const MIDDLE_ENGLISH: MCQ[] = [
  { id: 'ms-e-1', q: 'Which is a metaphor?', choices: ['He runs like a cheetah.', 'Time is a thief.', 'The clock ticked loudly.', 'She is faster than him.'], answer: 1, explanation: 'A metaphor states a direct equivalence ("time IS a thief") with no "like" or "as".', acCode: 'AC9E8LE05' },
  { id: 'ms-e-2', q: 'Iambic pentameter has how many syllables per line?', choices: ['8', '10', '12', '14'], answer: 1, explanation: 'Five iambs of two syllables each — Shakespeare’s sonnets follow this pattern.', acCode: 'AC9E9LE04' },
  { id: 'ms-e-3', q: 'A "protagonist" is the:', choices: ['Villain', 'Main character', 'Narrator only', 'Setting'], answer: 1, explanation: 'The protagonist is the central character whose story the text follows.', acCode: 'AC9E7LE02' },
  { id: 'ms-e-4', q: 'Shakespeare wrote primarily in which centuries?', choices: ['14th', '16th–17th', '18th', '19th'], answer: 1, explanation: 'Shakespeare worked in late Elizabethan and Jacobean England (c.1590–1613).', acCode: 'AC9E9LE01' },
  { id: 'ms-e-5', q: 'Which is alliteration?', choices: ['Buzz of bees', 'Sally sells seashells', 'Cold as ice', 'Time flies'], answer: 1, explanation: 'Alliteration repeats the same initial consonant sound across nearby words.', acCode: 'AC9E7LE05' },
  { id: 'ms-e-6', q: '"Bittersweet" is an example of:', choices: ['Hyperbole', 'Oxymoron', 'Personification', 'Pun'], answer: 1, explanation: 'An oxymoron combines two contradictory ideas (bitter + sweet).', acCode: 'AC9E9LE05' },
  { id: 'ms-e-7', q: 'Persuasive writing aims to:', choices: ['Entertain only', 'Describe a place', 'Convince the reader', 'Give instructions'], answer: 2, explanation: 'Persuasive texts use ethos, pathos and logos to influence the audience.', acCode: 'AC9E8LA01' },
  { id: 'ms-e-8', q: 'The first-person pronoun is:', choices: ['You', 'I', 'He', 'They'], answer: 1, explanation: '"I" is the first-person singular pronoun; "we" is first-person plural.', acCode: 'AC9E7LA03' },
  { id: 'ms-e-9', q: 'A "sonnet" has how many lines?', choices: ['10', '12', '14', '16'], answer: 2, explanation: 'A sonnet is a 14-line poem, often in iambic pentameter.', acCode: 'AC9E9LE04' },
  { id: 'ms-e-10', q: 'Pathos in persuasive writing means appealing to:', choices: ['Statistics', 'Emotions', 'Expert sources', 'Bullet points'], answer: 1, explanation: 'Pathos targets the audience’s feelings — fear, hope, anger, pride.', acCode: 'AC9E9LA01' },
  { id: 'ms-e-11', q: '"He could eat a horse" is an example of:', choices: ['Simile', 'Hyperbole', 'Metaphor', 'Pun'], answer: 1, explanation: 'Hyperbole exaggerates for effect.', acCode: 'AC9E7LE05' },
  { id: 'ms-e-12', q: 'The author of "Macbeth" is:', choices: ['Charles Dickens', 'William Shakespeare', 'Jane Austen', 'George Orwell'], answer: 1, explanation: 'Macbeth is one of Shakespeare’s "great tragedies", written c. 1606.', acCode: 'AC9E9LE01' },
  { id: 'ms-e-13', q: 'The "denouement" of a story is the:', choices: ['Climax', 'Setting', 'Resolution', 'Antagonist'], answer: 2, explanation: 'Denouement comes after the climax and ties up loose ends.', acCode: 'AC9E8LE02' },
  { id: 'ms-e-14', q: 'A "compound-complex sentence" has:', choices: ['One independent clause', 'Two independent and at least one dependent clause', 'Only dependent clauses', 'No clauses at all'], answer: 1, explanation: 'It combines compound (two independent) and complex (with a dependent clause) features.', acCode: 'AC9E8LA04' },
  { id: 'ms-e-15', q: '"To kill a mockingbird" was written by:', choices: ['Harper Lee', 'Mark Twain', 'Toni Morrison', 'F. Scott Fitzgerald'], answer: 0, explanation: 'Harper Lee’s 1960 novel is a staple of Australian secondary English study.', acCode: 'AC9E9LE01' },
  { id: 'ms-e-16', q: 'Ethos in persuasion appeals to:', choices: ['Emotion', 'Logic', 'Credibility / character', 'Style'], answer: 2, explanation: 'Ethos persuades by establishing the speaker as trustworthy or expert.', acCode: 'AC9E9LA01' },
  { id: 'ms-e-17', q: 'A "metaphor extended over many lines" is called:', choices: ['Conceit', 'Caesura', 'Allegory', 'Allusion'], answer: 0, explanation: 'A conceit is an elaborate, extended metaphor common in 17th-century poetry.', acCode: 'AC9E9LE05' },
  { id: 'ms-e-18', q: 'The "theme" of a text refers to:', choices: ['Setting', 'Central idea or message', 'Author bio', 'Front cover'], answer: 1, explanation: 'Theme is what a text says about life or human experience.', acCode: 'AC9E8LE02' },
  { id: 'ms-e-19', q: 'An "active voice" sentence puts the:', choices: ['Object before the verb', 'Subject performing the action', 'Verb at the end', 'Adjective first'], answer: 1, explanation: '"The cat chased the dog" is active; "The dog was chased by the cat" is passive.', acCode: 'AC9E8LA03' },
  { id: 'ms-e-20', q: 'Free verse poetry has:', choices: ['Strict rhyme and metre', 'No fixed pattern of rhyme or metre', 'Always 14 lines', 'Three stanzas only'], answer: 1, explanation: 'Free verse breaks from regular metrical structure; rhythm is shaped by imagery and breath.', acCode: 'AC9E9LE04' },
  { id: 'ms-e-21', q: '"Lord of the Flies" was written by:', choices: ['Aldous Huxley', 'William Golding', 'George Orwell', 'C.S. Lewis'], answer: 1, explanation: 'Golding’s 1954 allegory of boys stranded on an island is a Y9–10 staple.', acCode: 'AC9E9LE01' },
  { id: 'ms-e-22', q: 'The "voice" of a piece of writing refers to:', choices: ['Volume of speaking', 'The distinctive style of the writer or narrator', 'Pitch in a recording', 'Background music'], answer: 1, explanation: 'Voice is the personality readers hear in the writing.', acCode: 'AC9E8LE03' },
  { id: 'ms-e-23', q: 'A "dystopia" is:', choices: ['A perfect society', 'An imagined oppressive society', 'A type of poem', 'A historical period'], answer: 1, explanation: 'Dystopian fiction (1984, The Hunger Games) explores broken or oppressive futures.', acCode: 'AC9E9LE02' },
  { id: 'ms-e-24', q: 'The "Romantic" period in literature emphasised:', choices: ['Logic and order', 'Emotion and nature', 'Industry and machines', 'Mathematics'], answer: 1, explanation: 'Romantic poets like Wordsworth and Coleridge celebrated imagination, feeling and the natural world.', acCode: 'AC9E9LE01' },
  { id: 'ms-e-25', q: 'A "rhetorical question" is one that:', choices: ['Is asked to make a point, not to get an answer', 'Has only yes/no answers', 'Begins with how or why', 'Cannot be answered'], answer: 0, explanation: 'Rhetorical questions in persuasive writing engage readers without expecting a literal reply.', acCode: 'AC9E8LA01' },
];

const MIDDLE_MATHS: MCQ[] = [
  { id: 'ms-m-1', q: 'Solve for x: 2x + 5 = 17', choices: ['4', '5', '6', '7'], answer: 2, explanation: '17 − 5 = 12; 12 ÷ 2 = 6.', acCode: 'AC9M7A02' },
  { id: 'ms-m-2', q: 'Pythagoras: if a = 3, b = 4, then c = ?', choices: ['5', '6', '7', '12'], answer: 0, explanation: '3² + 4² = 9 + 16 = 25; √25 = 5.', acCode: 'AC9M9M03' },
  { id: 'ms-m-3', q: '15% of 200 = ?', choices: ['20', '25', '30', '35'], answer: 2, explanation: '10% = 20; 5% = 10; total 30.', acCode: 'AC9M7N06' },
  { id: 'ms-m-4', q: 'The gradient of y = 3x + 2 is:', choices: ['2', '3', '5', '−3'], answer: 1, explanation: 'In y = mx + c, m is the gradient and c is the y-intercept.', acCode: 'AC9M9A02' },
  { id: 'ms-m-5', q: '(−5) × (−4) = ?', choices: ['−20', '20', '−9', '9'], answer: 1, explanation: 'A negative times a negative gives a positive.', acCode: 'AC9M7N03' },
  { id: 'ms-m-6', q: 'Probability of rolling a 6 on a fair die:', choices: ['1/2', '1/3', '1/6', '1/12'], answer: 2, explanation: 'One favourable outcome out of six equally likely outcomes.', acCode: 'AC9M7P01' },
  { id: 'ms-m-7', q: 'Expand: 3(x + 4)', choices: ['3x + 4', '3x + 12', 'x + 12', '3x + 7'], answer: 1, explanation: 'Distributive law: 3 × x + 3 × 4 = 3x + 12.', acCode: 'AC9M7A01' },
  { id: 'ms-m-8', q: 'Mean of 4, 6, 8, 12, 20:', choices: ['8', '10', '12', '14'], answer: 1, explanation: 'Sum = 50; ÷ 5 = 10.', acCode: 'AC9M7ST01' },
  { id: 'ms-m-9', q: 'Volume of a cube with side 4cm:', choices: ['16 cm³', '32 cm³', '48 cm³', '64 cm³'], answer: 3, explanation: 'V = s³ = 4³ = 64.', acCode: 'AC9M8M02' },
  { id: 'ms-m-10', q: 'Which is irrational?', choices: ['0.5', '√2', '7', '−3/4'], answer: 1, explanation: '√2 cannot be expressed as a fraction of integers.', acCode: 'AC9M8N02' },
  { id: 'ms-m-11', q: 'Solve x² = 49:', choices: ['±7', '7 only', '24.5', '±6'], answer: 0, explanation: 'Both 7 and −7 squared give 49.', acCode: 'AC9M9A04' },
  { id: 'ms-m-12', q: '3:5 simplified is the same as:', choices: ['6:15', '6:10', '9:20', '15:25'], answer: 3, explanation: '15:25 both divide by 5 to give 3:5.', acCode: 'AC9M7N09' },
  { id: 'ms-m-13', q: 'A sector covering 90° of a circle is:', choices: ['1/2 the circle', '1/3 the circle', '1/4 the circle', '1/6 the circle'], answer: 2, explanation: '90/360 = 1/4.', acCode: 'AC9M8M01' },
  { id: 'ms-m-14', q: 'Surface area of a cube with side 5cm:', choices: ['50 cm²', '125 cm²', '150 cm²', '300 cm²'], answer: 2, explanation: '6 × (5×5) = 150 cm².', acCode: 'AC9M8M02' },
  { id: 'ms-m-15', q: 'The expanded form of (x+2)(x+3) is:', choices: ['x² + 5x + 6', 'x² + 6', 'x² + 5x + 5', 'x² + 6x + 6'], answer: 0, explanation: 'FOIL: x² + 3x + 2x + 6 = x² + 5x + 6.', acCode: 'AC9M9A01' },
  { id: 'ms-m-16', q: 'In a right triangle the side opposite the right angle is the:', choices: ['Adjacent', 'Opposite', 'Hypotenuse', 'Mean'], answer: 2, explanation: 'The hypotenuse is the longest side, opposite the 90° angle.', acCode: 'AC9M9M03' },
  { id: 'ms-m-17', q: 'Median of 3, 5, 8, 10, 12:', choices: ['5', '7.6', '8', '10'], answer: 2, explanation: 'For an odd count, the median is the middle value when ordered.', acCode: 'AC9M7ST01' },
  { id: 'ms-m-18', q: 'Solve 5x − 3 = 2x + 9:', choices: ['x = 2', 'x = 3', 'x = 4', 'x = 6'], answer: 2, explanation: '3x = 12; x = 4.', acCode: 'AC9M8A03' },
  { id: 'ms-m-19', q: 'Convert 0.6 to a fraction in simplest form:', choices: ['6/100', '3/5', '6/10', '2/3'], answer: 1, explanation: '6/10 simplifies to 3/5.', acCode: 'AC9M7N02' },
  { id: 'ms-m-20', q: 'Internal angles of a triangle sum to:', choices: ['90°', '180°', '270°', '360°'], answer: 1, explanation: 'A fundamental geometric fact: triangle angles always total 180°.', acCode: 'AC9M7SP02' },
  { id: 'ms-m-21', q: 'Probability of NOT rolling a 6 on a fair die:', choices: ['1/6', '1/2', '5/6', '6/6'], answer: 2, explanation: 'P(not 6) = 1 − 1/6 = 5/6.', acCode: 'AC9M8P01' },
  { id: 'ms-m-22', q: 'Area of a circle with radius 5 (use π ≈ 3.14):', choices: ['15.7', '31.4', '78.5', '157'], answer: 2, explanation: 'A = πr² = 3.14 × 25 = 78.5.', acCode: 'AC9M9M01' },
  { id: 'ms-m-23', q: 'Simplify: 2x + 3x − x', choices: ['4x', '5x', '6x', '2x'], answer: 0, explanation: 'Combine like terms: 2 + 3 − 1 = 4. So 4x.', acCode: 'AC9M7A01' },
  { id: 'ms-m-24', q: 'A linear equation in two variables graphs as a:', choices: ['Curve', 'Straight line', 'Parabola', 'Circle'], answer: 1, explanation: 'Equations of the form y = mx + c plot as straight lines.', acCode: 'AC9M9A02' },
  { id: 'ms-m-25', q: 'For data 2, 2, 3, 5, 7, the mode is:', choices: ['2', '3', '5', '3.8'], answer: 0, explanation: 'The mode is the most frequent value — 2 appears twice.', acCode: 'AC9M7ST01' },
];

const MIDDLE_HISTORY: MCQ[] = [
  { id: 'ms-h-1', q: 'The Western Roman Empire fell in approximately:', choices: ['476 AD', '1066 AD', '1492 AD', '800 AD'], answer: 0, explanation: 'Romulus Augustulus was deposed in 476, traditionally marking the end of the Western Empire.', acCode: 'AC9HH7K01' },
  { id: 'ms-h-2', q: 'The Black Death peaked in Europe during the:', choices: ['1100s', '1300s', '1500s', '1700s'], answer: 1, explanation: 'The plague killed perhaps a third of Europe between 1347 and 1351.', acCode: 'AC9HH8K01' },
  { id: 'ms-h-3', q: 'The Industrial Revolution began in:', choices: ['France', 'Germany', 'Britain', 'United States'], answer: 2, explanation: 'Mid-1700s Britain led with steam power, factories and textile mechanisation.', acCode: 'AC9HH9K01' },
  { id: 'ms-h-4', q: 'World War I began in:', choices: ['1912', '1914', '1916', '1918'], answer: 1, explanation: 'The war started after Archduke Franz Ferdinand was assassinated in June 1914.', acCode: 'AC9HH9K02' },
  { id: 'ms-h-5', q: 'The Gallipoli Campaign was in:', choices: ['1914', '1915', '1916', '1918'], answer: 1, explanation: 'Anzacs landed on 25 April 1915; the campaign ended in evacuation by January 1916.', acCode: 'AC9HH9K02' },
  { id: 'ms-h-6', q: 'Who led India to independence using non-violent resistance?', choices: ['Nehru', 'Mandela', 'Gandhi', 'Bose'], answer: 2, explanation: 'Mohandas Gandhi’s satyagraha campaigns helped end British rule in 1947.', acCode: 'AC9HH9K03' },
  { id: 'ms-h-7', q: 'The Magna Carta was signed in:', choices: ['1066', '1215', '1492', '1666'], answer: 1, explanation: 'King John signed at Runnymede, limiting royal power — a step toward modern rights.', acCode: 'AC9HH8K01' },
  { id: 'ms-h-8', q: 'The pharaohs ruled which ancient civilisation?', choices: ['Greece', 'Rome', 'Egypt', 'Persia'], answer: 2, explanation: 'Egyptian pharaohs ruled for over 3,000 years and built the pyramids.', acCode: 'AC9HH7K01' },
  { id: 'ms-h-9', q: 'Democracy was first developed in:', choices: ['Rome', 'Athens', 'Babylon', 'Persia'], answer: 1, explanation: 'Athenian direct democracy emerged in the 5th century BCE.', acCode: 'AC9HH7K01' },
  { id: 'ms-h-10', q: 'The Stolen Generations refers to:', choices: ['Gold rush thieves', 'Removal of Aboriginal children from their families', 'Lost colonial documents', 'Convicts who escaped'], answer: 1, explanation: 'Forcible removal policies operated from the early 1900s into the 1970s.', acCode: 'AC9HH9K04' },
  { id: 'ms-h-11', q: 'The Renaissance began in which country?', choices: ['France', 'Italy', 'England', 'Spain'], answer: 1, explanation: 'The cultural rebirth started in 14th-century Italian city-states like Florence.', acCode: 'AC9HH8K01' },
  { id: 'ms-h-12', q: 'WWI ended on:', choices: ['11 November 1918', '6 June 1944', '8 May 1945', '4 July 1776'], answer: 0, explanation: 'The Armistice was signed at 11am on 11 November 1918 — now Remembrance Day.', acCode: 'AC9HH9K02' },
  { id: 'ms-h-13', q: 'Confucianism originated in:', choices: ['India', 'China', 'Japan', 'Korea'], answer: 1, explanation: 'Confucius lived in China around 551–479 BCE and shaped Chinese ethics for millennia.', acCode: 'AC9HH7K01' },
  { id: 'ms-h-14', q: 'A "primary source" historian uses might be:', choices: ['A modern textbook', 'A 1915 soldier’s diary', 'A documentary made in 2020', 'An encyclopedia article'], answer: 1, explanation: 'Primary sources come from the time period being studied.', acCode: 'AC9HH7S03' },
  { id: 'ms-h-15', q: 'The Treaty of Versailles was signed in:', choices: ['1914', '1918', '1919', '1939'], answer: 2, explanation: 'Signed in 1919 to formally end WWI, it imposed harsh terms on Germany.', acCode: 'AC9HH9K02' },
  { id: 'ms-h-16', q: 'Who invaded Britain in 1066?', choices: ['Vikings', 'Romans', 'Normans', 'Spanish'], answer: 2, explanation: 'William of Normandy defeated King Harold at the Battle of Hastings.', acCode: 'AC9HH8K01' },
  { id: 'ms-h-17', q: 'The Eureka Stockade rebellion was about:', choices: ['Freedom for convicts', 'Miners’ rights on the goldfields', 'Women’s suffrage', 'Federation'], answer: 1, explanation: 'Ballarat miners revolted in 1854 against expensive mining licences and lack of vote.', acCode: 'AC9HH9K04' },
  { id: 'ms-h-18', q: 'The Mongol Empire was led at its peak by:', choices: ['Marco Polo', 'Kublai Khan', 'Genghis Khan', 'Tamerlane'], answer: 2, explanation: 'Genghis Khan unified the Mongols in 1206 and built history’s largest contiguous empire.', acCode: 'AC9HH8K01' },
  { id: 'ms-h-19', q: 'The Australian Federation united how many colonies?', choices: ['4', '5', '6', '7'], answer: 2, explanation: 'NSW, Victoria, Queensland, SA, WA and Tasmania united in 1901.', acCode: 'AC9HH9K04' },
  { id: 'ms-h-20', q: 'The Industrial Revolution led to widespread:', choices: ['Decline of cities', 'Urbanisation as people moved to factories', 'Return to subsistence farming', 'Increase in handicraft jobs'], answer: 1, explanation: 'Factories drew rural workers to fast-growing industrial cities.', acCode: 'AC9HH9K01' },
  { id: 'ms-h-21', q: 'The Crusades (11th–13th centuries) were primarily fought over:', choices: ['Trade routes only', 'Control of the Holy Land', 'Spice trade', 'Mediterranean piracy'], answer: 1, explanation: 'European Christians sought to retake Jerusalem from Muslim rule.', acCode: 'AC9HH8K01' },
  { id: 'ms-h-22', q: '"Pax Romana" means:', choices: ['Roman government', 'Roman peace', 'Roman warfare', 'Roman language'], answer: 1, explanation: 'A roughly 200-year period of relative peace beginning under Augustus.', acCode: 'AC9HH7K01' },
  { id: 'ms-h-23', q: 'The Russian Revolution was in:', choices: ['1905', '1914', '1917', '1922'], answer: 2, explanation: 'Bolsheviks led by Lenin overthrew the Provisional Government in October 1917.', acCode: 'AC9HH9K03' },
  { id: 'ms-h-24', q: 'A "watershed" event in history is one that:', choices: ['Has no impact', 'Marks a major turning point', 'Happened underwater', 'Lasted a single day'], answer: 1, explanation: 'Watershed events change the course of history (e.g. 1789 French Revolution).', acCode: 'AC9HH7S03' },
  { id: 'ms-h-25', q: 'Captain Cook’s ship was called:', choices: ['The Mayflower', 'HMS Endeavour', 'The Beagle', 'The Bounty'], answer: 1, explanation: 'Cook charted the east coast of Australia aboard HMS Endeavour in 1770.', acCode: 'AC9HH9K04' },
];

const MIDDLE_GEOGRAPHY: MCQ[] = [
  { id: 'ms-g-1', q: 'The Tropic of Capricorn passes through which Australian city?', choices: ['Sydney', 'Brisbane', 'Rockhampton', 'Hobart'], answer: 2, explanation: 'Rockhampton in Queensland sits almost exactly on the Tropic.', acCode: 'AC9HG7K02' },
  { id: 'ms-g-2', q: 'Which biome covers most of central Australia?', choices: ['Tropical rainforest', 'Desert', 'Tundra', 'Temperate forest'], answer: 1, explanation: 'The arid Outback covers about 70% of the continent.', acCode: 'AC9HG7K03' },
  { id: 'ms-g-3', q: 'The largest country by land area is:', choices: ['China', 'USA', 'Russia', 'Canada'], answer: 2, explanation: 'Russia covers over 17 million km² — almost twice Canada.', acCode: 'AC9HG8K02' },
  { id: 'ms-g-4', q: 'Tectonic plates moving apart create:', choices: ['Mountains', 'Volcanoes only', 'Rift valleys / mid-ocean ridges', 'Glaciers'], answer: 2, explanation: 'Divergent boundaries pull crust apart, forming rift valleys on land and ridges underwater.', acCode: 'AC9HG8K03' },
  { id: 'ms-g-5', q: 'The Amazon rainforest is mostly in:', choices: ['Africa', 'Brazil', 'India', 'Indonesia'], answer: 1, explanation: 'About 60% of the Amazon lies within Brazil.', acCode: 'AC9HG8K02' },
  { id: 'ms-g-6', q: 'Urbanisation means:', choices: ['Decline of cities', 'Movement to cities', 'Building national parks', 'Migration to farms'], answer: 1, explanation: 'Urbanisation is the rising share of people living in towns and cities.', acCode: 'AC9HG9K02' },
  { id: 'ms-g-7', q: 'The most populous country in 2024 is:', choices: ['China', 'India', 'USA', 'Indonesia'], answer: 1, explanation: 'India surpassed China around 2023 with over 1.4 billion people.', acCode: 'AC9HG9K02' },
  { id: 'ms-g-8', q: 'The Pacific "Ring of Fire" is known for:', choices: ['Fireworks', 'Volcanoes and earthquakes', 'Tropical storms', 'Oil reserves'], answer: 1, explanation: 'About 75% of the world’s volcanoes and most earthquakes occur along this rim.', acCode: 'AC9HG8K03' },
  { id: 'ms-g-9', q: 'A drainage basin is also called a:', choices: ['Catchment', 'Levee', 'Plateau', 'Delta'], answer: 0, explanation: 'A catchment is all the land where water drains into one river system.', acCode: 'AC9HG7K03' },
  { id: 'ms-g-10', q: 'Which gas is the largest contributor to human-driven climate change?', choices: ['Oxygen', 'Carbon dioxide', 'Nitrogen', 'Helium'], answer: 1, explanation: 'CO₂ from burning fossil fuels traps heat in the atmosphere.', acCode: 'AC9HG9K03' },
  { id: 'ms-g-11', q: 'Mt Kosciuszko is the highest peak in:', choices: ['Australia (mainland)', 'New Zealand', 'PNG', 'Tasmania'], answer: 0, explanation: 'Kosciuszko in NSW reaches 2,228 m — mainland Australia’s highest mountain.', acCode: 'AC9HG7K02' },
  { id: 'ms-g-12', q: 'Renewable resources include:', choices: ['Coal', 'Wind and solar', 'Oil', 'Natural gas'], answer: 1, explanation: 'Wind and sunlight replenish naturally on short human timescales.', acCode: 'AC9HG7K04' },
  { id: 'ms-g-13', q: 'A "monsoon" is:', choices: ['A small mountain', 'A seasonal wind bringing rain', 'A type of desert', 'An ocean current'], answer: 1, explanation: 'Monsoon winds shift with the seasons and drive wet/dry cycles across South Asia and northern Australia.', acCode: 'AC9HG7K02' },
  { id: 'ms-g-14', q: 'Bushfire risk in Australia is highest during:', choices: ['Winter', 'Spring rains', 'Hot, dry summer', 'Autumn cool snaps'], answer: 2, explanation: 'High temperatures, low humidity and strong winds peak in summer.', acCode: 'AC9HG8K03' },
  { id: 'ms-g-15', q: 'Population density is people per:', choices: ['Kilometre', 'Hectare or km²', 'Suburb', 'Continent'], answer: 1, explanation: 'Density measures how crowded an area is — people divided by area.', acCode: 'AC9HG9K02' },
  { id: 'ms-g-16', q: 'A "drainage divide" is:', choices: ['A water meter', 'A line separating catchments', 'A type of dam', 'A flood barrier'], answer: 1, explanation: 'Divides — often along mountain ranges — separate where water flows to different river systems.', acCode: 'AC9HG7K03' },
  { id: 'ms-g-17', q: 'The Three Gorges Dam is in:', choices: ['India', 'China', 'Brazil', 'Egypt'], answer: 1, explanation: 'The world’s largest hydroelectric dam, on China’s Yangtze River.', acCode: 'AC9HG8K02' },
  { id: 'ms-g-18', q: '"Push factors" in migration include:', choices: ['Higher pay overseas', 'War and persecution', 'Better climate', 'Family reunion'], answer: 1, explanation: 'Push factors drive people away — pull factors draw them somewhere new.', acCode: 'AC9HG9K02' },
  { id: 'ms-g-19', q: 'The Bay of Bengal lies between India and:', choices: ['Sri Lanka and Bangladesh', 'Iran and Afghanistan', 'Russia and Mongolia', 'Madagascar'], answer: 0, explanation: 'The Bay sits east of India, bordered by Bangladesh to the north and Sri Lanka to the south.', acCode: 'AC9HG8K02' },
  { id: 'ms-g-20', q: 'Coral reefs are vulnerable to:', choices: ['Heavy snow', 'Ocean warming and acidification', 'Sandstorms', 'Cold currents'], answer: 1, explanation: 'Bleaching from warmer water and chemistry shifts threaten coral globally.', acCode: 'AC9HG9K03' },
  { id: 'ms-g-21', q: 'An "isohyet" line on a map joins points with the same:', choices: ['Temperature', 'Rainfall amount', 'Elevation', 'Population'], answer: 1, explanation: 'Isohyets show rainfall patterns; isotherms show temperature; contours show elevation.', acCode: 'AC9HG7S02' },
  { id: 'ms-g-22', q: 'Indonesia consists of how many islands (approximately)?', choices: ['1,700', '17,000', '170,000', '170'], answer: 1, explanation: 'Indonesia is the world’s largest archipelago with around 17,000 islands.', acCode: 'AC9HG8K02' },
  { id: 'ms-g-23', q: '"Liveability" indicators include:', choices: ['Stock prices only', 'Safety, health care, education, environment', 'Currency value', 'Length of border'], answer: 1, explanation: 'Surveys like the EIU Liveability Index measure several quality-of-life domains.', acCode: 'AC9HG7K03' },
  { id: 'ms-g-24', q: 'A "delta" forms at the:', choices: ['Source of a river', 'Mouth of a river', 'Middle of a river', 'Highest mountain'], answer: 1, explanation: 'Sediment dropped where a river meets a sea or lake builds a fan-shaped delta.', acCode: 'AC9HG7K03' },
  { id: 'ms-g-25', q: 'Australia’s closest large neighbour is:', choices: ['China', 'Indonesia', 'USA', 'India'], answer: 1, explanation: 'Indonesia’s southern islands lie just over the Timor Sea.', acCode: 'AC9HG8K02' },
];

const MIDDLE_SCIENCE: MCQ[] = [
  { id: 'ms-s-1', q: 'The basic unit of life is the:', choices: ['Atom', 'Cell', 'Tissue', 'Organ'], answer: 1, explanation: 'All living things are made of one or more cells.', acCode: 'AC9S8U01' },
  { id: 'ms-s-2', q: 'Water boils at:', choices: ['50°C', '100°C', '212°C', '120°C'], answer: 1, explanation: 'At standard atmospheric pressure, water boils at 100°C.', acCode: 'AC9S7U02' },
  { id: 'ms-s-3', q: 'The chemical symbol for gold is:', choices: ['Go', 'Gd', 'Au', 'Ag'], answer: 2, explanation: 'Au comes from the Latin "aurum". Ag is silver.', acCode: 'AC9S8U02' },
  { id: 'ms-s-4', q: 'Plate tectonics describes:', choices: ['Wind patterns', 'The movement of Earth’s crust', 'Ocean tides', 'Magnetic storms'], answer: 1, explanation: 'Earth’s lithosphere is broken into plates that slide, collide and pull apart.', acCode: 'AC9S9U03' },
  { id: 'ms-s-5', q: 'A "balanced" chemical equation has:', choices: ['Different atoms on each side', 'The same atoms on both sides', 'More atoms on the right', 'Only reactants'], answer: 1, explanation: 'Conservation of mass — atoms aren’t created or destroyed in a reaction.', acCode: 'AC9S9U02' },
  { id: 'ms-s-6', q: 'Newton’s First Law states that an object will:', choices: ['Always slow down', 'Stay still or keep moving unless a force acts on it', 'Speed up over time', 'Fall up'], answer: 1, explanation: 'The law of inertia — no net force, no change in motion.', acCode: 'AC9S9U02' },
  { id: 'ms-s-7', q: 'DNA stands for:', choices: ['Diatomic Neutron Atom', 'Deoxyribonucleic Acid', 'Direct Natural Atom', 'Dual Nuclear Acid'], answer: 1, explanation: 'DNA is the molecule that stores genetic information.', acCode: 'AC9S8U01' },
  { id: 'ms-s-8', q: 'A "compound" is made of:', choices: ['One element', 'Two or more elements chemically bonded', 'Atoms with no bonds', 'Only metals'], answer: 1, explanation: 'Water (H₂O) is a compound of hydrogen and oxygen.', acCode: 'AC9S8U02' },
  { id: 'ms-s-9', q: 'Photosynthesis converts:', choices: ['Heat to electricity', 'Sunlight, CO₂ and water into glucose and oxygen', 'Sugar into starch', 'Carbon into diamond'], answer: 1, explanation: 'Plants capture light energy and store it in chemical bonds.', acCode: 'AC9S8U01' },
  { id: 'ms-s-10', q: 'An "acid" has a pH:', choices: ['Below 7', 'Of 7', 'Above 7', 'Of 14 only'], answer: 0, explanation: 'pH below 7 is acidic; above 7 is alkaline; 7 is neutral.', acCode: 'AC9S9U02' },
  { id: 'ms-s-11', q: 'Energy is measured in:', choices: ['Newtons', 'Pascals', 'Joules', 'Watts'], answer: 2, explanation: 'The joule is the SI unit of energy. Watts measure power (energy per second).', acCode: 'AC9S8U03' },
  { id: 'ms-s-12', q: 'Mitosis produces:', choices: ['Four gamete cells', 'Two genetically identical cells', 'A single sex cell', 'No cells'], answer: 1, explanation: 'Mitosis is body-cell division — two diploid daughter cells.', acCode: 'AC9S9U01' },
  { id: 'ms-s-13', q: 'The Periodic Table is arranged by:', choices: ['Atomic mass only', 'Atomic number', 'Date discovered', 'Density'], answer: 1, explanation: 'Atomic number (protons in the nucleus) governs the ordering.', acCode: 'AC9S8U02' },
  { id: 'ms-s-14', q: 'Sound travels fastest through:', choices: ['Air', 'Water', 'Steel', 'A vacuum'], answer: 2, explanation: 'Sound waves move faster through denser, more elastic solids.', acCode: 'AC9S7U03' },
  { id: 'ms-s-15', q: 'A neutron has charge:', choices: ['+1', '−1', '0', 'It depends'], answer: 2, explanation: 'Neutrons are electrically neutral; protons +1; electrons −1.', acCode: 'AC9S8U02' },
  { id: 'ms-s-16', q: 'An "ecosystem" includes:', choices: ['Only animals', 'Living things and their physical environment', 'Only plants', 'Only the soil'], answer: 1, explanation: 'Ecosystems link biota with abiotic factors like sunlight, water and nutrients.', acCode: 'AC9S7U01' },
  { id: 'ms-s-17', q: 'A "control variable" in an experiment is:', choices: ['What you change', 'What you measure', 'What you keep the same', 'A wild guess'], answer: 2, explanation: 'Controlled variables stay constant so only the independent variable affects the result.', acCode: 'AC9S7I02' },
  { id: 'ms-s-18', q: 'Visible light is part of the:', choices: ['Sound spectrum', 'Electromagnetic spectrum', 'Periodic table', 'Tectonic plate', ], answer: 1, explanation: 'Visible light sits between UV and infrared on the EM spectrum.', acCode: 'AC9S9U02' },
  { id: 'ms-s-19', q: 'Plant cells have a structure that animal cells don’t — the:', choices: ['Nucleus', 'Mitochondrion', 'Cell wall', 'Cytoplasm'], answer: 2, explanation: 'Plant cell walls (cellulose) provide rigidity and shape.', acCode: 'AC9S8U01' },
  { id: 'ms-s-20', q: 'Speed = distance ÷ ?', choices: ['Mass', 'Time', 'Force', 'Energy'], answer: 1, explanation: 'Speed is how much distance is covered per unit of time.', acCode: 'AC9S9U02' },
  { id: 'ms-s-21', q: 'A "compound" is broken down by:', choices: ['Physical change only', 'A chemical reaction', 'Filtering', 'Magnets'], answer: 1, explanation: 'Compounds are chemically bonded; you need a reaction to split them into elements.', acCode: 'AC9S9U02' },
  { id: 'ms-s-22', q: 'Earthquakes are measured on the:', choices: ['Mercalli & Richter / moment magnitude scales', 'Beaufort scale', 'Celsius scale', 'pH scale'], answer: 0, explanation: 'Mercalli measures perceived intensity; moment magnitude measures the energy released.', acCode: 'AC9S9U03' },
  { id: 'ms-s-23', q: 'The "biosphere" includes:', choices: ['All life on Earth', 'Just the atmosphere', 'Just oceans', 'The moon'], answer: 0, explanation: 'The biosphere is the global zone where life exists — air, land and water combined.', acCode: 'AC9S7U01' },
  { id: 'ms-s-24', q: 'In an electrical circuit, voltage is measured in:', choices: ['Amps', 'Ohms', 'Volts', 'Watts'], answer: 2, explanation: 'Voltage (V) is the electrical "push" — current (A) flows because of it.', acCode: 'AC9S9U02' },
  { id: 'ms-s-25', q: 'The Big Bang theory describes:', choices: ['How Earth formed', 'The origin of the Universe', 'Volcanic eruptions', 'Earthquakes'], answer: 1, explanation: 'The Universe began expanding from a hot, dense state about 13.8 billion years ago.', acCode: 'AC9S7U04' },
];

