const SENIOR_ENGLISH: MCQ[] = [
  { id: 'ss-e-1', q: 'A "bildungsroman" is a story about:', choices: ['A detective', 'Coming of age', 'A war', 'A romance only'], answer: 1, explanation: 'Bildungsroman traces moral and psychological growth from youth to adulthood.', acCode: 'AC9E10LE02' },
  { id: 'ss-e-2', q: 'Aristotle’s three rhetorical appeals are:', choices: ['Logos, pathos, ethos', 'Story, plot, theme', 'Hero, villain, helper', 'Past, present, future'], answer: 0, explanation: 'Logos (logic), pathos (emotion), ethos (credibility) underpin classical rhetoric.', acCode: 'AC9E10LA01' },
  { id: 'ss-e-3', q: '"The Great Gatsby" was written by:', choices: ['Hemingway', 'F. Scott Fitzgerald', 'Faulkner', 'Steinbeck'], answer: 1, explanation: 'Fitzgerald’s 1925 novel is a Senior English staple.', acCode: 'AC9E10LE01', unit: 1 },
  { id: 'ss-e-4', q: '"Synecdoche" is when:', choices: ['Two opposites combine', 'A part represents the whole (or vice versa)', 'Two ideas contrast', 'A word imitates a sound'], answer: 1, explanation: '"All hands on deck" — hands stands for sailors.', acCode: 'AC9E10LE05' },
  { id: 'ss-e-5', q: '"Stream of consciousness" is most associated with:', choices: ['Hemingway', 'James Joyce', 'Tolkien', 'Twain'], answer: 1, explanation: 'Joyce’s "Ulysses" (1922) is a defining modernist example.', acCode: 'AC9E10LE03' },
  { id: 'ss-e-6', q: 'The "unreliable narrator" technique means:', choices: ['The plot is wrong', 'The narrator’s account may be distorted', 'No narrator is present', 'The story is non-fiction'], answer: 1, explanation: 'Readers must read against the grain of the narration — e.g. in "Lolita" or "Gone Girl".', acCode: 'AC9E10LE02' },
  { id: 'ss-e-7', q: 'A "denouement" is the:', choices: ['Opening conflict', 'Climax', 'Resolution', 'Setting'], answer: 2, explanation: 'Denouement (French for "untying") resolves the narrative’s tensions.', acCode: 'AC9E10LE02' },
  { id: 'ss-e-8', q: '"Beware the ides of March" appears in:', choices: ['Hamlet', 'Macbeth', 'Julius Caesar', 'Othello'], answer: 2, explanation: 'The Soothsayer’s warning to Caesar in Shakespeare’s "Julius Caesar".', acCode: 'AC9E10LE01' },
  { id: 'ss-e-9', q: 'Modernist literature largely emerged in the:', choices: ['1700s', '1800s', 'Early 1900s', '1980s'], answer: 2, explanation: 'Modernism rose after WWI — Eliot’s "The Waste Land" (1922), Woolf, Joyce.', acCode: 'AC9E10LE03', unit: 2 },
  { id: 'ss-e-10', q: '"Ad hominem" is a logical fallacy that:', choices: ['Cites tradition', 'Attacks the person, not the argument', 'Uses circular reasoning', 'Presents a false dichotomy'], answer: 1, explanation: 'Ad hominem dodges the argument by going after the speaker’s character.', acCode: 'AC9E10LA01' },
  { id: 'ss-e-11', q: 'The "tragic flaw" of a hero is also called:', choices: ['Hubris', 'Hamartia', 'Catharsis', 'Pathos'], answer: 1, explanation: 'Hamartia is Aristotle’s term; hubris (excessive pride) is one common form.', acCode: 'AC9E10LE04' },
  { id: 'ss-e-12', q: 'A "thesis statement" should be:', choices: ['A question', 'A specific arguable claim', 'A summary of the topic', 'A neutral fact'], answer: 1, explanation: 'A thesis takes a debatable position the essay then defends with evidence.', acCode: 'AC9E10LA01' },
  { id: 'ss-e-13', q: 'Postmodern texts often feature:', choices: ['Linear plots', 'Metafiction and intertextuality', 'Reliable narrators only', 'Single perspectives'], answer: 1, explanation: 'Postmodern fiction self-references and plays with other texts (e.g. Calvino, Atwood).', acCode: 'AC9E10LE03', unit: 3 },
  { id: 'ss-e-14', q: '"Iambic pentameter" describes a line of:', choices: ['Five iambs (ten syllables) of unstressed-stressed', 'Six trochees', 'Three anapests', 'Four spondees'], answer: 0, explanation: 'Shakespearean blank verse runs in iambic pentameter — da-DUM × 5.', acCode: 'AC9E10LE04' },
  { id: 'ss-e-15', q: '"To Kill a Mockingbird" examines:', choices: ['Climate change', 'Racism in 1930s American South', 'Renaissance art', 'WWII Russia'], answer: 1, explanation: 'Lee’s novel uses Scout’s perspective to explore prejudice and conscience.', acCode: 'AC9E10LE02' },
  { id: 'ss-e-16', q: '"Catharsis" in tragedy refers to:', choices: ['Comic relief', 'Emotional release in the audience', 'A plot twist', 'A change of setting'], answer: 1, explanation: 'Aristotle described tragedy as purging pity and fear in the audience.', acCode: 'AC9E10LE04' },
  { id: 'ss-e-17', q: '"Allegory" is:', choices: ['A direct comparison', 'A narrative with a deeper symbolic meaning', 'A one-line joke', 'A type of metaphor'], answer: 1, explanation: 'Animal Farm is an allegory of the Russian Revolution.', acCode: 'AC9E10LE05' },
  { id: 'ss-e-18', q: 'Margaret Atwood’s "The Handmaid’s Tale" is a:', choices: ['Romance', 'Dystopian novel', 'Memoir', 'Historical biography'], answer: 1, explanation: 'Atwood’s 1985 novel explores theocratic dystopia and women’s rights.', acCode: 'AC9E10LE01', unit: 2 },
  { id: 'ss-e-19', q: 'A "syllogism" is:', choices: ['A type of poem', 'A deductive argument with two premises and a conclusion', 'A rhetorical question', 'A fallacy'], answer: 1, explanation: 'All humans are mortal; Socrates is human; therefore Socrates is mortal.', acCode: 'AC9E10LA01' },
  { id: 'ss-e-20', q: 'Modernist poet T.S. Eliot wrote:', choices: ['"The Waste Land"', '"Paradise Lost"', '"Beowulf"', '"The Canterbury Tales"'], answer: 0, explanation: 'Eliot’s 1922 fragmentary poem is a key modernist text.', acCode: 'AC9E10LE01' },
  { id: 'ss-e-21', q: '"Foreshadowing" is when a text:', choices: ['Concludes the story', 'Hints at events to come', 'Repeats earlier scenes', 'Lists characters'], answer: 1, explanation: 'Foreshadowing builds anticipation by planting clues.', acCode: 'AC9E10LE02' },
  { id: 'ss-e-22', q: '"Pastiche" means:', choices: ['Original work in a fresh genre', 'Imitating the style of other writers or texts', 'A short poem', 'A literary award'], answer: 1, explanation: 'Pastiche borrows another’s manner, often respectfully — common in postmodern writing.', acCode: 'AC9E10LE03' },
  { id: 'ss-e-23', q: 'A "didactic" text aims to:', choices: ['Entertain only', 'Teach a moral or instruct', 'Confuse the reader', 'Stay neutral'], answer: 1, explanation: 'Didactic works (fables, religious parables) carry an explicit lesson.', acCode: 'AC9E10LE05' },
  { id: 'ss-e-24', q: 'A "soliloquy" is:', choices: ['A duet between characters', 'A character speaking thoughts aloud, alone on stage', 'A stage direction', 'A chorus line'], answer: 1, explanation: 'Hamlet’s "To be or not to be" is the most famous soliloquy in English.', acCode: 'AC9E10LE04' },
  { id: 'ss-e-25', q: 'A "feminist reading" of a text might focus on:', choices: ['Plant imagery', 'How gender, power and women’s experience are represented', 'Sentence length', 'Rhyme scheme'], answer: 1, explanation: 'Feminist criticism examines representation, voice and ideology relating to gender.', acCode: 'AC9E10LE05', unit: 3 },
];

const SENIOR_MATHS: MCQ[] = [
  { id: 'ss-m-1', q: 'Derivative of x³:', choices: ['x²', '3x²', '3x', 'x³/3'], answer: 1, explanation: 'd/dx(x^n) = n·x^(n−1).', unit: 3 },
  { id: 'ss-m-2', q: 'sin(90°) = ?', choices: ['0', '0.5', '1', '√2/2'], answer: 2, explanation: 'At 90°, the sine reaches its maximum of 1.' },
  { id: 'ss-m-3', q: 'Quadratic formula solves ax² + bx + c = 0; x = ?', choices: ['(−b ± √(b²−4ac)) / 2a', '−b / a', 'b² − 4ac', 'c / (a + b)'], answer: 0, explanation: 'Works for any quadratic; the discriminant b²−4ac tells you the nature of the roots.', acCode: 'AC9M10A05' },
  { id: 'ss-m-4', q: 'log₁₀(1000) = ?', choices: ['1', '2', '3', '10'], answer: 2, explanation: '10³ = 1000, so log base 10 of 1000 is 3.', unit: 2 },
  { id: 'ss-m-5', q: 'Integral of 2x dx:', choices: ['x² + C', '2 + C', 'x + C', 'x²/2 + C'], answer: 0, explanation: 'Power rule for integration: ∫2x dx = x² + C.', unit: 3 },
  { id: 'ss-m-6', q: 'Probability of two independent events both occurring:', choices: ['P(A) + P(B)', 'P(A) × P(B)', 'P(A) − P(B)', 'P(A)/P(B)'], answer: 1, explanation: 'Multiplication rule for independent events.', acCode: 'AC9M10P01', unit: 1 },
  { id: 'ss-m-7', q: 'cos²(θ) + sin²(θ) = ?', choices: ['0', 'θ', '1', '2'], answer: 2, explanation: 'Pythagorean trig identity — fundamental.', unit: 1 },
  { id: 'ss-m-8', q: 'For y = e^x, dy/dx = ?', choices: ['x', '1', 'e^x', 'ln(x)'], answer: 2, explanation: 'The natural exponential is its own derivative.', unit: 3 },
  { id: 'ss-m-9', q: 'Number of permutations of 5 distinct items:', choices: ['25', '120', '60', '720'], answer: 1, explanation: '5! = 5 × 4 × 3 × 2 × 1 = 120.', unit: 2 },
  { id: 'ss-m-10', q: 'Standard deviation measures:', choices: ['The mean', 'The spread of data', 'The mode', 'The maximum'], answer: 1, explanation: 'σ quantifies how far values typically deviate from the mean.', acCode: 'AC9M10ST02' },
  { id: 'ss-m-11', q: 'A vector in 3D has how many components?', choices: ['1', '2', '3', '4'], answer: 2, explanation: 'A 3D vector has x, y and z components.', unit: 1 },
  { id: 'ss-m-12', q: 'The complex number i is defined by:', choices: ['i = 1', 'i = −1', 'i² = −1', 'i² = 1'], answer: 2, explanation: 'i² = −1 is the foundation of complex numbers (Specialist Maths).', unit: 1 },
  { id: 'ss-m-13', q: 'In a normal distribution, ~68% of data lies within:', choices: ['1 SD of the mean', '2 SD of the mean', '3 SD of the mean', 'The mean exactly'], answer: 0, explanation: 'The 68–95–99.7 rule for normal distributions.', acCode: 'AC9M10ST02', unit: 4 },
  { id: 'ss-m-14', q: 'The compound interest formula is:', choices: ['A = P(1 + rt)', 'A = P(1 + r/n)^(nt)', 'A = Pe^(rt) only', 'A = P − rt'], answer: 1, explanation: 'Compound interest grows by powers of the period rate; simple interest is linear (A = P(1+rt)).', acCode: 'AC9M10N01', unit: 2 },
  { id: 'ss-m-15', q: 'tan(45°) = ?', choices: ['0', '1/2', '1', '√3'], answer: 2, explanation: 'At 45°, sine and cosine are equal, so tan = 1.' },
  { id: 'ss-m-16', q: 'A function f(x) = 1/x is undefined at:', choices: ['x = 1', 'x = 0', 'x = −1', 'x = ∞'], answer: 1, explanation: 'Division by zero is undefined — there’s a vertical asymptote at x = 0.', unit: 1 },
  { id: 'ss-m-17', q: 'For data 4, 6, 6, 7, 12, the median is:', choices: ['6', '7', '8', '12'], answer: 0, explanation: 'Middle value of an ordered list of five numbers is the third one — 6.', acCode: 'AC9M10ST01' },
  { id: 'ss-m-18', q: '∫ 1/x dx =', choices: ['x + C', 'ln|x| + C', '1/(x²) + C', 'e^x + C'], answer: 1, explanation: 'A standard integral every Methods student memorises.', unit: 3 },
  { id: 'ss-m-19', q: 'In a binomial distribution, "n choose k" counts the:', choices: ['Number of trials', 'Probability of success', 'Number of ways to pick k from n', 'Mean'], answer: 2, explanation: 'Combinations: C(n, k) = n! / (k!(n−k)!).', unit: 2 },
  { id: 'ss-m-20', q: 'A "stationary point" of f(x) is where:', choices: ['f(x) = 0', "f'(x) = 0", "f''(x) = 0", 'f(x) is undefined'], answer: 1, explanation: 'Derivative is zero — could be a maximum, minimum or point of inflection.', unit: 3 },
  { id: 'ss-m-21', q: '"Pearson’s r" measures:', choices: ['Probability of an event', 'Strength of linear correlation', 'Median', 'Mode'], answer: 1, explanation: 'r ranges from −1 to 1; near ±1 means a strong linear relationship.', acCode: 'AC9M10ST02', unit: 4 },
  { id: 'ss-m-22', q: 'The geometric mean of 4 and 9:', choices: ['5', '6', '6.5', '13'], answer: 1, explanation: '√(4 × 9) = √36 = 6.', acCode: 'AC9M10ST01' },
  { id: 'ss-m-23', q: 'Solve for x: 2^x = 32', choices: ['3', '4', '5', '6'], answer: 2, explanation: '2^5 = 32. (Equivalent to log₂(32) = 5.)', acCode: 'AC9M10A04' },
  { id: 'ss-m-24', q: 'Cross product of vectors a × b is:', choices: ['A scalar', 'A vector perpendicular to both a and b', 'Always zero', 'The dot product'], answer: 1, explanation: 'Cross product is a 3D operation producing a perpendicular vector — Specialist Maths.', unit: 3 },
  { id: 'ss-m-25', q: 'In hypothesis testing, "p < 0.05" usually means:', choices: ['Result is certain', 'Null hypothesis is rejected at 5% significance', 'Sample is too small', 'Test failed'], answer: 1, explanation: 'A p-value below 0.05 is conventionally treated as statistically significant evidence against the null.', unit: 4 },
];

const SENIOR_HISTORY: MCQ[] = [
  { id: 'ss-h-1', q: 'The Russian Revolution occurred in:', choices: ['1905', '1917', '1929', '1945'], answer: 1, explanation: 'The February and October revolutions of 1917 ended Tsarist rule and brought the Bolsheviks to power.', acCode: 'AC9HH10K02' },
  { id: 'ss-h-2', q: 'The Treaty of Versailles ended:', choices: ['World War I', 'World War II', 'The Cold War', 'The Vietnam War'], answer: 0, explanation: 'Signed in 1919, it imposed harsh reparations on Germany and reshaped Europe.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-3', q: 'The Cold War was primarily between:', choices: ['USA & UK', 'USSR & China', 'USA & USSR', 'France & Germany'], answer: 2, explanation: 'A geopolitical and ideological stand-off lasting roughly 1947–1991.', acCode: 'AC9HH10K03' },
  { id: 'ss-h-4', q: 'The Berlin Wall fell in:', choices: ['1969', '1979', '1989', '1999'], answer: 2, explanation: 'On 9 November 1989 — symbolically ending the Cold War in Europe.', acCode: 'AC9HH10K03' },
  { id: 'ss-h-5', q: 'Apartheid in South Africa officially ended in:', choices: ['1976', '1985', '1991', '2001'], answer: 2, explanation: 'Legal apartheid was dismantled in 1991; Mandela was elected president in 1994.', acCode: 'AC9HH10K04', unit: 2 },
  { id: 'ss-h-6', q: 'The 1967 Australian referendum recognised:', choices: ['Decimal currency', 'Aboriginal people in the census', 'Capital change', 'New national anthem'], answer: 1, explanation: '90%+ said yes to counting First Nations peoples and allowing federal laws for them.', acCode: 'AC9HH10K04' },
  { id: 'ss-h-7', q: 'The Mabo decision (1992) overturned the doctrine of:', choices: ['Terra nullius', 'Eminent domain', 'Habeas corpus', 'Res judicata'], answer: 0, explanation: 'Terra nullius — "land belonging to no one" — was the legal fiction underlying British claims.', acCode: 'AC9HH10K04' },
  { id: 'ss-h-8', q: 'The Universal Declaration of Human Rights was adopted in:', choices: ['1918', '1945', '1948', '1968'], answer: 2, explanation: 'The UN General Assembly adopted the UDHR in December 1948.', acCode: 'AC9HH10K03' },
  { id: 'ss-h-9', q: 'Australian combat troops withdrew from Vietnam in:', choices: ['1965', '1972', '1975', '1980'], answer: 1, explanation: 'Whitlam ended Australian combat involvement in 1972.', acCode: 'AC9HH10K02', unit: 1 },
  { id: 'ss-h-10', q: 'Decolonisation in Africa peaked during the:', choices: ['1920s', '1940s', '1960s', '1980s'], answer: 2, explanation: 'Most African nations gained independence in the 1960s.', acCode: 'AC9HH10K03', unit: 2 },
  { id: 'ss-h-11', q: 'The Holocaust killed approximately:', choices: ['600,000 Jews', '6 million Jews', '60 million Jews', '600 million Jews'], answer: 1, explanation: 'Nazi Germany systematically murdered approximately 6 million European Jews.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-12', q: 'The Cuban Missile Crisis happened in:', choices: ['1956', '1962', '1968', '1975'], answer: 1, explanation: 'October 1962 — the closest the world came to nuclear war.', acCode: 'AC9HH10K03', unit: 3 },
  { id: 'ss-h-13', q: 'Pearl Harbor was attacked on:', choices: ['7 December 1941', '6 June 1944', '11 November 1918', '1 September 1939'], answer: 0, explanation: 'Japan’s surprise attack brought the USA into WWII.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-14', q: 'The Nuremberg Trials prosecuted:', choices: ['Soviet defectors', 'Nazi war criminals', 'Japanese emperors', 'British generals'], answer: 1, explanation: 'Held 1945–46 — established the principle of crimes against humanity.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-15', q: 'The Vietnam War involved Australia from:', choices: ['1962 to 1972', '1939 to 1945', '1950 to 1953', '1979 to 1989'], answer: 0, explanation: 'Australia first sent advisors in 1962 and withdrew combat troops by 1972.', acCode: 'AC9HH10K02' },
  { id: 'ss-h-16', q: 'The 1948 Israeli War followed:', choices: ['Yalta Conference', 'UN Partition Plan for Palestine', 'Versailles Treaty', 'Sykes-Picot Agreement'], answer: 1, explanation: 'The UN’s 1947 partition plan led directly to the 1948 Arab–Israeli War.', acCode: 'AC9HH10K03', unit: 4 },
  { id: 'ss-h-17', q: 'The "Iron Curtain" speech was given by:', choices: ['Roosevelt', 'Churchill', 'Stalin', 'Truman'], answer: 1, explanation: 'Churchill’s 1946 Fulton speech named the Cold War divide.', acCode: 'AC9HH10K03' },
  { id: 'ss-h-18', q: 'The Vietnam Tet Offensive was in:', choices: ['1965', '1968', '1973', '1975'], answer: 1, explanation: 'The 1968 offensive shifted American public opinion against the war.', acCode: 'AC9HH10K02', unit: 3 },
  { id: 'ss-h-19', q: 'The Whitlam government was dismissed in:', choices: ['1972', '1975', '1983', '1991'], answer: 1, explanation: 'Governor-General Sir John Kerr dismissed PM Whitlam on 11 November 1975 — Australia’s constitutional crisis.', acCode: 'AC9HH10K04', unit: 4 },
  { id: 'ss-h-20', q: 'The League of Nations was replaced by the:', choices: ['Warsaw Pact', 'United Nations', 'NATO', 'European Union'], answer: 1, explanation: 'The UN was founded in 1945 after the League failed to prevent WWII.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-21', q: 'The Apology to the Stolen Generations was delivered in:', choices: ['2000', '2005', '2008', '2013'], answer: 2, explanation: 'PM Kevin Rudd apologised in Parliament on 13 February 2008.', acCode: 'AC9HH10K04' },
  { id: 'ss-h-22', q: 'Mao Zedong proclaimed the People’s Republic of China in:', choices: ['1945', '1949', '1956', '1976'], answer: 1, explanation: 'After defeating the Nationalists, Mao founded the PRC on 1 October 1949.', acCode: 'AC9HH10K03', unit: 3 },
  { id: 'ss-h-23', q: 'The Nuremberg Laws (1935) targeted:', choices: ['Trade unions', 'Jewish citizens of Germany', 'Communists', 'Catholic clergy'], answer: 1, explanation: 'Nazi race laws stripped Jewish Germans of citizenship and forbade certain marriages.', acCode: 'AC9HH10K01' },
  { id: 'ss-h-24', q: 'The Civil Rights Act in the USA passed in:', choices: ['1954', '1964', '1972', '1980'], answer: 1, explanation: 'The 1964 Civil Rights Act outlawed segregation and discrimination in the USA.', acCode: 'AC9HH10K03', unit: 2 },
  { id: 'ss-h-25', q: 'The Sydney Olympics were held in:', choices: ['1996', '2000', '2004', '2008'], answer: 1, explanation: 'Sydney hosted the Games of the new millennium in September 2000.', acCode: 'AC9HH10K04' },
];

const SENIOR_GEOGRAPHY: MCQ[] = [
  { id: 'ss-g-1', q: 'The carbon cycle moves carbon between:', choices: ['Only the atmosphere and oceans', 'Atmosphere, biosphere, hydrosphere and geosphere', 'Only the biosphere', 'Only the hydrosphere'], answer: 1, explanation: 'Carbon cycles between all four major Earth systems through processes like photosynthesis and combustion.', acCode: 'AC9HG10K02', unit: 1 },
  { id: 'ss-g-2', q: 'Demographic transition theory describes changes in:', choices: ['Climate', 'Birth and death rates', 'Plate tectonics', 'Currency'], answer: 1, explanation: 'A 5-stage model linking economic development to falling birth and death rates.', acCode: 'AC9HG10K01', unit: 2 },
  { id: 'ss-g-3', q: 'A "megacity" has a population over:', choices: ['1 million', '5 million', '10 million', '50 million'], answer: 2, explanation: 'UN definition: an urban agglomeration of over 10 million people.', acCode: 'AC9HG10K01', unit: 2 },
  { id: 'ss-g-4', q: 'Eutrophication is mainly caused by:', choices: ['Drought', 'Nutrient runoff (esp. nitrogen and phosphorus)', 'Earthquakes', 'Salt water'], answer: 1, explanation: 'Excess nutrients feed algal blooms, depleting oxygen and killing aquatic life.', acCode: 'AC9HG10K02' },
  { id: 'ss-g-5', q: 'OPEC mainly produces:', choices: ['Coffee', 'Oil', 'Grain', 'Steel'], answer: 1, explanation: 'OPEC = Organization of Petroleum Exporting Countries.', unit: 3 },
  { id: 'ss-g-6', q: 'The 2015 Paris Agreement targets keeping warming below:', choices: ['1°C', '1.5°C', '3°C', '5°C'], answer: 1, explanation: 'Aim to limit global warming to well below 2°C and ideally to 1.5°C above pre-industrial levels.', acCode: 'AC9HG10K03', unit: 1 },
  { id: 'ss-g-7', q: 'ENSO refers to:', choices: ['El Niño – Southern Oscillation', 'European North Sea Org.', 'Equatorial Northern Sky Object', 'East-North Stratospheric Outflow'], answer: 0, explanation: 'ENSO drives major climate variability across the Pacific.', acCode: 'AC9HG10K02' },
  { id: 'ss-g-8', q: 'Which is a "developed" economy by World Bank classification?', choices: ['India', 'Indonesia', 'Australia', 'Vietnam'], answer: 2, explanation: 'Australia is a high-income economy by World Bank measures.', acCode: 'AC9HG10K01' },
  { id: 'ss-g-9', q: 'Coral bleaching is mainly driven by:', choices: ['Boat traffic', 'Ocean warming', 'Tides', 'Salinity drops'], answer: 1, explanation: 'Heat stress expels symbiotic algae from coral, leaving white skeletons.', acCode: 'AC9HG10K03' },
  { id: 'ss-g-10', q: 'A "primary industry" is one that:', choices: ['Manufactures goods', 'Extracts raw materials', 'Provides services', 'Builds software'], answer: 1, explanation: 'Primary = extraction (farming, fishing, mining). Secondary = manufacturing. Tertiary = services.', acCode: 'AC9HG10K01' },
  { id: 'ss-g-11', q: 'A "sustainable yield" of a forest means:', choices: ['Harvesting more than grows back', 'Harvesting at or below the rate of regrowth', 'No harvesting at all', 'Burning the forest'], answer: 1, explanation: 'Sustainable yields preserve the resource for future generations.', acCode: 'AC9HG10K02', unit: 4 },
  { id: 'ss-g-12', q: 'The "urban heat island" effect describes:', choices: ['Hot springs in cities', 'Cities being warmer than surrounding countryside', 'Volcanic activity near urban areas', 'Heatwaves only in summer'], answer: 1, explanation: 'Concrete, asphalt and reduced vegetation make cities significantly warmer than nearby rural land.', acCode: 'AC9HG10K01', unit: 2 },
  { id: 'ss-g-13', q: 'Australia’s largest export to China by value (recent years) has been:', choices: ['Wine', 'Iron ore', 'Wheat', 'Education'], answer: 1, explanation: 'Iron ore dominates Australia–China trade flows.', acCode: 'AC9HG10K01' },
  { id: 'ss-g-14', q: 'A "tipping point" in climate science refers to:', choices: ['A gradual change', 'A threshold beyond which large, often irreversible change occurs', 'A small fluctuation', 'A periodic cycle'], answer: 1, explanation: 'Examples: collapse of the West Antarctic ice sheet or amazon dieback.', acCode: 'AC9HG10K03', unit: 1 },
  { id: 'ss-g-15', q: 'GIS stands for:', choices: ['Global Internet System', 'Geographic Information System', 'Geological Index Scale', 'Government Indexed Standards'], answer: 1, explanation: 'GIS lets geographers layer and analyse spatial data.', acCode: 'AC9HG10S02' },
  { id: 'ss-g-16', q: 'A "youthful" age-sex pyramid suggests:', choices: ['Ageing population', 'High birth rates and low life expectancy', 'Stable population', 'Zero growth'], answer: 1, explanation: 'Wide-based pyramids show many young people — common in less-developed countries.', acCode: 'AC9HG10K01', unit: 2 },
  { id: 'ss-g-17', q: 'Sea level rise is mainly caused by:', choices: ['Tides', 'Thermal expansion + ice-sheet melt', 'River runoff', 'Rainfall'], answer: 1, explanation: 'Water expands as it warms; melting land ice adds new water to the oceans.', acCode: 'AC9HG10K03' },
  { id: 'ss-g-18', q: 'A "biocapacity" measurement compares:', choices: ['Carbon emissions to GDP', 'Biological resources available vs ecological demand', 'Birth rates to death rates', 'Trade to debt'], answer: 1, explanation: 'Used to assess whether a country is living within its ecological means.', acCode: 'AC9HG10K02', unit: 4 },
  { id: 'ss-g-19', q: 'Which country is the largest CO₂ emitter today?', choices: ['USA', 'Russia', 'China', 'India'], answer: 2, explanation: 'China became the largest annual emitter around 2006 (though per-capita and historical emissions differ).', acCode: 'AC9HG10K03' },
  { id: 'ss-g-20', q: 'A "food desert" is:', choices: ['A type of biome', 'An area with limited access to fresh, affordable food', 'A region with frequent droughts', 'A protected wilderness'], answer: 1, explanation: 'Common in poorer urban neighbourhoods lacking supermarkets.', acCode: 'AC9HG10K02', unit: 4 },
  { id: 'ss-g-21', q: 'Globalisation tends to increase:', choices: ['Trade barriers', 'Interconnection of economies and cultures', 'Self-sufficiency of nations', 'Use of local languages only'], answer: 1, explanation: 'Globalisation links markets, supply chains, media and migration patterns worldwide.', acCode: 'AC9HG10K01', unit: 3 },
  { id: 'ss-g-22', q: 'The "World Heritage" listing of Kakadu protects:', choices: ['Cultural and natural values', 'Only natural rock formations', 'Just Aboriginal art sites', 'Mining claims'], answer: 0, explanation: 'Kakadu is dual-listed for natural and cultural significance.', acCode: 'AC9HG10K02' },
  { id: 'ss-g-23', q: 'The Three Gorges Dam in China was built primarily for:', choices: ['Tourism', 'Hydroelectric power and flood control', 'Salt extraction', 'Defence'], answer: 1, explanation: 'World’s largest hydropower station — also displaced over a million residents.', acCode: 'AC9HG10K02' },
  { id: 'ss-g-24', q: 'The "Anthropocene" refers to:', choices: ['An ancient ice age', 'The current proposed epoch of significant human impact on Earth', 'A type of rock', 'A future star'], answer: 1, explanation: 'Some geologists propose this label for the era dominated by human-driven planetary change.', acCode: 'AC9HG10K03', unit: 1 },
  { id: 'ss-g-25', q: 'A "Gini coefficient" close to 0 indicates:', choices: ['Perfect inequality', 'Perfect equality', 'High poverty', 'Strong economic growth'], answer: 1, explanation: 'The Gini ranges 0 (perfect equality) to 1 (perfect inequality).', acCode: 'AC9HG10K01', unit: 2 },
];

const SENIOR_SCIENCE: MCQ[] = [
  { id: 'ss-s-1', q: 'Mitochondria are best known as the:', choices: ['Powerhouse of the cell', 'Storage for water', 'Information centre', 'Waste disposal'], answer: 0, explanation: 'They generate ATP through cellular respiration.', acCode: 'AC9S10U01', unit: 1 },
  { id: 'ss-s-2', q: 'The atomic number of an element equals its number of:', choices: ['Neutrons', 'Protons', 'Electrons in outer shell', 'Energy levels'], answer: 1, explanation: 'Atomic number = protons (and electrons in a neutral atom).', acCode: 'AC9S10U02' },
  { id: 'ss-s-3', q: 'Newton’s Second Law: F = ?', choices: ['m × v', 'm × a', 'a × v', 'm + a'], answer: 1, explanation: 'Force equals mass times acceleration.', acCode: 'AC9S10U02', unit: 2 },
  { id: 'ss-s-4', q: 'A "covalent bond" forms when atoms:', choices: ['Transfer electrons', 'Share electrons', 'Repel each other', 'Donate protons'], answer: 1, explanation: 'Ionic bonds transfer; covalent bonds share. Water (H₂O) is covalent.', acCode: 'AC9S10U02', unit: 1 },
  { id: 'ss-s-3b', q: 'DNA replication is described as:', choices: ['Conservative', 'Semi-conservative', 'Dispersive', 'Repetitive'], answer: 1, explanation: 'Each new DNA molecule keeps one parent strand and one new strand.', acCode: 'AC9S10U01', unit: 1 },
  { id: 'ss-s-5', q: 'The pH of pure water is:', choices: ['1', '7', '10', '14'], answer: 1, explanation: 'Pure water is neutral — pH 7.', acCode: 'AC9S10U02' },
  { id: 'ss-s-6', q: 'The kinetic energy of an object is given by:', choices: ['mgh', '½mv²', 'mv', 'm/v'], answer: 1, explanation: 'KE = ½mv²; mgh is gravitational potential energy.', acCode: 'AC9S10U02', unit: 2 },
  { id: 'ss-s-7', q: 'Photosynthesis takes place in the:', choices: ['Nucleus', 'Mitochondrion', 'Chloroplast', 'Ribosome'], answer: 2, explanation: 'Chloroplasts contain chlorophyll, which captures light energy.', acCode: 'AC9S10U01' },
  { id: 'ss-s-8', q: 'The Doppler effect explains:', choices: ['The colour of fire', 'Shift in wave frequency due to relative motion', 'How magnets attract', 'How fission works'], answer: 1, explanation: 'A passing siren’s pitch drops as it moves away from you.', acCode: 'AC9S10U02', unit: 3 },
  { id: 'ss-s-9', q: 'Hubble’s Law links a galaxy’s:', choices: ['Mass and brightness', 'Distance and recession velocity', 'Spin and shape', 'Age and chemistry'], answer: 1, explanation: 'Galaxies further away recede faster — evidence for an expanding universe.', acCode: 'AC9S10U04', unit: 4 },
  { id: 'ss-s-10', q: 'A "catalyst" in a reaction:', choices: ['Is consumed', 'Speeds the reaction without being consumed', 'Stops the reaction', 'Makes products toxic'], answer: 1, explanation: 'Catalysts lower activation energy and are regenerated at the reaction’s end.', acCode: 'AC9S10U02', unit: 2 },
  { id: 'ss-s-11', q: 'Natural selection requires:', choices: ['No variation', 'Variation, heritability, differential survival', 'Equal reproduction', 'Identical organisms'], answer: 1, explanation: 'Darwin’s mechanism: heritable variation + selective pressure → adaptation over generations.', acCode: 'AC9S10U01' },
  { id: 'ss-s-12', q: 'A "redox" reaction involves:', choices: ['Only acid–base exchange', 'Transfer of electrons between species', 'Phase changes', 'Distillation'], answer: 1, explanation: 'Reduction = gain of electrons; oxidation = loss. They always occur together.', acCode: 'AC9S10U02', unit: 3 },
  { id: 'ss-s-13', q: 'The "Standard Model" of particle physics includes:', choices: ['Only protons', 'Quarks, leptons and force-carrier bosons', 'Just atoms', 'Only neutrinos'], answer: 1, explanation: 'Six quarks, six leptons (incl. electron, neutrinos) and bosons (incl. the Higgs).', acCode: 'AC9S10U02', unit: 4 },
  { id: 'ss-s-14', q: 'Genetically, a male in humans has chromosomes:', choices: ['XX', 'XY', 'YY', 'XXY only'], answer: 1, explanation: 'In humans, XY usually develops as male; XX as female.', acCode: 'AC9S10U01' },
  { id: 'ss-s-15', q: 'Conservation of energy means energy can:', choices: ['Be destroyed', 'Be created from nothing', 'Only change form, never be created or destroyed', 'Disappear in friction'], answer: 2, explanation: 'First law of thermodynamics — energy is conserved, even when transformed.', acCode: 'AC9S10U02' },
  { id: 'ss-s-16', q: 'Ohm’s Law states:', choices: ['V = IR', 'P = V²/I', 'V = I + R', 'R = V × I'], answer: 0, explanation: 'Voltage = current × resistance for a linear (ohmic) conductor.', acCode: 'AC9S10U02', unit: 3 },
  { id: 'ss-s-17', q: 'The "greenhouse effect" is caused by:', choices: ['Volcanic dust only', 'Gases absorbing infrared radiation', 'The ozone hole', 'Solar flares'], answer: 1, explanation: 'CO₂, methane, water vapour and others trap outgoing infrared, warming the planet.', acCode: 'AC9S10U03' },
  { id: 'ss-s-18', q: 'The "specific heat capacity" of water is:', choices: ['Low compared to other liquids', 'Very high compared to most substances', 'Negative', 'Always zero'], answer: 1, explanation: 'Water resists temperature change — important for climate moderation and biology.', acCode: 'AC9S10U02' },
  { id: 'ss-s-19', q: 'Enzymes are made of:', choices: ['Carbohydrates', 'Lipids', 'Proteins', 'DNA'], answer: 2, explanation: 'Enzymes are protein biological catalysts (with rare RNA exceptions).', acCode: 'AC9S10U01' },
  { id: 'ss-s-20', q: 'A "blue shift" in stellar spectra implies the star is:', choices: ['Moving away from us', 'Moving toward us', 'Stationary', 'Cool'], answer: 1, explanation: 'Wavelengths compress when an object approaches — the relativistic Doppler effect.', acCode: 'AC9S10U04', unit: 4 },
  { id: 'ss-s-21', q: 'Mendel’s laws describe:', choices: ['Plate tectonics', 'Inheritance patterns of traits', 'Chemical bonding', 'Wave behaviour'], answer: 1, explanation: 'Gregor Mendel’s pea experiments founded modern genetics.', acCode: 'AC9S10U01' },
  { id: 'ss-s-22', q: 'A solution with pH 2 compared to pH 4 is:', choices: ['Slightly more acidic', '100× more acidic', '2× more acidic', 'Less acidic'], answer: 1, explanation: 'pH is logarithmic — each unit is a 10× change in [H+].', acCode: 'AC9S10U02', unit: 3 },
  { id: 'ss-s-23', q: 'Plate tectonics theory was firmly established in the:', choices: ['1800s', '1940s', '1960s', '1990s'], answer: 2, explanation: 'Seafloor spreading evidence in the 1960s confirmed Wegener’s earlier ideas.', acCode: 'AC9S10U03' },
  { id: 'ss-s-24', q: 'The half-life of a radioactive isotope is:', choices: ['Time for all atoms to decay', 'Time for half the atoms to decay', 'Time to form an isotope', 'Time for the element to change colour'], answer: 1, explanation: 'Used in carbon dating and nuclear medicine.', acCode: 'AC9S10U02', unit: 4 },
  { id: 'ss-s-25', q: 'In stellar evolution, our Sun will eventually become a:', choices: ['Black hole', 'Neutron star', 'Red giant then white dwarf', 'Supernova'], answer: 2, explanation: 'Sun-mass stars run out of hydrogen, swell into red giants and end as cooling white dwarfs.', acCode: 'AC9S10U04', unit: 4 },
];

// ============================================================
//  SENIOR — COMPUTING  (VCE Software Development Units 3–4)
//  Anchored to VCAA Applied Computing Study Design 2025–2028.
//  All items tagged unit: 3 or 4. Use cases: Quick Quiz, Buzzer
//  Round, Question Generator. Mix of factual recall and concept
//  application across all four Areas of Study.
// ============================================================
const SENIOR_COMPUTING: MCQ[] = [
  // -- Unit 3 AOS 1: Programming (1–25) --
  { id: 'ss-comp-1', q: 'The four stages of the VCAA problem-solving methodology are:', choices: ['Plan, Code, Test, Ship', 'Analysis, Design, Development, Evaluation', 'Brief, Build, Beta, Bug-fix', 'Requirements, Mock-up, Module, Markup'], answer: 1, explanation: 'The methodology has four stages: Analysis → Design → Development → Evaluation.', unit: 3 },
  { id: 'ss-comp-2', q: 'Which OOP principle bundles data with the methods that operate on it and controls access via modifiers?', choices: ['Abstraction', 'Inheritance', 'Encapsulation', 'Generalisation'], answer: 2, explanation: 'Encapsulation hides internal state behind public/protected/private access controls.', unit: 3 },
  { id: 'ss-comp-3', q: 'Which OOP principle lets a subclass acquire members from a superclass?', choices: ['Abstraction', 'Inheritance', 'Encapsulation', 'Generalisation'], answer: 1, explanation: 'Inheritance: the child class gains attributes and methods from its parent.', unit: 3 },
  { id: 'ss-comp-4', q: 'Hiding internal complexity and exposing only essential features describes:', choices: ['Encapsulation', 'Abstraction', 'Inheritance', 'Iteration'], answer: 1, explanation: 'Abstraction reduces cognitive load by surfacing only what the user needs to know.', unit: 3 },
  { id: 'ss-comp-5', q: 'Generalisation in OOP design means:', choices: ['Writing vague comments', 'Identifying common features across classes and lifting them into a more general superclass', 'Naming variables generically', 'Skipping validation for general users'], answer: 1, explanation: 'Generalisation is the design counterpart to inheritance — factoring shared behaviour upward.', unit: 3 },
  { id: 'ss-comp-6', q: 'Which data type best stores the value 42 with no decimal part?', choices: ['Floating point', 'String', 'Integer', 'Boolean'], answer: 2, explanation: 'Integers store whole numbers; floats store decimals; booleans store true/false.', unit: 3 },
  { id: 'ss-comp-7', q: 'Which data type stores only the values true or false?', choices: ['Integer', 'Boolean', 'Character', 'Date/time'], answer: 1, explanation: 'Boolean has exactly two possible values: true or false.', unit: 3 },
  { id: 'ss-comp-8', q: 'A variable holding the value 3.14159 is best declared as:', choices: ['Integer', 'Floating point', 'String', 'Boolean'], answer: 1, explanation: 'Floating-point types store numbers with a fractional component.', unit: 3 },
  { id: 'ss-comp-9', q: 'A one-dimensional array is best described as:', choices: ['A collection of records of different data types', 'A linear list of elements of the same data type', 'A grid of rows and columns', 'A tree of nodes'], answer: 1, explanation: '1D arrays are ordered, fixed-type sequences indexed from 0 (or 1, depending on language).', unit: 3 },
  { id: 'ss-comp-10', q: 'Which data structure best stores a chessboard?', choices: ['One-dimensional array', 'Two-dimensional array', 'Boolean variable', 'Single record'], answer: 1, explanation: 'A 2D array maps naturally to rows × columns — like an 8×8 chessboard.', unit: 3 },
  { id: 'ss-comp-11', q: 'A record (struct) differs from an array because it:', choices: ['Can only hold numbers', 'Holds multiple fields of possibly different data types', 'Is always one-dimensional', 'Cannot be passed to functions'], answer: 1, explanation: 'Records group heterogeneous fields under one name, accessed by field index/name.', unit: 3 },
  { id: 'ss-comp-12', q: 'Which file format is comma-delimited and commonly used to exchange tabular data?', choices: ['TXT', 'CSV', 'XML', 'JPG'], answer: 1, explanation: 'CSV (Comma-Separated Values) stores tabular data — one row per line, fields separated by commas.', unit: 3 },
  { id: 'ss-comp-13', q: 'XML files structure data using:', choices: ['Commas', 'Fixed-width columns', 'Nested tags with opening and closing brackets', 'Pipe characters'], answer: 2, explanation: 'XML uses hierarchical tags (e.g. <student><name>...</name></student>).', unit: 3 },
  { id: 'ss-comp-14', q: 'The naming convention strFirstName is an example of:', choices: ['snake_case', 'camelCase', 'Hungarian notation', 'PascalCase'], answer: 2, explanation: 'Hungarian notation prefixes the variable with its data type (str = string).', unit: 3 },
  { id: 'ss-comp-15', q: 'The variable name studentScore follows the convention:', choices: ['camelCase', 'snake_case', 'Hungarian notation', 'Kebab-case'], answer: 0, explanation: 'camelCase: lowercase first word, then capitalise each subsequent word, no separators.', unit: 3 },
  { id: 'ss-comp-16', q: 'The variable name total_marks is written in:', choices: ['camelCase', 'snake_case', 'Hungarian notation', 'PascalCase'], answer: 1, explanation: 'snake_case uses lowercase letters joined by underscores.', unit: 3 },
  { id: 'ss-comp-17', q: 'An existence check on user input verifies that:', choices: ['The value is the correct data type', 'The value falls within a specified range', 'A required field has been entered and is not blank', 'The value is unique in the database'], answer: 2, explanation: 'Existence (presence) checking confirms a mandatory field is not empty.', unit: 3 },
  { id: 'ss-comp-18', q: 'A type check confirms that data entered:', choices: ['Falls within a permitted minimum and maximum', 'Is of the expected data type (e.g. integer)', 'Matches a value in another table', 'Is not blank'], answer: 1, explanation: 'Type checking rejects, for example, alphabetic input where an integer was expected.', unit: 3 },
  { id: 'ss-comp-19', q: 'Range checking on a student-age field ensures the value:', choices: ['Is exactly 18', 'Falls between a defined minimum and maximum', 'Is unique', 'Matches the data type'], answer: 1, explanation: 'Range checks reject values outside an allowed interval (e.g. ages 5–99).', unit: 3 },
  { id: 'ss-comp-20', q: 'Selection sort has an average-case time complexity of:', choices: ['O(1)', 'O(log n)', 'O(n)', 'O(n²)'], answer: 3, explanation: 'Selection sort scans the remaining list each pass — O(n²) comparisons.', unit: 3 },
  { id: 'ss-comp-21', q: 'Quick sort has an average-case time complexity of:', choices: ['O(n²)', 'O(n log n)', 'O(n)', 'O(1)'], answer: 1, explanation: 'Quick sort averages O(n log n); worst case is O(n²) when pivots are poor.', unit: 3 },
  { id: 'ss-comp-22', q: 'Binary search requires the data to be:', choices: ['Unique', 'Numerical only', 'Sorted', 'Stored in an XML file'], answer: 2, explanation: 'Binary search halves a sorted list each step — it cannot operate on unsorted data.', unit: 3 },
  { id: 'ss-comp-23', q: 'Linear search works by:', choices: ['Halving the list at each step', 'Checking every element in turn from start to end', 'Hashing the target', 'Sorting first, then searching'], answer: 1, explanation: 'Linear search is O(n) but works on any list — sorted or unsorted.', unit: 3 },
  { id: 'ss-comp-24', q: 'A missing semicolon that prevents the program from running is which type of error?', choices: ['Logic error', 'Runtime error', 'Syntax error', 'Validation error'], answer: 2, explanation: 'Syntax errors violate language rules and are caught before execution.', unit: 3 },
  { id: 'ss-comp-25', q: 'A program that compiles and runs but produces the wrong answer has a:', choices: ['Syntax error', 'Logic error', 'Runtime error', 'Type error'], answer: 1, explanation: 'Logic errors give incorrect output even though the syntax is valid.', unit: 3 },
  // -- Unit 3 AOS 2: Analysis & Design (26–50) --
  { id: 'ss-comp-26', q: 'Dividing by zero at execution time produces a:', choices: ['Syntax error', 'Logic error', 'Runtime error', 'Compile-time error'], answer: 2, explanation: 'Runtime errors arise during execution — divide-by-zero, index out of range, type mismatch, overflow.', unit: 3 },
  { id: 'ss-comp-27', q: 'A breakpoint in a debugger:', choices: ['Stops the program permanently', 'Pauses execution at a chosen line so variables can be inspected', 'Deletes the next instruction', 'Optimises performance'], answer: 1, explanation: 'Breakpoints let developers inspect program state mid-run without rebuilding.', unit: 3 },
  { id: 'ss-comp-28', q: 'A testing table typically compares:', choices: ['Variables and constants', 'Expected output with actual output for given test data', 'Functional and non-functional requirements', 'Public and private members'], answer: 1, explanation: 'Test cases pair input + expected vs actual output to confirm a module behaves as intended.', unit: 3 },
  { id: 'ss-comp-29', q: 'Internal documentation in code primarily exists to:', choices: ['Replace external user manuals', 'Explain data and code structures and aid future maintenance', 'Increase the file size', 'Bypass type checking'], answer: 1, explanation: 'Comments and docstrings help future developers (and your future self) understand intent.', unit: 3 },
  { id: 'ss-comp-30', q: 'An emerging trend in programming with AI is:', choices: ['Removing all variables', 'Using natural-language prompts to generate code', 'Banning testing', 'Forbidding internal documentation'], answer: 1, explanation: 'AI code generators turn prompts into source — but require responsible, ethical use.', unit: 3 },
  { id: 'ss-comp-31', q: 'A FOR loop is an example of which control structure?', choices: ['Sequence', 'Selection', 'Iteration (repetition)', 'Encapsulation'], answer: 2, explanation: 'FOR, WHILE and REPEAT…UNTIL all express iteration/repetition.', unit: 3 },
  { id: 'ss-comp-32', q: 'An IF…ELSE statement is an example of which control structure?', choices: ['Sequence', 'Selection (branching)', 'Iteration', 'Recursion'], answer: 1, explanation: 'Selection chooses between code paths based on a condition.', unit: 3 },
  { id: 'ss-comp-33', q: 'A "brief" in a Software Development project documents:', choices: ['The marketing strategy', 'The problem/need/opportunity, proposed users and chosen programming language', 'The completed source code', 'The marking rubric'], answer: 1, explanation: 'A brief is a short scoping document submitted early in the SAT.', unit: 3 },
  { id: 'ss-comp-34', q: 'A Gantt chart is primarily used to:', choices: ['Diagram class inheritance', 'Visualise task sequencing, dependencies and time allocation', 'Model data flow', 'Document encryption keys'], answer: 1, explanation: 'Gantt charts plot tasks on a timeline showing dependencies and milestones.', unit: 3 },
  { id: 'ss-comp-35', q: 'The critical path on a Gantt chart is:', choices: ['The longest path of dependent tasks that determines minimum project duration', 'The shortest task', 'The hidden tasks', 'The lunch break'], answer: 0, explanation: 'Critical-path tasks have no slack — slipping them delays the whole project.', unit: 3 },
  { id: 'ss-comp-36', q: 'A milestone in project management is:', choices: ['A single line of code', 'A significant point or event marking progress', 'A type of bug', 'A subclass'], answer: 1, explanation: 'Milestones mark notable checkpoints (e.g. "design folio complete").', unit: 3 },
  { id: 'ss-comp-37', q: 'A non-functional requirement describes:', choices: ['What the system does', 'A quality attribute such as usability, reliability or maintainability', 'Hardware costs', 'Source code style'], answer: 1, explanation: 'Functional = what it does; non-functional = how well it does it.', unit: 3 },
  { id: 'ss-comp-38', q: 'A functional requirement of a login system would be:', choices: ['The login screen should load within 2 seconds', 'The system shall authenticate users via username and password', 'The system should be intuitive', 'The system should be available 99% of the time'], answer: 1, explanation: 'Functional requirements specify behaviours; the others are performance/usability/availability — non-functional.', unit: 3 },
  { id: 'ss-comp-39', q: 'Economic, legal, social and technical are categories of:', choices: ['Data types', 'Constraints', 'OOP principles', 'Test cases'], answer: 1, explanation: 'Solution constraints fall into these four broad categories per the study design.', unit: 3 },
  { id: 'ss-comp-40', q: 'The solution scope describes:', choices: ['The marketing budget', 'The boundaries — what will and will not be addressed', 'The IDE settings', 'The colour palette'], answer: 1, explanation: 'Scope establishes the limits/boundaries of the solution.', unit: 3 },
  { id: 'ss-comp-41', q: 'A context diagram (Level 0) typically shows:', choices: ['Every internal process', 'The system as a single process plus external entities and data flows', 'Class inheritance', 'Sorting algorithms'], answer: 1, explanation: 'Level 0 = a one-bubble overview; Level 1 DFD then decomposes the bubble.', unit: 3 },
  { id: 'ss-comp-42', q: 'A data flow diagram (Level 1) decomposes a system into:', choices: ['Processes, entities, data stores and data flows', 'Classes and objects', 'Test cases and assertions', 'Roles and permissions only'], answer: 0, explanation: 'Level 1 DFDs expand the system into internal processes and data stores.', unit: 3 },
  { id: 'ss-comp-43', q: 'In a use case diagram, an "actor" is:', choices: ['A class within the system', 'An external entity (user or system) that interacts with the system', 'The system database', 'A test case'], answer: 1, explanation: 'Actors sit outside the system boundary and trigger or receive use cases.', unit: 3 },
  { id: 'ss-comp-44', q: 'In UML use case diagrams the «includes» relationship means:', choices: ['Optional behaviour', 'Mandatory sub-behaviour shared by multiple use cases', 'Class inheritance', 'A delete action'], answer: 1, explanation: '«includes» is mandatory; «extends» is optional/conditional.', unit: 3 },
  { id: 'ss-comp-45', q: 'For her SAT analysis, Maya is producing the Software Requirements Specification (SRS). Which combination of contents does VCAA expect the SRS to cover?', choices: ['Functional requirements, test cases, deployment plan and user manual', 'Functional and non-functional requirements, constraints, scope, user characteristics and technical environment', 'Use-case diagrams, ERDs, data dictionary and Gantt chart', 'Risk register, change log, stakeholder map and evaluation criteria'], answer: 1, explanation: 'The SRS is the central analysis artefact for the SAT — VCAA names this exact six-item scope. The other options name real-but-different SDLC artefacts.', unit: 3 },
  { id: 'ss-comp-46', q: 'Which is a method for collecting primary data?', choices: ['A published government report', 'A survey conducted by the developer', 'A textbook chapter', 'Wikipedia'], answer: 1, explanation: 'Primary data is collected by the researcher; the others are secondary sources.', unit: 3 },
  { id: 'ss-comp-47', q: 'A differential backup contains:', choices: ['A full copy of all data', 'Changes since the last full backup', 'Changes since the last backup of any kind', 'Encrypted hashes only'], answer: 1, explanation: 'Differential = since last full; incremental = since last backup of any kind.', unit: 3 },
  { id: 'ss-comp-48', q: 'An INCREMENTAL backup captures:', choices: ['A complete copy of all data on the system', 'All changes since the last FULL backup', 'All changes since the most recent prior backup of any kind', 'Only files modified in the current calendar day'], answer: 2, explanation: 'Incremental = changes since the last backup of any kind. Differential = changes since the last full backup. Smaller and faster to take, slower to restore.', unit: 3 },
  { id: 'ss-comp-49', q: 'Version control software exists primarily to:', choices: ['Encrypt source code', 'Track changes to files over time and enable branching/merging', 'Optimise execution speed', 'Generate documentation'], answer: 1, explanation: 'Git, Subversion and similar tools preserve history and coordinate teamwork.', unit: 3 },
  { id: 'ss-comp-50', q: 'A mood board is a/an:', choices: ['Design tool for detailed pseudocode', 'Ideation tool for collecting visual references and inspiration', 'Testing strategy', 'Bug-tracking system'], answer: 1, explanation: 'Mood boards live in the ideation phase of design, capturing tone and aesthetic.', unit: 3 },
  // -- Unit 4 AOS 1: Development & Evaluation (51–75) --
  { id: 'ss-comp-51', q: 'A data dictionary in the design stage of the SDLC documents which combination of attributes for each data element?', choices: ['Just the field name and table name', 'Only the validation rules and data type', 'Name, type, size, validation rules and description for each field', 'Field name, table name and primary/foreign key relationships'], answer: 2, explanation: 'A data dictionary is the single source of truth — every field gets all five attributes documented. The other options name partial subsets that real-but-incomplete design docs sometimes contain.', unit: 4 },
  { id: 'ss-comp-52', q: 'An IPO chart describes:', choices: ['Inputs, Processes and Outputs of a module', 'Internal Procedure Order', 'Independent Programming Object', 'Iteration, Persistence, Output'], answer: 0, explanation: 'IPO = Input → Process → Output — a classic design tool for module behaviour.', unit: 4 },
  { id: 'ss-comp-53', q: 'Pseudocode is best described as:', choices: ['Compiled machine code', 'English-like statements expressing an algorithm independent of any programming language', 'A debugging tool', 'A version control system'], answer: 1, explanation: 'Pseudocode communicates logic without language-specific syntax.', unit: 4 },
  { id: 'ss-comp-54', q: 'Affordance in user experience (UX) refers to:', choices: ['The cost of the software', 'Visual or behavioural cues that suggest how an element can be used', 'How much memory the app uses', 'The number of users'], answer: 1, explanation: 'A button that looks pressable "affords" pressing — a key UX cue.', unit: 4 },
  { id: 'ss-comp-55', q: 'The design principle of "contrast" mainly helps with:', choices: ['File compression', 'Drawing attention to important elements and improving readability', 'Loop unrolling', 'Encryption'], answer: 1, explanation: 'Contrast distinguishes elements visually, aiding hierarchy and accessibility.', unit: 4 },
  { id: 'ss-comp-56', q: 'The Copyright Act 1968 (Cwlth) primarily protects:', choices: ['Personal data', 'Original literary, artistic and software works', 'Trademarks', 'Patents'], answer: 1, explanation: 'Copyright covers original works — including source code as a literary work.', unit: 4 },
  { id: 'ss-comp-57', q: 'The Privacy Act 1988 is a:', choices: ['Victorian Act', 'Federal (Commonwealth) Act', 'School policy', 'Industry standard'], answer: 1, explanation: 'Privacy Act 1988 (Cwlth) is federal; the Vic equivalent is the Privacy and Data Protection Act 2014.', unit: 4 },
  { id: 'ss-comp-58', q: 'Australian Privacy Principle (APP) 11 covers:', choices: ['Direct marketing', 'Security of personal information', 'Access to personal information', 'Anonymity and pseudonymity'], answer: 1, explanation: 'APP 11 requires organisations to take reasonable steps to protect personal information they hold.', unit: 4 },
  { id: 'ss-comp-59', q: 'Efficient and effective solutions are characterised by:', choices: ['Maximum lines of code', 'User-centred design, clear and concise code, and detailed internal documentation', 'Encrypting every variable', 'Using global variables exclusively'], answer: 1, explanation: 'The study design lists these three characteristics explicitly for Unit 4 AOS 1.', unit: 4 },
  { id: 'ss-comp-60', q: 'Which access modifier restricts a class member to be visible only within its own class?', choices: ['public', 'protected', 'private', 'internal'], answer: 2, explanation: 'private = same class only. protected adds subclasses; public adds the whole world.', unit: 4 },
  { id: 'ss-comp-61', q: 'Which access modifier exposes a class member to subclasses but not to unrelated classes?', choices: ['public', 'protected', 'private', 'static'], answer: 1, explanation: 'protected = visible to the declaring class and any subclasses.', unit: 4 },
  { id: 'ss-comp-62', q: 'A code repository (e.g. Git on GitHub) primarily supports:', choices: ['Image rendering', 'Storing source code, tracking history and enabling collaboration', 'Database design', 'Sound synthesis'], answer: 1, explanation: 'Repos are the foundation of modern version control and team development.', unit: 4 },
  { id: 'ss-comp-63', q: 'An API is best described as:', choices: ['A type of database', 'A defined interface that lets one piece of software request services from another', 'A backup format', 'A user interface element'], answer: 1, explanation: 'APIs define endpoints and contracts; libraries package reusable functionality.', unit: 4 },
  { id: 'ss-comp-64', q: 'Alpha testing is performed by:', choices: ['End users in production', 'Developers and internal testers in a development environment', 'Random customers via app stores', 'Auditors only'], answer: 1, explanation: 'Alpha = internal. Beta = potential end users in a production-like environment.', unit: 4 },
  { id: 'ss-comp-65', q: 'Beta testing is performed by:', choices: ['Developers writing the code', 'Compilers', 'Potential end users in an environment similar to deployment', 'Automated bots only'], answer: 2, explanation: 'Beta puts the solution in front of real users to gather feedback before release.', unit: 4 },
  { id: 'ss-comp-66', q: 'A beta-testing plan should include:', choices: ['Marketing budget', 'Test scenarios, observation method and how results will be recorded', 'Server hardware specs only', 'The encryption algorithm'], answer: 1, explanation: 'Per study design: testing plan, test scenarios, observation, documentation of results.', unit: 4 },
  { id: 'ss-comp-67', q: 'Per VCAA study design, a complete evaluation strategy specifies three elements:', choices: ['Criteria, success metrics and user feedback', 'Criteria, time frame and responsibility', 'Test cases, time frame and stakeholder sign-off', 'Criteria, sample size and data collection method'], answer: 1, explanation: 'Study design lists evaluation strategies as: WHAT to measure (criteria), WHEN (time frame), and WHO (responsibility). Missing any of the three drops marks.', unit: 4 },
  { id: 'ss-comp-68', q: '"Scope creep" refers to:', choices: ['A bug that copies data', 'Uncontrolled expansion of project requirements beyond the original scope', 'A search algorithm', 'A type of recursion'], answer: 1, explanation: 'Scope creep is a leading cause of project plan failure.', unit: 4 },
  { id: 'ss-comp-69', q: 'VCAA\'s three criteria for assessing the effectiveness of a project plan are:', choices: ['Total tasks completed, total budget spent and total bugs found', 'Number of changes made, reasons for those changes, and impact on completion', 'Number of stakeholders consulted, milestones met and risks identified', 'Lines of code written, test cases passed and documentation pages produced'], answer: 1, explanation: 'The study design names these three explicit criteria. Other options describe real software-engineering metrics that are NOT the VCAA-mandated three.', unit: 4 },
  { id: 'ss-comp-70', q: 'Which is NOT a factor that influences project plan effectiveness per the study design?', choices: ['Scope creep', 'Personnel changes', 'Technical issues', 'Variable names'], answer: 3, explanation: 'The three factors listed are scope creep, personnel changes and technical issues.', unit: 4 },
  { id: 'ss-comp-71', q: 'A project journal/log is used to:', choices: ['Replace the IDE', 'Monitor and document progress, decisions and changes throughout the project', 'Store user passwords', 'Render graphics'], answer: 1, explanation: 'Journals support reflective practice and provide evidence of progress for the SAT.', unit: 4 },
  { id: 'ss-comp-72', q: '"Commenting out" code is a debugging technique that:', choices: ['Permanently deletes the lines', 'Temporarily disables lines so the program runs without them', 'Encrypts the lines', 'Sends the lines to a server'], answer: 1, explanation: 'Useful for isolating which block is causing a bug without losing the code.', unit: 4 },
  { id: 'ss-comp-73', q: 'Constructing relevant test data means:', choices: ['Using only random values', 'Designing inputs that exercise valid, invalid, boundary and edge cases', 'Always using the production database', 'Avoiding negative numbers'], answer: 1, explanation: 'Good test data includes typical, boundary and invalid inputs.', unit: 4 },
  { id: 'ss-comp-74', q: 'AI assistants in software development (e.g. Copilot) are best used:', choices: ['To replace all human code review', 'As a productivity aid, with outputs critically reviewed and tested by the developer', 'To bypass version control', 'To skip documentation'], answer: 1, explanation: 'Responsible use treats AI output as a draft, not a finished product.', unit: 4 },
  { id: 'ss-comp-75', q: 'An overflow error is a type of:', choices: ['Syntax error', 'Logic error', 'Runtime error', 'Validation error'], answer: 2, explanation: 'Overflow occurs when a calculation exceeds the maximum value the data type can hold — at runtime.', unit: 4 },
  // -- Unit 4 AOS 2: Secure software development practices (76–100) --
  { id: 'ss-comp-76', q: 'An advantage of developing software in-house rather than externally is:', choices: ['Guaranteed lower cost', 'Greater control over requirements, IP and security practices', 'No need for testing', 'No need for legal compliance'], answer: 1, explanation: 'In-house dev gives the organisation tighter control, though it can require more upfront resourcing.', unit: 4 },
  { id: 'ss-comp-77', q: 'A common vulnerability of an insecurely designed API is:', choices: ['It uses too much electricity', 'It exposes data or functions without sufficient authentication or rate-limiting', 'It is written in a high-level language', 'It contains comments'], answer: 1, explanation: 'Poorly secured APIs are a major attack surface — broken auth, excessive data exposure, etc.', unit: 4 },
  { id: 'ss-comp-78', q: 'Malware is software that:', choices: ['Improves performance', 'Is intentionally designed to damage, disrupt or gain unauthorised access', 'Is open-source', 'Is licensed under GPL'], answer: 1, explanation: 'Malware umbrella includes viruses, worms, ransomware, spyware, trojans.', unit: 4 },
  { id: 'ss-comp-79', q: 'Why is unpatched software a security risk?', choices: ['It looks ugly', 'Known vulnerabilities remain exploitable until the patch is applied', 'It runs slower', 'It uses more disk space'], answer: 1, explanation: 'Public CVEs essentially advertise attacks; patches close them — until applied, the door stays open.', unit: 4 },
  { id: 'ss-comp-80', q: 'Identity and Access Management (IAM) refers to:', choices: ['Encrypting hard drives', 'Ensuring users have the right level of access to the right resources at the right time', 'Tracking IP addresses only', 'Renaming files'], answer: 1, explanation: 'IAM enforces the principle of least privilege across an organisation.', unit: 4 },
  { id: 'ss-comp-81', q: 'A man-in-the-middle (MITM) attack involves:', choices: ['Two attackers cooperating', 'An attacker secretly intercepting and possibly altering communication between two parties', 'A virus replicating itself', 'A worm spreading through a network'], answer: 1, explanation: 'MITM defeats confidentiality and integrity in transit — mitigated by TLS and certificate validation.', unit: 4 },
  { id: 'ss-comp-82', q: 'An "insider threat" originates from:', choices: ['Foreign state actors', 'Current or former employees, contractors or partners with legitimate access', 'Random external scanners', 'Hardware manufacturers'], answer: 1, explanation: 'Insider threats are dangerous because the actor already has trusted access.', unit: 4 },
  { id: 'ss-comp-83', q: 'A risk of using third-party software is:', choices: ['It is always slower', 'Vulnerabilities or supply-chain compromises in the dependency become your organisation\'s problem', 'It cannot be tested', 'It does not need licences'], answer: 1, explanation: 'SolarWinds, Log4Shell and similar incidents illustrate supply-chain risk.', unit: 4 },
  { id: 'ss-comp-84', q: 'A risk of combining development, testing and production environments is:', choices: ['Better collaboration', 'Test data or partially developed code can leak into production, expanding the attack surface', 'Lower compute cost', 'Easier UI design'], answer: 1, explanation: 'Separated environments isolate failures and limit blast radius.', unit: 4 },
  { id: 'ss-comp-85', q: 'Code review is best described as:', choices: ['Automated linting only', 'Human peer inspection of code to find defects and improve quality', 'Profiling for performance', 'Compiling the program'], answer: 1, explanation: 'Code review catches bugs early and spreads knowledge across the team.', unit: 4 },
  { id: 'ss-comp-86', q: 'Encryption of data at rest primarily protects against:', choices: ['Performance bottlenecks', 'Unauthorised reading of data on stolen or compromised storage', 'Code style violations', 'Compiler warnings'], answer: 1, explanation: 'Encryption ensures that even if storage media is lost, the contents are unreadable without the key.', unit: 4 },
  { id: 'ss-comp-87', q: 'Threat modelling typically follows the principles of:', choices: ['Define security requirements, identify and mitigate threats, then confirm mitigation', 'Build first, secure later', 'Outsource and hope', 'Encrypt everything regardless of risk'], answer: 0, explanation: 'Per study design: define → identify/mitigate → confirm.', unit: 4 },
  { id: 'ss-comp-88', q: 'Which Australian framework lists eight prioritised mitigation strategies including patching, MFA and application control?', choices: ['Essential Eight', 'OWASP Top 10', 'NIST 800-53', 'GDPR'], answer: 0, explanation: 'The Essential Eight is published by the Australian Cyber Security Centre (ACSC).', unit: 4 },
  { id: 'ss-comp-89', q: 'The Information Security Manual (ISM) is published by:', choices: ['The VCAA', 'The Australian Cyber Security Centre / ASD', 'The Privacy Commissioner', 'GitHub'], answer: 1, explanation: 'The ISM is the federal cyber-security baseline for Australian government and is referenced by the study design.', unit: 4 },
  { id: 'ss-comp-90', q: 'Onboarding training focused on secure development primarily aims to:', choices: ['Reduce salary costs', 'Embed secure coding practices in developers from day one', 'Replace code review', 'Eliminate the need for patches'], answer: 1, explanation: 'Culture is a primary mitigation — trained developers introduce fewer vulnerabilities.', unit: 4 },
  { id: 'ss-comp-91', q: 'A risk management plan (RMP) — recommended as an improvement strategy in Unit 4 AOS 2 — typically documents which four elements for each identified risk?', choices: ['Risk owner, escalation path, executive summary, board approval', 'Risk description, likelihood, impact AND mitigation strategy', 'Risk description, root cause, post-incident report, learnings register', 'Risk description, project Gantt position, cost estimate, sign-off'], answer: 1, explanation: 'Standard RMP structure: what is the risk, how likely is it, what is the impact if it occurs, and what is the mitigation strategy. The other options describe real corporate governance artefacts that are NOT the RMP structure VCAA expects.', unit: 4 },
  { id: 'ss-comp-92', q: 'An ethical issue arising from using AI during software development is:', choices: ['Faster compilation', 'Potential use of copyrighted training material or introduction of biased / vulnerable code', 'Reduced electricity cost', 'Smaller binaries'], answer: 1, explanation: 'Provenance of AI-generated code and its potential vulnerabilities are active ethical concerns.', unit: 4 },
  { id: 'ss-comp-93', q: 'The "principle of least privilege" means:', choices: ['Give every user admin rights for convenience', 'Grant each user the minimum access required to do their job', 'Privileges should rotate randomly', 'Privileges only apply to managers'], answer: 1, explanation: 'Least privilege limits the damage if an account is compromised.', unit: 4 },
  { id: 'ss-comp-94', q: 'Regular updates and patches contribute to security by:', choices: ['Adding more features only', 'Closing known vulnerabilities before attackers exploit them', 'Resetting all passwords', 'Encrypting backups'], answer: 1, explanation: 'Patch management is one of the Essential Eight strategies.', unit: 4 },
  { id: 'ss-comp-95', q: 'Multi-factor authentication (MFA) typically requires:', choices: ['Two passwords', 'Two or more independent factors — e.g. something you know plus something you have', 'A single biometric scan only', 'A username only'], answer: 1, explanation: 'Factors include knowledge (password), possession (token) and inherence (biometric).', unit: 4 },
  { id: 'ss-comp-96', q: 'An ethical responsibility of a developer who finds a security flaw is to:', choices: ['Sell the flaw', 'Disclose it responsibly so it can be fixed before public exploitation', 'Post it on social media immediately', 'Ignore it'], answer: 1, explanation: 'Responsible disclosure balances transparency with user protection.', unit: 4 },
  { id: 'ss-comp-97', q: 'A separated production environment helps because:', choices: ['It looks nicer', 'Bugs and partial features cannot accidentally affect real users or data', 'It uses less storage', 'It bypasses version control'], answer: 1, explanation: 'Production should only ever run code that has passed dev and testing checks.', unit: 4 },
  { id: 'ss-comp-98', q: 'A consequence of ineffective software development practices for an organisation can be:', choices: ['Better Glassdoor reviews', 'Legal liability, reputational damage and financial loss', 'Reduced electricity bills', 'A larger headcount'], answer: 1, explanation: 'Outages, breaches and lawsuits all flow from poor dev hygiene.', unit: 4 },
  { id: 'ss-comp-99', q: 'Robust IAM combined with separated environments and regular patching is an example of:', choices: ['Defence in depth', 'Premature optimisation', 'Scope creep', 'Pseudocode'], answer: 0, explanation: 'Defence in depth layers multiple controls so a single failure does not compromise the system.', unit: 4 },
  { id: 'ss-comp-100', q: 'After mitigations are implemented, threat modelling requires you to:', choices: ['Skip all future reviews', 'Confirm that the identified threats have been adequately mitigated', 'Delete the threat list', 'Outsource the project'], answer: 1, explanation: 'The final step closes the loop — verify that mitigations actually address the threats.', unit: 4 },

  // ============================================================
  //  Batch 2 (ss-comp-101 – ss-comp-200) — exam-style scenarios.
  //  Anchored to the 2025 VCAA Applied Computing: Software
  //  Development examination (Section A multiple-choice style).
  //  Scenario-led, named characters, application-focused.
  // ============================================================
  // -- Unit 3 AOS 1: Programming (101–125) --
  { id: 'ss-comp-101', q: 'Maya is writing code in an OOP language. The compiler stops with the message "expected }". This is most likely a:', choices: ['Runtime error', 'Logic error', 'Syntax error', 'Validation error'], answer: 2, explanation: 'Missing brackets violate the language\'s grammar — caught at compile time as a syntax error.', unit: 3 },
  { id: 'ss-comp-102', q: 'In the pseudocode IF score >= 50 THEN PRINT "Pass" ELSE PRINT "Fail" ENDIF, the control structure used is:', choices: ['Sequence', 'Selection', 'Iteration', 'Recursion'], answer: 1, explanation: 'IF / THEN / ELSE branches on a condition — selection.', unit: 3 },
  { id: 'ss-comp-103', q: 'A program stores prices like 19.95 (dollars and cents). The best data type is:', choices: ['Integer', 'Floating point', 'String', 'Boolean'], answer: 1, explanation: 'Fractional numeric values need a non-integer numeric type — floating point.', unit: 3 },
  { id: 'ss-comp-104', q: 'A school stores test scores for 30 students across 5 subjects. The most natural data structure is:', choices: ['A one-dimensional array of 30 elements', 'A two-dimensional array of 30 rows × 5 columns', 'A single record', 'A Boolean variable'], answer: 1, explanation: 'Rows = students, columns = subjects — a 2D array maps directly.', unit: 3 },
  { id: 'ss-comp-105', q: 'A student object stores a name (string), age (integer) and enrolment status (Boolean). The best data structure is a:', choices: ['One-dimensional array', 'Two-dimensional array', 'Record (or class instance)', 'TXT file'], answer: 2, explanation: 'Records / class instances bundle fields of different types under one name.', unit: 3 },
  { id: 'ss-comp-106', q: 'A file format that uses nested tags to represent hierarchical data is:', choices: ['CSV', 'TXT', 'XML', 'JPG'], answer: 2, explanation: 'XML\'s opening/closing tags naturally express hierarchy. CSV is flat tabular; TXT is unstructured.', unit: 3 },
  { id: 'ss-comp-107', q: 'A delimited file using commas to separate values is known as:', choices: ['TXT', 'CSV', 'XML', 'BIN'], answer: 1, explanation: 'CSV = Comma-Separated Values — one row per line.', unit: 3 },
  { id: 'ss-comp-108', q: 'Devon declares a variable as "intStudentAge". This is an example of:', choices: ['camelCase', 'snake_case', 'Hungarian notation', 'kebab-case'], answer: 2, explanation: 'Hungarian notation prefixes the variable with its data type ("int" here).', unit: 3 },
  { id: 'ss-comp-109', q: 'The variable name "student_first_name" follows which convention?', choices: ['camelCase', 'snake_case', 'Hungarian notation', 'PascalCase'], answer: 1, explanation: 'snake_case uses lowercase words separated by underscores.', unit: 3 },
  { id: 'ss-comp-110', q: 'A registration form requires an email address. The check confirming the field is not empty is a:', choices: ['Existence check', 'Type check', 'Range check', 'Format check'], answer: 0, explanation: 'Existence (presence) checking verifies that a required field has been filled in.', unit: 3 },
  { id: 'ss-comp-111', q: 'A program asks for an age as an integer. If the user types "twenty" and the program rejects it, this is an example of:', choices: ['A range check', 'A type check', 'An existence check', 'An overflow error'], answer: 1, explanation: 'Type checking ensures input matches the expected data type.', unit: 3 },
  { id: 'ss-comp-112', q: 'A grade field accepts only values between 0 and 100. The check that rejects 150 is a:', choices: ['Range check', 'Type check', 'Existence check', 'Code review'], answer: 0, explanation: 'Range checks confirm the value falls within a defined minimum and maximum.', unit: 3 },
  { id: 'ss-comp-113', q: 'Selection sort works by:', choices: ['Halving the list at each step', 'Repeatedly finding the smallest remaining element and placing it next', 'Partitioning around a pivot', 'Hashing each element'], answer: 1, explanation: 'Selection sort finds the minimum of the unsorted portion and swaps it into place.', unit: 3 },
  { id: 'ss-comp-114', q: 'Which statement is true about quick sort?', choices: ['It requires the data to be pre-sorted', 'It picks a pivot, partitions the data around it, and recurses on the partitions', 'It is always O(n) in the worst case', 'It cannot sort strings'], answer: 1, explanation: 'Quick sort\'s divide-and-conquer approach uses a pivot to split work.', unit: 3 },
  { id: 'ss-comp-115', q: 'A linear search through a list of 1000 items takes up to:', choices: ['1 comparison', '10 comparisons', '1000 comparisons', '5 comparisons'], answer: 2, explanation: 'Linear search is O(n) — worst case checks every element.', unit: 3 },
  { id: 'ss-comp-116', q: 'A binary search through 1000 sorted items takes at most about:', choices: ['1 comparison', '10 comparisons', '500 comparisons', '1000 comparisons'], answer: 1, explanation: 'Binary search is O(log n) — log₂(1000) ≈ 10 halving steps.', unit: 3 },
  { id: 'ss-comp-117', q: 'A program calculates average marks but reports a wildly wrong number. It compiled and ran without crashing. This is most likely:', choices: ['A syntax error', 'A logic error', 'A divide-by-zero error', 'An index-out-of-range error'], answer: 1, explanation: 'Code compiles and runs but produces incorrect output → logic error.', unit: 3 },
  { id: 'ss-comp-118', q: 'A 32-bit signed integer can store values up to about 2.1 billion. Attempting to store 5 billion in it causes:', choices: ['A syntax error', 'A logic error', 'An overflow error', 'A divide-by-zero error'], answer: 2, explanation: 'Overflow occurs when a value exceeds the maximum the data type can represent.', unit: 3 },
  { id: 'ss-comp-119', q: 'An array has indices 0–9. A loop using FOR i = 0 TO 10 will trigger:', choices: ['A syntax error', 'An index-out-of-range error when i = 10', 'A type mismatch error', 'No error at all'], answer: 1, explanation: 'Accessing array[10] when valid indices are 0–9 is out of range — runtime error.', unit: 3 },
  { id: 'ss-comp-120', q: 'A program tries to add a value entered as a string to an integer without conversion. The result is:', choices: ['Successful with implicit conversion in every language', 'A syntax error', 'A type mismatch (runtime) error in strongly-typed languages', 'An overflow error'], answer: 2, explanation: 'Type mismatch — string and integer cannot be combined without explicit conversion in strongly-typed languages.', unit: 3 },
  { id: 'ss-comp-121', q: 'Setting a breakpoint in the IDE primarily lets the developer:', choices: ['Permanently remove code from the file', 'Pause execution at a chosen line to inspect variables', 'Encrypt sensitive code sections', 'Generate documentation automatically'], answer: 1, explanation: 'Breakpoints pause the running program so developers can examine state.', unit: 3 },
  { id: 'ss-comp-122', q: 'Devon is designing test data for an "age" field that accepts integer values 0–120. To exercise boundary, typical and invalid inputs, the strongest test set is:', choices: ['25, 50, 75 (three typical values)', '-1, 0, 1, 120, 121 (boundary values only)', '-1, 0, 1, 25, 120, 121, "abc" (typical + boundary + invalid)', 'Random sample of 100 values drawn uniformly from 0–120'], answer: 2, explanation: 'Effective testing exercises typical, boundary AND invalid inputs together — pure-typical or pure-boundary sets miss whole bug categories.', unit: 3 },
  { id: 'ss-comp-123', q: 'A placeholder comment like "// TODO: implement payment gateway" is an example of:', choices: ['A breakpoint', 'A stub for future development', 'A syntax error', 'A unit test'], answer: 1, explanation: 'Stubs flag work to be completed and are a form of internal documentation.', unit: 3 },
  { id: 'ss-comp-124', q: 'When using AI to generate code, a developer\'s ethical responsibility includes:', choices: ['Never reading the generated code', 'Reviewing the output for correctness, security flaws and IP issues before committing', 'Removing all comments to hide the AI use', 'Disabling automated testing'], answer: 1, explanation: 'Responsible AI use requires critical review — AI can produce incorrect, insecure, or copyright-tainted code.', unit: 3 },
  { id: 'ss-comp-125', q: 'A WHILE loop with condition "WHILE count < 5", starting at count = 0 and incremented inside the loop, executes:', choices: ['4 times', '5 times', '6 times', 'Indefinitely'], answer: 1, explanation: 'Count goes 0, 1, 2, 3, 4 — five iterations before the condition fails.', unit: 3 },

  // -- Unit 3 AOS 2: Analysis & Design (126–150) --
  { id: 'ss-comp-126', q: 'A project BRIEF at the start of the SAT analysis stage primarily documents:', choices: ['The problem/need/opportunity, the proposed users and the chosen programming language', 'The full Software Requirements Specification and test plan', 'The final usability evaluation and recommended improvements', 'The complete data dictionary and use-case diagrams'], answer: 0, explanation: 'Briefs are short scoping documents — problem context, users, and technology choice. The other options describe artefacts produced LATER in the SDLC.', unit: 3 },
  { id: 'ss-comp-127', q: 'In a Gantt chart, a dependency between two tasks means:', choices: ['Both tasks must start at the same time', 'One task cannot start (or finish) until the other has reached a particular state', 'The tasks are unrelated', 'Both tasks are on the critical path'], answer: 1, explanation: 'Dependencies enforce sequencing — Task B waits on Task A.', unit: 3 },
  { id: 'ss-comp-128', q: 'A delay on a task that is NOT on the critical path will:', choices: ['Always delay the whole project', 'Not delay the project as long as the delay stays within the task\'s slack/float', 'Cause immediate scope creep', 'Reduce the project budget'], answer: 1, explanation: 'Non-critical tasks have slack — they can slip without delaying the project finish.', unit: 3 },
  { id: 'ss-comp-129', q: '"Design folio approved by client" would best be represented on a Gantt chart as a:', choices: ['Dependency', 'Milestone', 'Critical path', 'Constraint'], answer: 1, explanation: 'Milestones mark significant checkpoints or events.', unit: 3 },
  { id: 'ss-comp-130', q: 'Which of the following is a NON-functional requirement?', choices: ['The system must let users add new products', 'The system must respond within 2 seconds under normal load', 'The system must allow payment by credit card', 'The system must email a receipt on purchase'], answer: 1, explanation: 'Response time is a quality attribute — non-functional. The others describe what the system does.', unit: 3 },
  { id: 'ss-comp-131', q: 'A project budget of $50,000 is an example of which kind of constraint?', choices: ['Economic', 'Technical', 'Legal', 'Social'], answer: 0, explanation: 'Budget and time fall under economic constraints.', unit: 3 },
  { id: 'ss-comp-132', q: 'A requirement that the app must work on devices with only 2 GB of RAM is a:', choices: ['Legal constraint', 'Technical constraint', 'Social constraint', 'Functional requirement'], answer: 1, explanation: 'Hardware limitations fall under technical constraints.', unit: 3 },
  { id: 'ss-comp-133', q: 'Compliance with the Copyright Act 1968 (Cwlth) is an example of which constraint?', choices: ['Economic', 'Technical', 'Legal', 'Social'], answer: 2, explanation: 'IP / copyright considerations are legal constraints.', unit: 3 },
  { id: 'ss-comp-134', q: 'The solution scope of a project describes:', choices: ['The total cost of the project', 'What will and will not be addressed by the solution', 'Which team members are assigned', 'The colour palette of the UI'], answer: 1, explanation: 'Scope sets boundaries — explicit in-scope and out-of-scope items.', unit: 3 },
  { id: 'ss-comp-135', q: 'A context diagram (Level 0) typically shows:', choices: ['Every internal database table', 'The system as a single process plus external entities and data flows', 'Class inheritance', 'Test cases and expected results'], answer: 1, explanation: 'Context diagrams give a single-bubble overview with external entities.', unit: 3 },
  { id: 'ss-comp-136', q: 'A Level 1 data flow diagram (DFD) decomposes the system into:', choices: ['Processes, entities, data stores and data flows', 'Class members and methods', 'Test scenarios', 'User stories only'], answer: 0, explanation: 'Level 1 DFDs detail internal processes and the data they exchange.', unit: 3 },
  { id: 'ss-comp-137', q: 'In a use case diagram, an "actor" represents:', choices: ['A use case', 'A class', 'An external entity (user or system) that interacts with the system', 'A database table'], answer: 2, explanation: 'Actors sit outside the system boundary and trigger or receive use cases.', unit: 3 },
  { id: 'ss-comp-138', q: 'The «includes» relationship between two use cases means:', choices: ['The included use case is optional', 'The included use case is mandatory sub-behaviour invoked by the base case', 'The base case inherits from the included case', 'The base case extends the included case'], answer: 1, explanation: '«includes» is mandatory and called every time the base case runs.', unit: 3 },
  { id: 'ss-comp-139', q: 'The «extends» relationship between two use cases means:', choices: ['The extending use case adds optional, conditional behaviour to the base case', 'The extending use case is required', 'The extending use case must run before the base', 'The base case inherits methods from the extending case'], answer: 0, explanation: '«extends» represents optional / conditional behaviour layered on the base.', unit: 3 },
  { id: 'ss-comp-140', q: 'A software requirements specification (SRS) should NOT typically include:', choices: ['Functional and non-functional requirements', 'Constraints, scope and user characteristics', 'The technical environment', 'The final source code'], answer: 3, explanation: 'SRS captures requirements — not implementation. Source code is a development output.', unit: 3 },
  { id: 'ss-comp-141', q: 'Which data collection method best gathers deep, qualitative insights from a single stakeholder?', choices: ['A survey of 500 customers', 'A semi-structured interview', 'A passive observation of website logs', 'A bulk email broadcast'], answer: 1, explanation: 'Interviews allow follow-up questions and capture nuanced perspectives.', unit: 3 },
  { id: 'ss-comp-142', q: 'Which data collection method is best for capturing how staff currently complete a daily workflow?', choices: ['Observation in the workplace', 'A multiple-choice survey', 'A reading of historical financial reports', 'A literature review'], answer: 0, explanation: 'Observation directly captures current behaviour rather than what people SAY they do.', unit: 3 },
  { id: 'ss-comp-143', q: 'A government report on national broadband usage, read and used by a researcher, is an example of:', choices: ['Primary data', 'Secondary data', 'A survey result the researcher produced', 'An interview transcript'], answer: 1, explanation: 'Data collected by someone other than the researcher is secondary.', unit: 3 },
  { id: 'ss-comp-144', q: 'A site does a FULL backup every Sunday and an INCREMENTAL backup every other day. The incremental taken on Wednesday captures:', choices: ['A complete copy of all current data', 'All changes since Sunday\'s full backup', 'All changes since Tuesday\'s incremental backup', 'All changes since the previous Wednesday'], answer: 2, explanation: 'Incrementals capture changes since the MOST RECENT prior backup of any kind — so Wednesday\'s incremental covers only Tuesday\'s changes. A differential backup would capture everything since Sunday.', unit: 3 },
  { id: 'ss-comp-145', q: 'A site does a FULL backup every Sunday and a DIFFERENTIAL backup every other day. The differential taken on Wednesday captures:', choices: ['Changes from Wednesday alone', 'All changes since Sunday\'s full backup (Mon + Tue + Wed)', 'All changes since Tuesday\'s differential backup', 'A complete copy of all current data'], answer: 1, explanation: 'Differentials always capture changes since the most recent FULL backup — so Wednesday\'s differential covers Mon + Tue + Wed combined. Larger than an incremental, faster to restore.', unit: 3 },
  { id: 'ss-comp-146', q: 'Version control systems like Git primarily support developers by:', choices: ['Compiling code faster', 'Tracking changes to files over time and enabling branching/merging for collaboration', 'Encrypting source code at rest', 'Automatically deploying code to production'], answer: 1, explanation: 'Git manages history and structures team collaboration.', unit: 3 },
  { id: 'ss-comp-147', q: 'A mind map is best categorised as a/an:', choices: ['Detailed design tool for module structure', 'Ideation tool for generating and connecting ideas', 'Testing strategy', 'Debugger feature'], answer: 1, explanation: 'Mind maps live in the ideation phase — capturing thoughts and links.', unit: 3 },
  { id: 'ss-comp-148', q: 'A mock-up of a user interface is best described as a:', choices: ['Working prototype with full logic', 'Visual design tool showing layout, placement and appearance of UI elements', 'A list of test cases', 'A backup of the final design files'], answer: 1, explanation: 'Mock-ups represent appearance and layout without implementing behaviour.', unit: 3 },
  { id: 'ss-comp-149', q: 'A data dictionary documents:', choices: ['Funny variable names', 'Each data element\'s name, type, size, validation rules and description', 'Project schedules only', 'The UI colour scheme only'], answer: 1, explanation: 'Data dictionaries are the canonical record of every field in the data model.', unit: 3 },
  { id: 'ss-comp-150', q: 'In UX terms, "usability" refers to:', choices: ['How attractive the design is', 'How easily users can achieve their goals using the system', 'How quickly the code compiles', 'How many users have signed up'], answer: 1, explanation: 'Usability = ease of use; achieving goals effectively, efficiently and with satisfaction.', unit: 3 },

  // -- Unit 4 AOS 1: Development & Evaluation (151–175) --
  { id: 'ss-comp-151', q: 'Per the study design, characteristics of efficient and effective solutions include user-centred design, clear concise code, and:', choices: ['Maximum lines of code per function', 'Detailed internal documentation', 'Fully obfuscated logic', 'Hard-coded test values'], answer: 1, explanation: 'The three explicit characteristics: user-centred design, clear/concise code, detailed internal documentation.', unit: 4 },
  { id: 'ss-comp-152', q: 'User-centred design prioritises:', choices: ['The developer\'s preferences', 'The intended end users\' needs, goals and contexts throughout the design process', 'Investor preferences only', 'The latest design trends regardless of fit'], answer: 1, explanation: 'UCD places real users at the centre — through research, prototypes, and testing with actual users.', unit: 4 },
  { id: 'ss-comp-153', q: 'A class attribute marked "private" can be accessed by:', choices: ['Any class in the application', 'Only the class that declares it', 'Only subclasses', 'Only the program\'s main method'], answer: 1, explanation: 'private = same class only. protected adds subclasses; public is global.', unit: 4 },
  { id: 'ss-comp-154', q: 'A class attribute marked "protected" can be accessed by:', choices: ['Only the declaring class', 'The declaring class and any subclasses', 'Any class in the application', 'Only methods marked static'], answer: 1, explanation: 'protected exposes members to subclasses while hiding them from unrelated classes.', unit: 4 },
  { id: 'ss-comp-155', q: 'A class attribute marked "public" can be accessed by:', choices: ['Only the declaring class', 'Only subclasses', 'Any class anywhere with a reference to the object', 'Nobody — public means "publicly hidden"'], answer: 2, explanation: 'public = no access restrictions; visible wherever the object is in scope.', unit: 4 },
  { id: 'ss-comp-156', q: 'An application programming interface (API) provides:', choices: ['A user interface', 'A defined contract through which software can request services from other software', 'A backup mechanism', 'A type of database index'], answer: 1, explanation: 'APIs expose functionality with documented endpoints and parameters.', unit: 4 },
  { id: 'ss-comp-157', q: 'A code repository hosted on GitHub primarily helps a development team by:', choices: ['Encrypting all source code at rest', 'Storing source code centrally with version history and supporting collaboration via branches and pull requests', 'Automatically generating UI mock-ups', 'Stopping bugs from being introduced'], answer: 1, explanation: 'Code repos centralise source, track history, and structure team collaboration.', unit: 4 },
  { id: 'ss-comp-158', q: 'When an AI assistant suggests a block of code, the developer should:', choices: ['Commit it immediately without review', 'Critically review it for correctness, security and IP issues, then test before committing', 'Reject all AI-generated code as a matter of policy', 'Remove all comments to hide its AI origin'], answer: 1, explanation: 'Responsible AI use treats output as a draft, not a finished product.', unit: 4 },
  { id: 'ss-comp-159', q: 'Alpha testing is best described as testing carried out by:', choices: ['End users in a production environment', 'Developers and internal testers in a development environment', 'Customers post-launch', 'Automated test bots only'], answer: 1, explanation: 'Alpha = internal, in dev environment. Beta = potential users, in production-like environment.', unit: 4 },
  { id: 'ss-comp-160', q: 'Beta testing is best described as testing carried out by:', choices: ['Developers in the dev environment', 'Compilers and linters', 'Potential end users in an environment similar to deployment', 'The CEO of the company'], answer: 2, explanation: 'Beta puts the solution in front of real prospective users for feedback.', unit: 4 },
  { id: 'ss-comp-161', q: 'For VCAA-compliant beta testing in the SAT, the testing plan should document which four elements?', choices: ['Testing plan, test scenarios, observation method, results documentation', 'Bug count, severity, owner, resolution date', 'Stakeholder list, test budget, scheduled hours, sign-off', 'Test environment, hardware specs, network config, browser matrix'], answer: 0, explanation: 'Study design requires beta testing to cover all four: the plan itself, the scenarios users will exercise, how observation will be conducted, and how results will be documented.', unit: 4 },
  { id: 'ss-comp-162', q: 'Effective test scenarios for a beta test should be drawn from:', choices: ['Edge cases the development team has not yet considered', 'Realistic tasks users would actually perform, aligned with the solution\'s requirements', 'A random sample of all possible system interactions', 'Tasks invented after observing initial bug reports'], answer: 1, explanation: 'Scenarios should mirror realistic, requirement-aligned user goals — testing what users will actually do, not just what might theoretically break.', unit: 4 },
  { id: 'ss-comp-163', q: 'Evaluation criteria for a software solution are typically developed during:', choices: ['The development stage', 'The design stage, then refined and applied during evaluation', 'After the project is fully delivered only', 'The marketing campaign'], answer: 1, explanation: 'Criteria are designed early so evaluation can measure against them later.', unit: 4 },
  { id: 'ss-comp-164', q: 'An evaluation strategy explicitly specifies criteria, responsibility and:', choices: ['Source code', 'Time frame', 'Compiler version', 'Number of UI screens'], answer: 1, explanation: 'Per study design: criteria + time frame + responsibility.', unit: 4 },
  { id: 'ss-comp-165', q: 'Responsibility for conducting the post-implementation evaluation should be:', choices: ['Left unspecified', 'Assigned explicitly to a person or team, documented in the evaluation strategy', 'Always with the original developer regardless of role changes', 'Always with the client only'], answer: 1, explanation: 'Strategies name who collects what data and when.', unit: 4 },
  { id: 'ss-comp-166', q: 'A client repeatedly asks for new features mid-project, expanding the original requirements without formal change control. This is called:', choices: ['Agile development', 'Scope creep', 'Refactoring', 'Iteration'], answer: 1, explanation: 'Scope creep — uncontrolled growth of project scope beyond the original brief.', unit: 4 },
  { id: 'ss-comp-167', q: 'A key software developer leaves the team midway through a project. The most direct impact on the project plan is likely to be:', choices: ['Improved morale', 'Delays as knowledge is transferred and tasks reassigned', 'Reduced cost', 'Faster delivery'], answer: 1, explanation: 'Personnel changes are an explicit project-plan effectiveness factor — usually causing slowdowns.', unit: 4 },
  { id: 'ss-comp-168', q: 'A team discovers that the database engine chosen for the project does not scale to the expected user load. This is best categorised as:', choices: ['Scope creep', 'A personnel change', 'A technical issue', 'A change in user requirements'], answer: 2, explanation: 'Technical issues are one of the three explicit project-plan effectiveness factors.', unit: 4 },
  { id: 'ss-comp-169', q: 'A project journal is most useful for:', choices: ['Replacing the IDE', 'Capturing decisions, progress and reasons for change over the life of the project', 'Generating compiled binaries', 'Storing user passwords'], answer: 1, explanation: 'Project journals/logs are the formal record of "what we did and why" through the project.', unit: 4 },
  { id: 'ss-comp-170', q: 'When a task on a Gantt chart slips by two days, the recommended record-keeping practice is to:', choices: ['Erase the original plan', 'Annotate the chart with the new dates, update dependencies and record the reason for the change', 'Email the team with no documentation', 'Hide the slip from the client'], answer: 1, explanation: 'Annotations preserve the audit trail and let dependent tasks be re-planned correctly.', unit: 4 },
  { id: 'ss-comp-171', q: 'Commenting out a block of code while debugging is useful because:', choices: ['It permanently deletes the code', 'It temporarily disables the code without losing it, helping isolate the source of a bug', 'It runs the code faster', 'It encrypts the code'], answer: 1, explanation: 'You can isolate the bug by toggling which sections run.', unit: 4 },
  { id: 'ss-comp-172', q: 'A VCAA-style testing table should contain columns for:', choices: ['Test ID, input data, expected output, actual output, pass/fail', 'Test ID, developer name, date written, code reviewer', 'Bug title, severity, assigned-to, resolution status', 'Test ID, code coverage %, execution time, memory usage'], answer: 0, explanation: 'The core of a testing table is comparing EXPECTED vs ACTUAL under a labelled test ID. Other options describe valid software-engineering artefacts that are NOT the VCAA testing table.', unit: 4 },
  { id: 'ss-comp-173', q: 'Range checking is best categorised as:', choices: ['A debugging technique', 'A validation technique used on input', 'A backup strategy', 'A type of malware'], answer: 1, explanation: 'Validation techniques include existence, type and range checking.', unit: 4 },
  { id: 'ss-comp-174', q: 'Verification (as distinct from validation) refers to:', choices: ['Checking input is reasonable as it is entered', 'Checking that entered data accurately matches the source it was taken from', 'Encrypting data', 'Backing up data'], answer: 1, explanation: 'Validation = reasonable on input; verification = matches the source after entry.', unit: 4 },
  { id: 'ss-comp-175', q: 'Recognised techniques for recording project progress include all of the following EXCEPT:', choices: ['Adjustments to tasks', 'Adjustments to time frames', 'Annotations to project plans', 'Random verbal updates with no record'], answer: 3, explanation: 'Per study design: task/time-frame adjustments, annotations and logs/journals — formal records.', unit: 4 },

  // -- Unit 4 AOS 2: Secure Software Development Practices (176–200) --
  { id: 'ss-comp-176', q: 'An organisation choosing to develop software in-house rather than externally typically gains:', choices: ['No legal obligations', 'Greater control over intellectual property, requirements and security practices', 'Guaranteed lower cost in every case', 'A free pass on testing'], answer: 1, explanation: 'In-house gives tighter control — at the cost of needing in-house capacity.', unit: 4 },
  { id: 'ss-comp-177', q: 'A potential advantage of OUTSOURCING software development to an external team is:', choices: ['No need to ever review the code', 'Access to specialised skills or capacity the organisation does not have in-house', 'Automatic immunity to security flaws', 'Avoiding all project management overhead'], answer: 1, explanation: 'External teams bring specialist expertise and scale — though IP and security require careful contracts.', unit: 4 },
  { id: 'ss-comp-178', q: 'A public API exposes user records when called with a known account ID, even from unauthenticated clients. The vulnerability is best described as:', choices: ['A man-in-the-middle attack', 'Insecure API design (broken authentication / access control)', 'A natural disaster', 'A code review failure only'], answer: 1, explanation: 'Poorly authenticated APIs expose data to anyone who can guess endpoints or IDs.', unit: 4 },
  { id: 'ss-comp-179', q: 'Malware that encrypts the victim\'s data and demands payment for the key is called:', choices: ['Spyware', 'Ransomware', 'A worm', 'Adware'], answer: 1, explanation: 'Ransomware extorts a payment in exchange for decryption.', unit: 4 },
  { id: 'ss-comp-180', q: 'Unpatched software is a security risk primarily because:', choices: ['It runs slower', 'Known vulnerabilities (CVEs) remain exploitable until the patch is applied', 'It looks outdated', 'It uses more disk space'], answer: 1, explanation: 'Once a CVE is published, attackers can target unpatched systems immediately.', unit: 4 },
  { id: 'ss-comp-181', q: 'A company gives every employee full admin rights to the source-code repository "for convenience". This violates the principle of:', choices: ['Defence in depth', 'Least privilege', 'Encryption in transit', 'Redundancy'], answer: 1, explanation: 'Least privilege grants the minimum access required — universal admin is the opposite.', unit: 4 },
  { id: 'ss-comp-182', q: 'A man-in-the-middle (MITM) attack involves:', choices: ['Encrypting all network traffic', 'An attacker secretly intercepting and possibly altering communications between two parties', 'Replicating itself across a network', 'Backing up data twice'], answer: 1, explanation: 'MITM breaks confidentiality and integrity in transit — usually defeated by TLS.', unit: 4 },
  { id: 'ss-comp-183', q: 'A former employee retains their old VPN credentials after leaving and uses them to access company data. This is an example of:', choices: ['A natural disaster', 'An insider threat', 'A denial-of-service attack', 'A phishing campaign'], answer: 1, explanation: 'Insider threats include current AND former employees with leftover access.', unit: 4 },
  { id: 'ss-comp-184', q: 'A third-party JavaScript library used by a company\'s app is found to contain a backdoor. This is an example of:', choices: ['A natural disaster', 'A supply-chain risk from third-party software', 'A logic error', 'An overflow error'], answer: 1, explanation: 'Vulnerabilities in dependencies become the consuming organisation\'s problem.', unit: 4 },
  { id: 'ss-comp-185', q: 'A purpose of code review is to:', choices: ['Replace all automated testing', 'Have peers inspect code to catch defects, security flaws and design issues before merging', 'Compile the code faster', 'Encrypt the code'], answer: 1, explanation: 'Code review is a quality + security practice and a recognised security control.', unit: 4 },
  { id: 'ss-comp-186', q: 'A risk of running development, testing and production in a SINGLE combined environment is:', choices: ['Lower hosting cost', 'Test data or partial work can leak into production, expanding the attack surface and risking real users', 'Faster development', 'Better security'], answer: 1, explanation: 'Separated environments isolate failures; combining them removes that isolation.', unit: 4 },
  { id: 'ss-comp-187', q: 'Using version control as a security practice helps because it:', choices: ['Encrypts all files automatically', 'Lets the team trace who changed what and revert malicious or accidental changes', 'Prevents all bugs', 'Runs antivirus scans'], answer: 1, explanation: 'Auditable history is a security property — supports incident response.', unit: 4 },
  { id: 'ss-comp-188', q: 'Encrypting data at rest protects against:', choices: ['Slow networks', 'Unauthorised reading of data if storage media is stolen or otherwise accessed', 'CPU overheating', 'Compiler errors'], answer: 1, explanation: 'Even with physical access, the data remains unreadable without the key.', unit: 4 },
  { id: 'ss-comp-189', q: 'Encrypting data in transit (e.g. via TLS) protects against:', choices: ['Hard-drive failure', 'Eavesdropping and tampering by attackers on the network path', 'Software bugs', 'Battery drain'], answer: 1, explanation: 'TLS protects confidentiality and integrity of traffic between client and server.', unit: 4 },
  { id: 'ss-comp-190', q: 'During code review, a reviewer notices a password is hard-coded as a string literal in source. The reviewer should:', choices: ['Ignore it — code reviews are only for style', 'Flag it as a security issue and require it be moved to a secrets store or environment variable', 'Approve the PR immediately', 'Delete the entire file'], answer: 1, explanation: 'Hard-coded secrets are a classic security flaw that code review must catch.', unit: 4 },
  { id: 'ss-comp-191', q: 'Regular patching of operating systems and libraries primarily:', choices: ['Adds new features only', 'Closes known security vulnerabilities before they can be exploited', 'Slows the system down', 'Replaces the need for backups'], answer: 1, explanation: 'Patch management is one of the Essential Eight strategies precisely because of CVE risk.', unit: 4 },
  { id: 'ss-comp-192', q: 'Separating development, testing and production environments helps because:', choices: ['It uses more electricity', 'A failure or attack in one environment does not propagate to the others', 'It eliminates the need for testing', 'It removes the need for backups'], answer: 1, explanation: 'Isolation limits blast radius — a core security principle.', unit: 4 },
  { id: 'ss-comp-193', q: 'The first step in threat modelling, per the study design, is to:', choices: ['Buy more firewalls', 'Define the security requirements of the system', 'Run a penetration test', 'Encrypt every byte'], answer: 1, explanation: 'Define requirements → identify and mitigate threats → confirm mitigation.', unit: 4 },
  { id: 'ss-comp-194', q: 'After identifying threats, threat modelling requires the team to:', choices: ['Ignore the threats', 'Design and implement mitigations for those threats', 'Outsource the project', 'Reset all passwords annually'], answer: 1, explanation: 'Identify → mitigate is the heart of the threat modelling cycle.', unit: 4 },
  { id: 'ss-comp-195', q: 'The final step in threat modelling, after mitigations have been implemented, is to:', choices: ['Stop documenting the system', 'Confirm that the identified threats have actually been mitigated', 'Delete the threat list', 'Increase the marketing budget'], answer: 1, explanation: 'Closing the loop — verify that mitigations addressed the threats they targeted.', unit: 4 },
  { id: 'ss-comp-196', q: 'A purpose of threat modelling is to:', choices: ['Replace the need for testing', 'Systematically reason about what could go wrong with the system and how to address it', 'Replace encryption', 'Avoid all third-party software'], answer: 1, explanation: 'Threat modelling is a structured way to think about attack surface and defences.', unit: 4 },
  { id: 'ss-comp-197', q: 'Which of the following is part of the Essential Eight mitigation strategies?', choices: ['Hiring a marketing team', 'Multi-factor authentication', 'Outsourcing all development', 'Increasing the project budget'], answer: 1, explanation: 'MFA is one of the eight strategies published by the ACSC.', unit: 4 },
  { id: 'ss-comp-198', q: 'The Essential Eight strategy of "application control" means:', choices: ['Forbidding users from opening any application', 'Allowing only approved applications to execute on a system', 'Removing the Start menu', 'Encrypting every application binary'], answer: 1, explanation: 'Application control (whitelisting) limits execution to trusted software, blocking malware.', unit: 4 },
  { id: 'ss-comp-199', q: 'The Information Security Manual (ISM) is published by:', choices: ['The Victorian Curriculum and Assessment Authority', 'The Australian Cyber Security Centre (part of the Australian Signals Directorate)', 'GitHub', 'The IETF'], answer: 1, explanation: 'The ISM is the federal cyber-security baseline maintained by ACSC / ASD.', unit: 4 },
  { id: 'ss-comp-200', q: 'Onboarding new developers with security-focused training is recommended primarily because:', choices: ['It is required by the VCAA', 'It embeds secure coding practices from day one, reducing vulnerabilities introduced into the codebase', 'It guarantees no bugs', 'It replaces the need for code review'], answer: 1, explanation: 'Culture is a primary mitigation — trained developers ship fewer vulnerabilities.', unit: 4 },
];

// ============================================================
//  SENIOR — SOCIOLOGY (VCE Sociology Units 3–4)
//  Anchored to VCAA Sociology Study Design 2024 (v1.1) and the
//  2025 examination. 200 MCQs across U3 AOS1 (Indigenous
//  cultures), U3 AOS2 (Ethnicity), U4 AOS1 (Community), U4 AOS2
//  (Social movements & social change). 50 items per AOS.
//
//  NOTE: The VCAA Sociology exam has NO multiple choice. MCQ
//  shape is our brain-break convention. Distractors target the
//  misconceptions documented in source-material/.../_overview.md.
// ============================================================
const SENIOR_SOCIOLOGY: MCQ[] = [
  // -- Unit 3 AOS 1: Australian Indigenous cultures (1–50) --
  { id: 'ss-soc-1', q: 'In sociology, "material culture" refers to:', choices: ['Values, beliefs and norms shared by a group', 'Physical artefacts, art, tools and clothing produced by a culture', 'Government policies that shape a culture', 'Economic resources held by a society'], answer: 1, explanation: 'Material culture is the physical, tangible expression of a culture; non-material culture covers ideas, values, beliefs and norms.', unit: 3 },
  { id: 'ss-soc-2', q: 'Examples of NON-material culture include:', choices: ['Tools, clothing and artworks', 'Buildings and monuments', 'Values, beliefs, norms and language', 'Coins and physical money'], answer: 2, explanation: 'Non-material culture is the intangible aspect — values, beliefs, language, customs.', unit: 3 },
  { id: 'ss-soc-3', q: 'The concept of the "sociological imagination" was developed by:', choices: ['Stuart Hall', 'Charles Wright Mills (1959)', 'Erica Chenoweth', 'Ferdinand Tönnies'], answer: 1, explanation: 'C. Wright Mills coined the term in his 1959 book of the same name.', unit: 3 },
  { id: 'ss-soc-4', q: 'The sociological imagination, per C. Wright Mills, connects:', choices: ['Material and non-material culture', 'Personal experience and wider social structures', 'Race and ethnicity', 'Symbolic and practical reconciliation'], answer: 1, explanation: 'Mills described it as seeing the link between personal troubles and public issues.', unit: 3 },
  { id: 'ss-soc-5', q: 'Australian sociologist Evan Willis identifies four facets for practising the sociological imagination:', choices: ['Past, present, future and possible', 'Historical, cultural, structural and critical', 'Material, non-material, symbolic and practical', 'Reward, coercive, expert and legitimate'], answer: 1, explanation: 'Willis named these four facets to operationalise Mills\'s sociological imagination.', unit: 3 },
  { id: 'ss-soc-6', q: 'Ethnocentrism is best described as:', choices: ['Understanding a culture on its own terms', 'Judging another culture by the standards of one\'s own', 'Acknowledging that all cultures are equal', 'Studying culture using primary research'], answer: 1, explanation: 'Ethnocentrism uses one\'s own culture as the yardstick — generally a barrier to sociological understanding.', unit: 3 },
  { id: 'ss-soc-7', q: 'Cultural relativism is best described as:', choices: ['Judging cultures against a universal standard', 'Understanding a culture on its own terms, within its own context', 'Ignoring cultural difference', 'Promoting one culture over others'], answer: 1, explanation: 'Relativism takes the culture\'s own framework as the lens — the opposite of ethnocentrism.', unit: 3 },
  { id: 'ss-soc-8', q: 'The Latin phrase "terra nullius" — used historically to justify European settlement of Australia — translates roughly as:', choices: ['Empty land / land belonging to no-one', 'New land', 'Sacred land', 'Crown land'], answer: 0, explanation: 'Terra nullius was the legal fiction that Australia was uninhabited prior to European arrival; overturned by Mabo (1992).', unit: 3 },
  { id: 'ss-soc-9', q: 'Which of the following is explicitly identified by the VCAA study design as a public MISCONCEPTION about Australian Indigenous cultures?', choices: ['That Indigenous Australians are diverse and have many distinct nations', 'That Australian Indigenous people share one single culture', 'That Indigenous languages number in the hundreds', 'That sovereignty was never ceded'], answer: 1, explanation: 'VCAA lists "shares one culture" as a misconception. There are 250+ language groups.', unit: 3 },
  { id: 'ss-soc-10', q: 'Which of the following is a public misconception about where Australian Indigenous people live?', choices: ['That most live in cities and regional centres', 'That they mainly live in arid areas of Australia', 'That they live across all states and territories', 'That many live in coastal areas'], answer: 1, explanation: 'The misconception is "mainly arid areas". In fact most Indigenous Australians live in urban and regional locations.', unit: 3 },
  { id: 'ss-soc-11', q: 'The first government policy phase used to suppress Australian Indigenous cultures (mid-1800s onwards) was:', choices: ['Assimilation', 'Integration', 'Protection and segregation', 'The Intervention (NTER)'], answer: 2, explanation: 'Protection and segregation policies (with reserves and mission stations) preceded assimilation, integration and the NTER.', unit: 3 },
  { id: 'ss-soc-12', q: 'The Australian government policy of ASSIMILATION (from 1937) aimed to:', choices: ['Preserve Indigenous languages', 'Absorb Indigenous people into the dominant non-Indigenous culture', 'Return land to traditional owners', 'Provide bilingual education in remote schools'], answer: 1, explanation: 'Assimilation sought to erase Indigenous distinctiveness — directly leading to the Stolen Generations.', unit: 3 },
  { id: 'ss-soc-13', q: 'The "Stolen Generations" refers to:', choices: ['Indigenous land taken under terra nullius', 'Indigenous children forcibly removed from their families under assimilation-era policies', 'Indigenous artworks held in museums', 'Indigenous languages no longer spoken'], answer: 1, explanation: 'Between the late 1800s and 1970s, governments forcibly removed Indigenous children from their families — the Stolen Generations.', unit: 3 },
  { id: 'ss-soc-14', q: 'The Northern Territory National Emergency Response (NTER), commonly known as "The Intervention", began in:', choices: ['1992', '2007', '2013', '2017'], answer: 1, explanation: 'The NTER was introduced by the Howard government in 2007 — a more recent example of suppression-era policy.', unit: 3 },
  { id: 'ss-soc-15', q: 'Symbolic reconciliation is best illustrated by:', choices: ['Government funding for Indigenous health programs', 'The 2008 National Apology to the Stolen Generations', 'The Closing the Gap policy targets', 'Native title legislation'], answer: 1, explanation: 'Speeches, acknowledgements and apologies (including Rudd\'s 2008 Apology) are symbolic acts of reconciliation.', unit: 3 },
  { id: 'ss-soc-16', q: 'Practical reconciliation is best illustrated by:', choices: ['Rudd\'s 2008 Apology speech', 'Acknowledgement of Country at a public event', 'Government funding for Closing the Gap programs', 'A symbolic flag-raising ceremony'], answer: 2, explanation: 'Practical reconciliation involves measurable actions and resources targeting tangible outcomes.', unit: 3 },
  { id: 'ss-soc-17', q: 'The Mabo decision of 1992:', choices: ['Returned all Australian land to Indigenous ownership', 'Overturned terra nullius and recognised native title', 'Created the Closing the Gap framework', 'Established the Northern Territory Intervention'], answer: 1, explanation: 'Mabo (1992) recognised that Indigenous peoples had pre-existing rights to land — overturning terra nullius.', unit: 3 },
  { id: 'ss-soc-18', q: 'The "Uluru Statement from the Heart" was issued in:', choices: ['1992', '2008', '2017', '2023'], answer: 2, explanation: 'The Uluru Statement was delivered in May 2017 by First Nations delegates as a call for Voice, Treaty and Truth.', unit: 3 },
  { id: 'ss-soc-19', q: 'A school assembly opens with a non-Indigenous student saying "we acknowledge the Traditional Owners of the land on which we meet". Which protocol have they performed?', choices: ['A Welcome to Country', 'An Acknowledgement of Country', 'A Smoking Ceremony', 'A Treaty declaration'], answer: 1, explanation: 'A Welcome must be delivered by a Traditional Owner of that Country; an Acknowledgement can be offered by anyone — including non-Indigenous speakers.', unit: 3 },
  { id: 'ss-soc-20', q: 'Which sociological term describes a representation that judges another culture using the values of one\'s own?', choices: ['Culturally relativist', 'Ethnocentric', 'Symbolic', 'Material'], answer: 1, explanation: 'Ethnocentric representations evaluate others using one\'s own culture as the standard.', unit: 3 },
  { id: 'ss-soc-21', q: 'According to the study design, the period considered "contemporary" when analysing representations is typically:', choices: ['The last 12 months', 'The last 10 years', 'The last 50 years', 'Since 1992'], answer: 1, explanation: 'VCAA specifies "generally, contemporary representations are those created within the last ten years".', unit: 3 },
  { id: 'ss-soc-22', q: 'The 1967 referendum on Indigenous Australians:', choices: ['Granted Indigenous people the right to vote for the first time', 'Counted Indigenous Australians in the census and gave the federal government power to legislate for them', 'Returned land to traditional owners', 'Established the Stolen Generations program'], answer: 1, explanation: 'The 1967 referendum changed the Constitution to include Indigenous Australians in the census and gave the Commonwealth law-making power.', unit: 3 },
  { id: 'ss-soc-23', q: 'In sociological terms, an Indigenous response to suppression-era policies could include:', choices: ['Acceptance and assimilation', 'Maintaining language, ceremony, and cultural practices despite policy pressure', 'Disengaging from public discourse', 'Migration overseas'], answer: 1, explanation: 'Cultural survival — keeping languages, ceremonies and practices alive — is a key Indigenous response.', unit: 3 },
  { id: 'ss-soc-24', q: 'A traditional Aboriginal song line or "songline" is best categorised as:', choices: ['Material culture', 'Non-material culture', 'A government policy', 'A type of land title'], answer: 1, explanation: 'Songlines are oral traditions encoding knowledge — non-material culture.', unit: 3 },
  { id: 'ss-soc-25', q: 'Traditional Aboriginal stone tools are best categorised as:', choices: ['Material culture', 'Non-material culture', 'Symbolic reconciliation', 'A government policy'], answer: 0, explanation: 'Physical artefacts are material culture.', unit: 3 },
  { id: 'ss-soc-26', q: 'When a media representation centres on Indigenous voices speaking on their own terms, it most clearly demonstrates:', choices: ['Ethnocentrism', 'Cultural relativism', 'Terra nullius', 'Assimilation'], answer: 1, explanation: 'Letting a culture speak for itself, on its own terms, is cultural relativism in practice.', unit: 3 },
  { id: 'ss-soc-27', q: 'The "Closing the Gap" framework is best described as:', choices: ['A symbolic gesture of reconciliation', 'A practical reconciliation initiative targeting measurable life-outcome disparities', 'A native title court decision', 'A community-based language preservation program'], answer: 1, explanation: 'Closing the Gap sets measurable targets across health, education, employment etc. — practical reconciliation.', unit: 3 },
  { id: 'ss-soc-28', q: 'A historical representation portraying Indigenous Australians as "primitive" relative to European settlers is BEST described as:', choices: ['Culturally relativist', 'Ethnocentric', 'A symbolic act of reconciliation', 'An example of multiculturalism'], answer: 1, explanation: 'Ranking other cultures as "lesser" against one\'s own standards is the textbook definition of ethnocentrism.', unit: 3 },
  { id: 'ss-soc-29', q: 'Which of the following is a NON-material element of Wurundjeri Woi-Wurrung culture?', choices: ['Traditional tools', 'Language and Dreaming stories', 'Body paint pigments', 'Coolamons (carrying vessels)'], answer: 1, explanation: 'Language and Dreaming are intangible — non-material culture. The other examples are tangible objects.', unit: 3 },
  { id: 'ss-soc-30', q: 'A teacher acknowledges the Traditional Owners of the land at the start of class. Which form of reconciliation does this best illustrate?', choices: ['Practical reconciliation', 'Symbolic reconciliation', 'Native title', 'Assimilation'], answer: 1, explanation: 'Acknowledgements are symbolic — they recognise sovereignty and presence without delivering material outcomes directly.', unit: 3 },
  { id: 'ss-soc-31', q: 'When sociologists "engage the sociological imagination" to study a culture, they:', choices: ['Look only at individual experiences in isolation', 'Look only at large-scale structures', 'Connect personal experiences to the wider historical and social structures that shape them', 'Avoid theory in favour of raw data'], answer: 2, explanation: 'Mills\'s imagination links the personal (troubles) to the structural (issues).', unit: 3 },
  { id: 'ss-soc-32', q: 'Per VCAA terminology, "First Nations Peoples" refers to:', choices: ['Recent immigrants to Australia', 'Aboriginal and Torres Strait Islander Peoples', 'Australian-born citizens', 'European settlers'], answer: 1, explanation: 'First Nations Peoples refers to Aboriginal and Torres Strait Islander Peoples — Australia\'s first peoples.', unit: 3 },
  { id: 'ss-soc-33', q: 'The PROTECTION-era policies established reserves and mission stations primarily to:', choices: ['Promote Indigenous self-determination', 'Restrict and control Indigenous people\'s movement and lives', 'Return land to traditional owners', 'Recognise Indigenous sovereignty'], answer: 1, explanation: 'Despite the name, "protection" policies controlled and confined Indigenous people, often dispossessing them of land and family.', unit: 3 },
  { id: 'ss-soc-34', q: 'The 2008 National Apology was delivered by:', choices: ['John Howard', 'Kevin Rudd', 'Paul Keating', 'Anthony Albanese'], answer: 1, explanation: 'Prime Minister Kevin Rudd delivered the Apology to the Stolen Generations on 13 February 2008.', unit: 3 },
  { id: 'ss-soc-35', q: 'Paul Keating\'s "Redfern speech" (1992) is best categorised as an example of:', choices: ['Symbolic reconciliation', 'Practical reconciliation', 'Terra nullius', 'A government suppression policy'], answer: 0, explanation: 'The Redfern speech publicly acknowledged historical wrongs — a landmark act of symbolic reconciliation.', unit: 3 },
  { id: 'ss-soc-36', q: 'The Northern Territory Intervention (NTER) is criticised by many sociologists because it:', choices: ['Recognised Indigenous sovereignty', 'Reintroduced top-down government control over Indigenous communities, echoing earlier suppression-era policies', 'Followed Indigenous community consultation', 'Was a purely symbolic gesture'], answer: 1, explanation: 'NTER suspended the Racial Discrimination Act in affected areas and was widely seen as paternalistic — echoes of earlier control-based policies.', unit: 3 },
  { id: 'ss-soc-37', q: 'The Aboriginal Tent Embassy, established in 1972 outside Parliament House in Canberra, is best understood as:', choices: ['A government-funded reconciliation program', 'An Indigenous-led response asserting sovereignty and demanding land rights', 'A tourist attraction', 'A symbolic Acknowledgement of Country'], answer: 1, explanation: 'The Tent Embassy is a long-running Indigenous protest asserting unceded sovereignty and demanding land rights.', unit: 3 },
  { id: 'ss-soc-38', q: 'Saying "Indigenous Australians all live a traditional desert lifestyle" is an example of:', choices: ['Cultural relativism', 'A public misconception VCAA explicitly identifies', 'Practical reconciliation', 'A non-material cultural element'], answer: 1, explanation: 'VCAA lists the "mainly arid areas" perception as a misconception. Most Indigenous Australians live in urban / regional areas.', unit: 3 },
  { id: 'ss-soc-39', q: 'A speech that emphasises Indigenous Australians\' resilience and continuing connection to Country is best described as:', choices: ['Ethnocentric', 'A form of symbolic reconciliation', 'A practical funding program', 'A suppression-era policy'], answer: 1, explanation: 'Speeches affirming Indigenous experience are acts of symbolic reconciliation.', unit: 3 },
  { id: 'ss-soc-40', q: 'Which is a more sociologically appropriate term: "Aboriginal cultures" or "Aboriginal culture"?', choices: ['"Culture" — Indigenous Australians share one culture', '"Cultures" — there are many distinct nations and language groups', 'Both are interchangeable', 'Neither — the correct term is "society"'], answer: 1, explanation: 'Plural "cultures" correctly reflects Indigenous diversity — addressing the public misconception.', unit: 3 },
  { id: 'ss-soc-41', q: 'A documentary featuring only non-Indigenous experts commenting on Indigenous culture is most vulnerable to the criticism that it is:', choices: ['Culturally relativist', 'Ethnocentric and lacks Indigenous voices', 'A form of practical reconciliation', 'A non-material artefact'], answer: 1, explanation: 'Centring outside voices about a culture is ethnocentric; cultural relativism would foreground Indigenous voices themselves.', unit: 3 },
  { id: 'ss-soc-42', q: 'The Yorta Yorta and Wurundjeri are examples of:', choices: ['Two ethnic groups within Australia\'s migrant communities', 'Two distinct Australian Indigenous nations/language groups', 'Two government policies', 'Two reconciliation programs'], answer: 1, explanation: 'They are distinct Indigenous nations — evidence against the misconception of "one Indigenous culture".', unit: 3 },
  { id: 'ss-soc-43', q: 'A representation that respectfully shows a culture\'s rituals as meaningful in their own context is BEST described as:', choices: ['Ethnocentric', 'Culturally relativist', 'A public misconception', 'A government policy'], answer: 1, explanation: 'Respecting another culture\'s practices on their own terms is cultural relativism.', unit: 3 },
  { id: 'ss-soc-44', q: 'Native title (recognised after Mabo, 1992) gives Indigenous Australians:', choices: ['Full freehold ownership of all Australian land', 'A legally recognised but limited form of land rights based on continuing connection to Country', 'Government funding only', 'A symbolic but not legal recognition'], answer: 1, explanation: 'Native title is a legal recognition of certain ongoing Indigenous rights to land — narrower than freehold but a real legal status.', unit: 3 },
  { id: 'ss-soc-45', q: 'The INTEGRATION policy (1965 onwards) differed from earlier ASSIMILATION policy in that:', choices: ['Integration sought to erase Indigenous distinctiveness entirely', 'Integration allowed some retention of Indigenous identity while encouraging participation in mainstream society', 'Integration restored Indigenous land rights', 'Integration was identical to assimilation in every respect'], answer: 1, explanation: 'Integration softened assimilation by allowing some retention of Indigenous identity — though still pushing mainstream participation.', unit: 3 },
  { id: 'ss-soc-46', q: 'A sociologist wants to evaluate Australian public awareness of Indigenous cultures. Which approach offers the strongest evidence base?', choices: ['Census ancestry data combined with parliamentary speeches', 'Academic sociology journals and government policy documents', 'Triangulation across speeches, news media, social media, Indigenous-produced content and academic literature', 'A single nationally representative opinion poll'], answer: 2, explanation: 'Triangulation across multiple source types is the standard sociological approach for studying public awareness — no single source captures it adequately.', unit: 3 },
  { id: 'ss-soc-47', q: 'A truth-telling commission is most directly an example of:', choices: ['Practical reconciliation', 'Symbolic reconciliation', 'Native title', 'Cultural suppression'], answer: 1, explanation: 'Truth-telling is symbolic — public acknowledgement of historical wrongs through honest narrative.', unit: 3 },
  { id: 'ss-soc-48', q: 'When non-Indigenous individuals advocate for Indigenous rights publicly, they are best described as:', choices: ['Ethnocentric', 'Allies engaging with the reconciliation process', 'Cultural relativists by definition', 'Practising terra nullius'], answer: 1, explanation: 'Non-Indigenous allies play a recognised role in supporting reconciliation efforts.', unit: 3 },
  { id: 'ss-soc-49', q: 'A Year 12 essay on contemporary Indigenous experience should draw on historical context spanning:', choices: ['The post-2000 reconciliation era only', 'Protection-era policies through assimilation, integration, the 1967 referendum, Mabo, the Apology and contemporary Indigenous responses', 'The colonial period (1788–1901) only', 'The years since the Voice referendum (2023 onwards)'], answer: 1, explanation: 'Mills\'s sociological imagination requires depth across multiple eras AND attention to ongoing Indigenous responses, not just any single phase.', unit: 3 },
  { id: 'ss-soc-50', q: 'A common feature of CULTURALLY RELATIVIST representations is that they:', choices: ['Compare other cultures unfavourably to one\'s own', 'Present the culture on its own terms, often through its own voices', 'Use only quantitative data', 'Avoid discussing culture at all'], answer: 1, explanation: 'Relativism foregrounds the culture\'s self-understanding — often via direct voices and on-the-ground context.', unit: 3 },

  // -- Unit 3 AOS 2: Ethnicity (51–100) --
  { id: 'ss-soc-51', q: 'Most sociologists prefer to focus on the concept of ETHNICITY rather than RACE because:', choices: ['Race is more scientifically valid', 'Ethnicity captures shared cultural heritage rather than visible physical traits', 'Race is easier to define', 'Ethnicity is older as a concept'], answer: 1, explanation: 'Sociologists largely reject "race" as a scientific category and prefer "ethnicity" — a cultural concept.', unit: 3 },
  { id: 'ss-soc-52', q: 'The sociological concept of "othering" refers to:', choices: ['Polite respect for outsiders', 'Defining and labelling individuals or groups as not fitting within the norms of a social group', 'A type of multiculturalism', 'A research methodology'], answer: 1, explanation: 'Othering marks particular groups as outside the in-group\'s norms — often a precursor to prejudice.', unit: 3 },
  { id: 'ss-soc-53', q: 'The theory of CULTURAL HYBRIDITY is most associated with:', choices: ['Charles Wright Mills', 'Stuart Hall', 'Erica Chenoweth', 'Ferdinand Tönnies'], answer: 1, explanation: 'Stuart Hall developed cultural hybridity to capture dual or multiple cultural identities.', unit: 3 },
  { id: 'ss-soc-54', q: 'Stuart Hall\'s theory of cultural hybridity argues that cultural identity is:', choices: ['Determined at birth by ancestral heritage', 'Fluid, blending elements from multiple cultural backgrounds across time', 'Set by the dominant national culture of the country one lives in', 'Best understood as a single fixed ethnic category'], answer: 1, explanation: 'Hall argued identity is a process of "becoming" — never finished, always blending elements through migration, diaspora and globalisation.', unit: 3 },
  { id: 'ss-soc-55', q: 'A second-generation Australian who speaks both their parents\' language at home and English at work most clearly illustrates:', choices: ['Assimilation', 'Cultural hybridity', 'Ethnocentrism', 'Coercive power'], answer: 1, explanation: 'Holding multiple cultural identities in tandem — exactly what Hall describes as hybridity.', unit: 3 },
  { id: 'ss-soc-56', q: 'Australia\'s official policy of MULTICULTURALISM was introduced in:', choices: ['1901', '1947', '1973', '2001'], answer: 2, explanation: 'The Whitlam government formally adopted multiculturalism in 1973, replacing the White Australia Policy.', unit: 3 },
  { id: 'ss-soc-57', q: 'The White Australia Policy (formally the Immigration Restriction Act) was enacted in:', choices: ['1788', '1901', '1945', '1973'], answer: 1, explanation: 'Passed in 1901 at Federation, it restricted non-European migration until being dismantled through the 1960s–70s.', unit: 3 },
  { id: 'ss-soc-58', q: 'Multiculturalism, as a policy, differs from ASSIMILATION in that:', choices: ['Assimilation absorbs minorities into the dominant culture; multiculturalism preserves and celebrates difference', 'They are identical', 'Multiculturalism forces minorities to abandon their traditions', 'Assimilation actively promotes ethnic diversity'], answer: 0, explanation: 'Assimilation = absorb. Multiculturalism = retain and respect cultural difference.', unit: 3 },
  { id: 'ss-soc-59', q: 'Approximately what proportion of Australians were born overseas (per recent census data)?', choices: ['About 5%', 'About 15%', 'About 30%', 'About 70%'], answer: 2, explanation: '~30% of Australians were born overseas — among the highest rates in the developed world.', unit: 3 },
  { id: 'ss-soc-60', q: 'Per VCAA terminology, which of these is NOT one of the four ethical methodology elements?', choices: ['Voluntary participation', 'Informed consent', 'Privacy and confidentiality', 'Mandatory reporting'], answer: 3, explanation: 'The four elements: voluntary participation, informed consent, privacy, and confidentiality of data.', unit: 3 },
  { id: 'ss-soc-61', q: 'Informed consent in sociological research means that:', choices: ['Researchers can withhold the study\'s purpose to avoid bias', 'Participants are told the purpose, nature and implications of the study before agreeing', 'Researchers obtain government approval', 'Participants are paid to take part'], answer: 1, explanation: 'Informed consent requires participants to understand what they are agreeing to.', unit: 3 },
  { id: 'ss-soc-62', q: 'Confidentiality of data in research requires that:', choices: ['Data is published with full participant identification', 'Information collected is not shared beyond the agreed scope', 'Researchers withhold all findings', 'Government approval is obtained'], answer: 1, explanation: 'Confidentiality protects participants — collected info stays within the agreed-upon use.', unit: 3 },
  { id: 'ss-soc-63', q: 'Voluntary participation in sociological research requires that:', choices: ['Participants are coerced for their own good', 'Participants choose freely to take part, without pressure, and can withdraw at any time', 'Researchers select participants randomly without their knowledge', 'Participants are paid to ensure compliance'], answer: 1, explanation: 'No coercion, free choice to participate or withdraw — the heart of voluntary participation.', unit: 3 },
  { id: 'ss-soc-64', q: 'The professional body that publishes Australian sociological ethical guidelines is the:', choices: ['VCAA', 'Australian Sociological Association (TASA)', 'Australian Bureau of Statistics', 'United Nations'], answer: 1, explanation: 'TASA — The Australian Sociological Association — publishes the ethical guidelines.', unit: 3 },
  { id: 'ss-soc-65', q: 'Negative or stereotypical media representations of an ethnic group are most likely to:', choices: ['Strengthen the group\'s sense of belonging', 'Reinforce othering and weaken belonging', 'Have no effect on belonging', 'Increase multicultural understanding'], answer: 1, explanation: 'Negative representations contribute to othering and prejudice, undermining inclusion.', unit: 3 },
  { id: 'ss-soc-66', q: 'Government funding for community-language schools is an example of which factor influencing belonging?', choices: ['Cultural practices', 'Media representations', 'Political factors', 'Geographical characteristics'], answer: 2, explanation: 'Government policy and funding fall under political factors per the study design.', unit: 3 },
  { id: 'ss-soc-67', q: 'A restaurant celebrating an ethnic group\'s cuisine that draws mixed clientele is most clearly:', choices: ['A form of othering', 'A response that may foster belonging by visibility and acceptance', 'A government policy', 'An ethical breach'], answer: 1, explanation: 'Positive cultural visibility (e.g. via food, festivals) can enable belonging and reduce othering.', unit: 3 },
  { id: 'ss-soc-68', q: 'When the way a group sees ITSELF differs from the way OUTSIDERS see it, sociologists describe this as:', choices: ['An issue of cultural identity vs imposed categorisation', 'Always indicating othering', 'A flawed survey result', 'Pure cultural hybridity'], answer: 0, explanation: 'A core sociological insight: imposed categories don\'t always match self-identification.', unit: 3 },
  { id: 'ss-soc-69', q: 'Recent migrants who form ethnic enclaves (e.g. cultural precincts) are often described by sociologists as:', choices: ['Failing to integrate', 'Building social support and preserving culture while engaging with the wider society', 'Practising assimilation', 'Practising terra nullius'], answer: 1, explanation: 'Ethnic enclaves provide social capital and cultural continuity — and can be part of broader multicultural participation.', unit: 3 },
  { id: 'ss-soc-70', q: 'The concept of "diaspora" refers to:', choices: ['A government immigration department', 'A community of people living away from their ancestral homeland', 'A type of ethnic prejudice', 'A research method'], answer: 1, explanation: 'Diaspora describes populations dispersed from a homeland — often retaining cultural ties.', unit: 3 },
  { id: 'ss-soc-71', q: 'A sociologist conducting a full study of an ethnic group should examine which combination of evidence?', choices: ['Material culture (food, dress, arts) and government policy', 'Non-material culture (values, beliefs, language) and Census statistics', 'Material culture, non-material culture, and members\' own self-identification', 'Government policy and historical migration data'], answer: 2, explanation: 'A full sociological study triangulates tangible artefacts, intangible beliefs, AND how the group defines itself — without self-identification, the picture is incomplete.', unit: 3 },
  { id: 'ss-soc-72', q: 'A media story portraying all members of an ethnic group as criminals is an example of:', choices: ['Cultural hybridity', 'Stereotyping and othering', 'Multicultural inclusion', 'Ethical research practice'], answer: 1, explanation: 'Such representations stereotype and "other" the group — well-documented mechanisms of prejudice.', unit: 3 },
  { id: 'ss-soc-73', q: 'Stuart Hall\'s theory of cultural hybridity is particularly useful for understanding:', choices: ['Indigenous land claims', 'Second-generation migrants navigating multiple cultural identities', 'Government taxation policy', 'Crime rates'], answer: 1, explanation: 'Hybridity speaks directly to the experience of people moving between cultural worlds.', unit: 3 },
  { id: 'ss-soc-74', q: 'According to VCAA, "race" is generally rejected by sociologists because:', choices: ['It is too modern a concept', 'It is based on visible physical characteristics and lacks scientific validity as a social category', 'It overlaps too much with ethnicity', 'It is too specific'], answer: 1, explanation: 'Race lacks a sound biological basis; ethnicity is the more meaningful sociological category.', unit: 3 },
  { id: 'ss-soc-75', q: 'When a sociologist asks participants to sign a written consent form explaining the study, they are demonstrating:', choices: ['Othering', 'Informed consent (an element of ethical methodology)', 'Cultural relativism', 'Coercive power'], answer: 1, explanation: 'Consent forms are the standard mechanism for documenting informed consent.', unit: 3 },
  { id: 'ss-soc-76', q: 'When a sociologist removes participant names from research outputs, they are demonstrating:', choices: ['Privacy and confidentiality of data', 'Othering', 'Cultural hybridity', 'Assimilation'], answer: 0, explanation: 'De-identification protects participants\' privacy and the confidentiality of their data.', unit: 3 },
  { id: 'ss-soc-77', q: 'A factor that may PREVENT belonging in multicultural Australia is:', choices: ['Inclusive government policy', 'Positive media representation', 'Public hostility to a group\'s cultural practices', 'Cultural diversity within schools'], answer: 2, explanation: 'Hostile public responses to cultural practices are a leading barrier to belonging.', unit: 3 },
  { id: 'ss-soc-78', q: 'A factor that may ENABLE belonging in multicultural Australia is:', choices: ['Public hostility to cultural practices', 'Inclusive media representations that humanise the group', 'Restrictive immigration policies', 'Government withdrawal of funding'], answer: 1, explanation: 'Humanising representations build understanding and foster belonging.', unit: 3 },
  { id: 'ss-soc-79', q: 'A festival where multiple ethnic communities share traditions is best described as a public event that:', choices: ['Reinforces othering', 'Supports multicultural belonging through shared visibility', 'Embodies cultural suppression', 'Demonstrates assimilation'], answer: 1, explanation: 'Festivals enable cultural exchange and visibility — core to multicultural inclusion.', unit: 3 },
  { id: 'ss-soc-80', q: 'The concept of "in-group" and "out-group" is closely connected to:', choices: ['Cultural hybridity', 'Othering', 'Multiculturalism', 'Reconciliation'], answer: 1, explanation: 'In-group / out-group dynamics underpin othering — defining who "belongs" and who doesn\'t.', unit: 3 },
  { id: 'ss-soc-81', q: 'A sociologist researching an ethnic group who fails to obtain informed consent is breaching:', choices: ['A funding requirement', 'A core principle of ethical methodology', 'A copyright law', 'A government regulation only'], answer: 1, explanation: 'Informed consent is a foundational ethical principle in sociological research.', unit: 3 },
  { id: 'ss-soc-82', q: 'A community-language radio station that broadcasts in Cantonese for Sydney\'s Chinese community most clearly supports:', choices: ['Assimilation', 'Cultural maintenance and belonging within Australia\'s multicultural framework', 'Ethnocentrism', 'Othering'], answer: 1, explanation: 'Such services help maintain culture and belonging within a multicultural Australia.', unit: 3 },
  { id: 'ss-soc-83', q: 'Government discourse that frames migrants as a "threat" tends to:', choices: ['Support belonging', 'Promote othering and weaken inclusion', 'Promote cultural hybridity', 'Have no measurable effect'], answer: 1, explanation: 'Hostile political framing fuels othering and weakens multicultural inclusion.', unit: 3 },
  { id: 'ss-soc-84', q: 'A second-generation Vietnamese-Australian who celebrates Tết (Lunar New Year) and Christmas equally most clearly illustrates:', choices: ['Cultural assimilation', 'Cultural hybridity', 'Cultural suppression', 'Ethnocentrism'], answer: 1, explanation: 'Embracing multiple cultural traditions simultaneously is hybridity in action.', unit: 3 },
  { id: 'ss-soc-85', q: 'The shift from the WHITE AUSTRALIA POLICY to MULTICULTURALISM in the 1970s represented:', choices: ['A move toward stricter assimilation', 'A formal embrace of ethnic and cultural diversity in Australia', 'A return to terra nullius', 'A reconciliation programme'], answer: 1, explanation: 'Multiculturalism replaced the racist exclusion of the White Australia Policy with a celebration of diversity.', unit: 3 },
  { id: 'ss-soc-86', q: 'When a researcher allows participants to withdraw at any time, they are honouring which ethical element?', choices: ['Voluntary participation', 'Confidentiality of data', 'Cultural relativism', 'Random sampling'], answer: 0, explanation: 'The right to withdraw is part of voluntary participation.', unit: 3 },
  { id: 'ss-soc-87', q: 'A common feature of OTHERING is:', choices: ['Treating the "other" group as undifferentiated and outside the norms of the in-group', 'Promoting cultural hybridity', 'Centring the other group\'s voices', 'Funding community programs'], answer: 0, explanation: 'Othering flattens the "out-group" into a stereotype, treating its members as fundamentally different.', unit: 3 },
  { id: 'ss-soc-88', q: 'The Australian Bureau of Statistics census tracks ethnic diversity via questions on:', choices: ['Race only', 'Ancestry, country of birth and language spoken at home', 'Voting history', 'Tax records'], answer: 1, explanation: 'These three questions allow ABS to map Australia\'s ethnic and linguistic diversity.', unit: 3 },
  { id: 'ss-soc-89', q: 'When a sociologist studies a specific ethnic group, the group should be allowed to:', choices: ['Be defined by the researcher only', 'Define itself in its own terms', 'Be ignored if its self-definition is inconvenient', 'Be merged with another group'], answer: 1, explanation: 'Self-definition is critical — the group\'s own understanding of its ethnic identity is the starting point.', unit: 3 },
  { id: 'ss-soc-90', q: 'A media story that portrays a recent migrant group only via crime statistics is best described as:', choices: ['Culturally relativist', 'A negative, stereotyping representation that may fuel othering', 'A balanced sociological study', 'An ethical research output'], answer: 1, explanation: 'Single-frame negative portrayals reinforce stereotypes and othering.', unit: 3 },
  { id: 'ss-soc-91', q: 'Australia\'s ethnic diversity compared with comparable nations like the UK, Canada and Germany is:', choices: ['Significantly lower', 'Among the highest in the developed world by overseas-born proportion', 'Roughly equal in every dimension', 'Considered insignificant'], answer: 1, explanation: 'Australia has one of the highest overseas-born population shares of any developed country.', unit: 3 },
  { id: 'ss-soc-92', q: 'A primary research method that respects ethical methodology when interviewing migrants might include:', choices: ['Recording without telling participants', 'Explaining the purpose, obtaining written consent, anonymising data, and allowing withdrawal', 'Using deception to encourage frank responses', 'Skipping consent for efficiency'], answer: 1, explanation: 'The four elements — voluntary, informed, privacy, confidentiality — operationalised together.', unit: 3 },
  { id: 'ss-soc-93', q: 'Cultural hybridity, per Stuart Hall, tends to be associated with:', choices: ['Cultural decline', 'Migration, diaspora and globalisation', 'Cultural homogenisation', 'Suppression-era policies'], answer: 1, explanation: 'Hybridity emerges most visibly through migration, diaspora and globalising cultural flows.', unit: 3 },
  { id: 'ss-soc-94', q: 'Which pattern best describes a typical second-generation diaspora community?', choices: ['Complete cultural assimilation into the host society within one generation', 'Cultural, linguistic and emotional ties to the ancestral homeland alongside local adaptation', 'Strict cultural separation from the host society across generations', 'Political loyalty to the homeland combined with rejection of homeland cultural practices'], answer: 1, explanation: 'Diasporas typically blend homeland ties with local adaptation — producing hybrid identities (Stuart Hall) rather than full assimilation or separation.', unit: 3 },
  { id: 'ss-soc-95', q: 'When a public figure makes hostile remarks about an ethnic group, sociologists often analyse this as:', choices: ['A neutral observation', 'A political factor that may enable othering and weaken belonging', 'A purely personal statement with no social effect', 'A form of cultural hybridity'], answer: 1, explanation: 'Public political discourse shapes belonging — hostile remarks contribute to othering.', unit: 3 },
  { id: 'ss-soc-96', q: 'A research study claiming to represent an ethnic group should ideally include:', choices: ['The researcher\'s opinions only', 'Voices from within the group, captured ethically and with informed consent', 'Hostile critics\' views only', 'Anonymised non-members\' perspectives'], answer: 1, explanation: 'Centring the group\'s own voices, ethically gathered, is foundational sociological practice.', unit: 3 },
  { id: 'ss-soc-97', q: 'The role of media in multicultural Australia, sociologically, is to:', choices: ['Always reinforce stereotypes', 'Shape public perception of ethnic groups — for better or worse', 'Have no influence on belonging', 'Replace formal government policy'], answer: 1, explanation: 'Media representations are a major (though not sole) factor in shaping public attitudes and belonging.', unit: 3 },
  { id: 'ss-soc-98', q: 'A factor that may PREVENT belonging that relates to media representations is:', choices: ['Inclusive, varied portrayals of an ethnic group', 'Persistent negative or absent representations of an ethnic group', 'Government anti-discrimination campaigns', 'Community festivals'], answer: 1, explanation: 'Persistent negative or absent media portrayal correlates with lower public acceptance.', unit: 3 },
  { id: 'ss-soc-99', q: 'When VCAA refers to "cultural practices" as a factor influencing belonging, the term covers:', choices: ['Food, festivals and dress as visible markers of ethnic identity', 'Religious observance and language use as private aspects of culture', 'Customs, traditions, language, religious observance AND how the wider society responds to those practices', 'Government-funded cultural programs and their measurable outcomes'], answer: 2, explanation: 'VCAA frames cultural practices as both the practices themselves AND the wider society\'s response — belonging is shaped relationally, not just by what a group does.', unit: 3 },
  { id: 'ss-soc-100', q: 'An ethically conducted sociological study of an ethnic group should ALWAYS protect:', choices: ['The researcher\'s reputation', 'Participant welfare, including consent, privacy and confidentiality', 'Funding sources', 'The dominant culture\'s perspective'], answer: 1, explanation: 'TASA ethical guidelines centre participant welfare — consent, privacy, confidentiality, no harm.', unit: 3 },

  // -- Unit 4 AOS 1: Community (101–150) --
  { id: 'ss-soc-101', q: 'Sociologically, a "community" is best defined as:', choices: ['Any random group of people', 'A group sharing social relationships through proximity and/or regular contact, plus similarities like mutual interests or shared ideology', 'A government administrative area', 'A single household'], answer: 1, explanation: 'VCAA: relationships + similarities (interests/ideology) — with geographical proximity OR regular contact.', unit: 4 },
  { id: 'ss-soc-102', q: 'Per the VCAA study design, a strong "sense of community" is built primarily from:', choices: ['Physical proximity and frequent face-to-face contact', 'Active participation by members alongside emotional connection', 'A formal membership structure with elected leadership', 'Government recognition and ongoing public funding'], answer: 1, explanation: 'VCAA defines sense of community as active participation + emotional connection — proximity helps but is neither sufficient nor necessary.', unit: 4 },
  { id: 'ss-soc-103', q: 'Ferdinand Tönnies\'s "Gemeinschaft" describes:', choices: ['Modern, urban, contractual society', 'Traditional, rural, close-knit community based on kinship and shared values', 'A neo-tribe', 'A type of social movement'], answer: 1, explanation: 'Gemeinschaft = traditional community: kinship, shared values, mutual obligations.', unit: 4 },
  { id: 'ss-soc-104', q: 'Ferdinand Tönnies\'s "Gesellschaft" describes:', choices: ['Traditional rural community', 'Modern, urban, individualistic society characterised by contractual and transactional relationships', 'A neo-tribe', 'A specific ethnic group'], answer: 1, explanation: 'Gesellschaft = modern society: individualism, contracts, weaker kinship ties.', unit: 4 },
  { id: 'ss-soc-105', q: 'Tönnies argued that over time, societies have shifted:', choices: ['From Gesellschaft to Gemeinschaft', 'From Gemeinschaft to Gesellschaft', 'From neo-tribes to Gemeinschaft', 'From multiculturalism to assimilation'], answer: 1, explanation: 'Tönnies\'s thesis: modernisation moved society from traditional community (Gemeinschaft) to impersonal society (Gesellschaft).', unit: 4 },
  { id: 'ss-soc-106', q: 'Michel Maffesoli\'s theory of NEO-TRIBES describes:', choices: ['Traditional kinship-based societies', 'Postmodern communities organised around shared emotions, interests and lifestyles rather than geography', 'Government bureaucracies', 'A reconciliation framework'], answer: 1, explanation: 'Neo-tribes are fluid, interest-based postmodern groupings — sports fans, fandoms, music subcultures, online communities.', unit: 4 },
  { id: 'ss-soc-107', q: 'A key feature of Maffesoli\'s neo-tribes is that:', choices: ['Members must live in the same village', 'Members can belong to many tribes simultaneously, and tribes can be fluid and temporary', 'Membership is hereditary', 'Tribes always last for centuries'], answer: 1, explanation: 'Neo-tribes are characterised by fluidity, multiple memberships and emotional/aesthetic shared bonds.', unit: 4 },
  { id: 'ss-soc-108', q: 'An online fandom community gathered around a TV series is best understood through:', choices: ['Tönnies\'s Gemeinschaft', 'Maffesoli\'s neo-tribes', 'The Closing the Gap policy', 'Stuart Hall\'s hybridity'], answer: 1, explanation: 'Online fandoms are classic Maffesoli neo-tribes — interest-based, fluid, geographically dispersed.', unit: 4 },
  { id: 'ss-soc-109', q: 'A small farming village where residents have known each other for generations and share religious traditions illustrates:', choices: ['Gesellschaft', 'Gemeinschaft', 'A neo-tribe', 'A revolutionary social movement'], answer: 1, explanation: 'Tönnies\'s Gemeinschaft — traditional, kin-based, value-sharing.', unit: 4 },
  { id: 'ss-soc-110', q: 'A busy CBD where commuters interact transactionally and rarely know their neighbours illustrates:', choices: ['Gemeinschaft', 'Gesellschaft', 'A neo-tribe', 'Cultural relativism'], answer: 1, explanation: 'Tönnies\'s Gesellschaft — modern, urban, impersonal, transactional.', unit: 4 },
  { id: 'ss-soc-111', q: 'Information and communications technology (ICT) tends to:', choices: ['Eliminate all forms of community', 'Enable new (often geographically dispersed) communities while sometimes weakening local ties', 'Strengthen only Gemeinschaft', 'Have no measurable effect on community'], answer: 1, explanation: 'ICT both enables global connections AND can erode local face-to-face engagement.', unit: 4 },
  { id: 'ss-soc-112', q: 'A "third place" in community sociology refers to:', choices: ['A residence', 'A workplace', 'A public space (café, pub, park) where informal community life happens beyond home and work', 'A government building'], answer: 2, explanation: 'Coined by Ray Oldenburg — third places are vital informal spaces between home (first) and work (second).', unit: 4 },
  { id: 'ss-soc-113', q: 'An ECONOMIC factor that influences the experience of community is:', choices: ['The local climate', 'The presence of local businesses, employment opportunities, or economic decline', 'Geographical accessibility', 'Religious diversity'], answer: 1, explanation: 'Economic vitality directly affects community life — jobs, services, viability of local businesses.', unit: 4 },
  { id: 'ss-soc-114', q: 'A POLITICAL factor that influences the experience of community is:', choices: ['Local landforms', 'Local government decisions, funding allocations and policy', 'Climate', 'Population genetics'], answer: 1, explanation: 'Council decisions, funding and policy shape what a community can do.', unit: 4 },
  { id: 'ss-soc-115', q: 'Which list MOST COMPLETELY matches VCAA\'s "geographical characteristics" influencing community?', choices: ['Proximity, accessibility and climate', 'Climate, landforms, scenic quality and natural resources', 'Proximity, accessibility, climate, scenic quality, landforms, natural resources and built features', 'Built features, urban density and council boundaries'], answer: 2, explanation: 'VCAA\'s list is broad — all seven elements. Partial lists are common student errors that drop marks.', unit: 4 },
  { id: 'ss-soc-116', q: 'Maffesoli\'s neo-tribes contrast with Tönnies\'s Gemeinschaft in that they:', choices: ['Are also primarily kin-based', 'Are based on shared emotion and lifestyle rather than blood or locality', 'Are inherently religious', 'Are exclusively rural'], answer: 1, explanation: 'Neo-tribes are postmodern; Gemeinschaft is traditional. Different basis for the bond.', unit: 4 },
  { id: 'ss-soc-117', q: 'A community member who attends every event, shares the group\'s values and feels emotionally connected, BUT who experiences subtle exclusion from longstanding members, would be sociologically described as:', choices: ['Having full belonging because participation is high', 'Having partial belonging — the inclusion-by-others dimension is unmet', 'Having no belonging because they are new', 'Not a community member at all'], answer: 1, explanation: 'Belonging is multi-dimensional (participation + shared values + emotional connection + inclusion by others). High scores on three dimensions don\'t compensate when the fourth is unmet.', unit: 4 },
  { id: 'ss-soc-118', q: 'A community group that meets weekly to play sport, run by volunteers, is best described as:', choices: ['A government-mandated body', 'A community of practice / interest-based community that fosters belonging', 'A type of revolutionary social movement', 'An assimilationist policy'], answer: 1, explanation: 'Sports clubs are classic communities of practice — interest-based, participation-driven, belonging-generating.', unit: 4 },
  { id: 'ss-soc-119', q: 'An online support group for parents of children with rare diseases illustrates:', choices: ['Tönnies\'s Gesellschaft only', 'A digital community / Maffesoli neo-tribe formed around shared experience and emotion', 'Coercive power', 'A government welfare scheme'], answer: 1, explanation: 'Such groups are neo-tribes — shared emotion and interest transcend geography.', unit: 4 },
  { id: 'ss-soc-120', q: 'When ICT enables a person to participate in a global fandom while losing touch with their neighbours, sociologists describe this as:', choices: ['A reinforcement of Gemeinschaft', 'A trade-off where digital neo-tribes grow as local Gemeinschaft weakens', 'Total assimilation', 'A symbolic act of reconciliation'], answer: 1, explanation: 'ICT often shifts community from local face-to-face Gemeinschaft toward dispersed neo-tribes.', unit: 4 },
  { id: 'ss-soc-121', q: 'A SOCIAL factor that influences the experience of community is:', choices: ['Average rainfall', 'Schools, churches, social networks, demographic mix and community events', 'Number of roads', 'GDP per capita only'], answer: 1, explanation: 'Social factors include the institutions, networks and events that bring people together.', unit: 4 },
  { id: 'ss-soc-122', q: 'Compared with Tönnies\'s Gemeinschaft, Maffesoli\'s neo-tribes typically:', choices: ['Last much longer', 'Are more fluid, temporary and lifestyle-based', 'Are based on stronger kinship ties', 'Are inherently coercive'], answer: 1, explanation: 'Neo-tribes are deliberately framed as ephemeral and lifestyle-based — distinct from traditional community ties.', unit: 4 },
  { id: 'ss-soc-123', q: 'When sociologists evaluate whether a group counts as a "community", they typically look for:', choices: ['Geographical proximity ALONE', 'Some combination of relationships, shared interests/ideology, and a sense of belonging', 'Government registration', 'A formal constitution'], answer: 1, explanation: 'Multiple factors combine — relationships + similarities + belonging.', unit: 4 },
  { id: 'ss-soc-124', q: 'Climate change forcing residents to relocate from coastal towns is an example of:', choices: ['A neo-tribe formation', 'A geographical/environmental factor disrupting an existing community', 'A symbolic act of reconciliation', 'Coercive power exercised by a social movement'], answer: 1, explanation: 'Environmental factors can dissolve or reshape geographical communities.', unit: 4 },
  { id: 'ss-soc-125', q: 'A "sense of community" is most directly threatened by:', choices: ['Active participation', 'Social isolation, lack of trust, and weakening emotional ties', 'Local festivals', 'High volunteer rates'], answer: 1, explanation: 'Isolation and weak trust are the opposite of what makes community.', unit: 4 },
  { id: 'ss-soc-126', q: 'When researching a community ethically, the same four principles apply as in studying ethnic groups:', choices: ['Coercion, deception, secrecy, exclusion', 'Voluntary participation, informed consent, privacy, confidentiality of data', 'Funding, scope, methodology, reporting only', 'Geography, history, economics, politics'], answer: 1, explanation: 'The same TASA-derived ethical methodology applies across sociological research.', unit: 4 },
  { id: 'ss-soc-127', q: 'A regional town losing its only school is most directly affected by:', choices: ['A geographical factor', 'A political/economic factor with major social consequences for community life', 'A neo-tribe', 'Assimilation policy'], answer: 1, explanation: 'School closures often reflect economic and political decisions that profoundly weaken community.', unit: 4 },
  { id: 'ss-soc-128', q: 'A workplace where colleagues share lunch daily and support each other through life events is closest to:', choices: ['Gesellschaft only', 'A workplace Gemeinschaft / community of practice with strong belonging', 'A revolutionary movement', 'An assimilationist policy'], answer: 1, explanation: 'Some workplaces develop strong Gemeinschaft-like ties despite being modern institutions.', unit: 4 },
  { id: 'ss-soc-129', q: 'A group that gathers once a year for a music festival, with members from across the country, is best described as:', choices: ['A traditional Gemeinschaft', 'A neo-tribe that briefly intensifies belonging through shared lifestyle and emotion', 'A government policy', 'An ethical research method'], answer: 1, explanation: 'Music festivals epitomise Maffesoli\'s neo-tribes — temporary, lifestyle-based, emotionally bonded.', unit: 4 },
  { id: 'ss-soc-130', q: 'A "digital divide" affecting access to ICT may:', choices: ['Strengthen all communities equally', 'Exclude some members from online communities, weakening their sense of belonging', 'Be irrelevant to community sociology', 'Eliminate Gesellschaft'], answer: 1, explanation: 'Unequal ICT access excludes some from digital communities — a real community-belonging issue.', unit: 4 },
  { id: 'ss-soc-131', q: 'A factor that influences the experience of community AND is unique to online communities is:', choices: ['Local council policy', 'Platform design, moderation, algorithms and access to ICT', 'Local geography', 'Climate'], answer: 1, explanation: 'Online communities are shaped by platform mechanics — algorithms, moderation, ICT access — in ways physical communities aren\'t.', unit: 4 },
  { id: 'ss-soc-132', q: 'A community garden in a suburb is best understood as:', choices: ['Pure Gesellschaft', 'A geographically grounded community of practice fostering Gemeinschaft-like ties through shared activity', 'A neo-tribe with no shared activity', 'A symbolic act of reconciliation'], answer: 1, explanation: 'Community gardens combine geography, shared interest and active participation — quintessential community formation.', unit: 4 },
  { id: 'ss-soc-133', q: 'When Maffesoli wrote of "neo-tribes", he was describing a phenomenon associated with:', choices: ['The Industrial Revolution', 'Postmodernity / late modern society', 'The Middle Ages', 'Indigenous tribal societies'], answer: 1, explanation: 'Maffesoli\'s neo-tribes are a postmodern phenomenon — fluid, identity-based groupings of late modern society.', unit: 4 },
  { id: 'ss-soc-134', q: 'A community that successfully campaigns to save its local pool from closure demonstrates:', choices: ['Bureaucratic inertia', 'Active participation, emotional connection and collective power — a strong sense of community', 'Pure Gesellschaft', 'Assimilation'], answer: 1, explanation: 'Successful local mobilisation shows the participation + emotional connection that defines a strong community.', unit: 4 },
  { id: 'ss-soc-135', q: 'When a new highway divides a residential community in two, sociologists analyse this as:', choices: ['A geographical factor that may erode community ties through physical separation', 'A purely economic gain', 'A neo-tribe formation', 'A form of practical reconciliation'], answer: 0, explanation: 'Physical barriers (highways, walls) often fragment communities — a geographical and built-environment factor.', unit: 4 },
  { id: 'ss-soc-136', q: 'A regional town whose population shrinks as young people move to cities for work illustrates the effect of:', choices: ['ICT alone', 'Economic and social factors reshaping a community over time', 'Pure Maffesoli neo-tribe formation', 'A revolutionary social movement'], answer: 1, explanation: 'Economic opportunity drives demographic shift, which reshapes the community.', unit: 4 },
  { id: 'ss-soc-137', q: 'A modern HOUSEHOLD with high commute times and limited time for neighbours typifies:', choices: ['Gemeinschaft', 'Gesellschaft', 'A neo-tribe', 'A coercive movement'], answer: 1, explanation: 'Time-poor, transactional modern households exemplify Gesellschaft.', unit: 4 },
  { id: 'ss-soc-138', q: 'A men\'s shed group for older men in a suburb is best understood as:', choices: ['A government program', 'A community of practice fostering belonging through shared activity and conversation', 'A revolutionary social movement', 'A diaspora community'], answer: 1, explanation: 'Men\'s sheds are classic communities of practice — shared activity creates belonging and well-being.', unit: 4 },
  { id: 'ss-soc-139', q: 'When a community of locally owned shops is replaced by chain stores, sociologists may interpret this as:', choices: ['A move toward Gemeinschaft', 'An economic shift that may weaken local-community ties and shift the town toward Gesellschaft', 'Pure cultural relativism', 'An act of reconciliation'], answer: 1, explanation: 'Chain stores often weaken local ties; the shift typifies Tönnies\'s Gemeinschaft → Gesellschaft trajectory.', unit: 4 },
  { id: 'ss-soc-140', q: 'A community formed around a shared political identity (e.g. an activist network) is best described as:', choices: ['Gemeinschaft only', 'A neo-tribe formed around shared ideology', 'A diaspora', 'An ethnic group'], answer: 1, explanation: 'Politically organised communities of shared ideology fit Maffesoli\'s neo-tribe model.', unit: 4 },
  { id: 'ss-soc-141', q: 'A FACTOR that VCAA explicitly lists as influencing the experience of community is:', choices: ['Birthrate', 'Information and communications technology (ICT)', 'Currency exchange rate', 'Astrology'], answer: 1, explanation: 'VCAA explicitly names ICT as a key influence on contemporary community.', unit: 4 },
  { id: 'ss-soc-142', q: 'A sociology student wants to study a Melbourne ethnic-community organisation. The methodologically strongest approach is:', choices: ['Reading ABS Census data on the suburb', 'Combining ethically-conducted interviews and observation with relevant ABS and academic secondary sources', 'Asking three friends about their impressions of the community', 'Reading the organisation\'s website only'], answer: 1, explanation: 'Mixed methods (primary + secondary), conducted ethically, are the standard for VCAA-level sociological study. Single-source approaches miss the multi-dimensional nature of community.', unit: 4 },
  { id: 'ss-soc-143', q: 'A common feature of GEMEINSCHAFT-type communities is:', choices: ['Anonymity', 'Strong personal relationships, mutual obligation and shared traditions', 'Pure transactional exchange', 'Algorithmic curation of membership'], answer: 1, explanation: 'Gemeinschaft is defined by close personal bonds and mutual responsibility.', unit: 4 },
  { id: 'ss-soc-144', q: 'A common feature of GESELLSCHAFT-type societies is:', choices: ['Strong kinship-based bonds', 'Impersonal, contractual and transactional relationships', 'Universal mutual obligation', 'Inherited social roles'], answer: 1, explanation: 'Gesellschaft is impersonal and contract-based — typical of large modern societies.', unit: 4 },
  { id: 'ss-soc-145', q: 'Different members of the same community may experience the sense of community DIFFERENTLY because:', choices: ['Belonging is uniform for all', 'Factors like age, length of residence, ethnicity, ability and participation vary across members', 'Belonging is determined only by geography', 'Belonging is set by government decree'], answer: 1, explanation: 'Belonging is subjective and varies by individual circumstance and participation.', unit: 4 },
  { id: 'ss-soc-146', q: 'A retirement community combining shared spaces and resident-led activities reflects elements of:', choices: ['Pure Gesellschaft only', 'A planned Gemeinschaft-like community designed to foster belonging among similar residents', 'A neo-tribe with no shared geography', 'A revolutionary social movement'], answer: 1, explanation: 'Such communities deliberately recreate Gemeinschaft-like ties through shared geography and activities.', unit: 4 },
  { id: 'ss-soc-147', q: 'When a sociologist conducts FIELDWORK in a community, ethical practice requires them to:', choices: ['Observe secretly', 'Be transparent about their purpose, obtain consent, anonymise data and protect privacy', 'Avoid local cultural protocols', 'Publish identifying photographs without consent'], answer: 1, explanation: 'Transparency + consent + anonymisation = the ethical baseline.', unit: 4 },
  { id: 'ss-soc-148', q: 'A community newsletter that connects neighbours and shares local news mainly:', choices: ['Erodes community', 'Supports community by sharing information and fostering identification', 'Replaces the need for in-person interaction', 'Has no measurable effect'], answer: 1, explanation: 'Local information channels build the shared understanding that underpins community.', unit: 4 },
  { id: 'ss-soc-149', q: 'Maya lives in Glen Waverley, plays in a Melbourne ultimate-frisbee league, and moderates a global Reddit forum on board games. Sociologically, Maya:', choices: ['Belongs to only one true community — the geographical one', 'Belongs to multiple communities simultaneously — geographical, interest-based and online', 'Belongs to no real communities because none are exclusive', 'Belongs only to her online community because that is where she spends most time'], answer: 1, explanation: 'Multiple community memberships are normal in contemporary society — geographical, interest-based and digital can coexist for the same person.', unit: 4 },
  { id: 'ss-soc-150', q: 'Tönnies\'s and Maffesoli\'s theories are best described as:', choices: ['Identical', 'Complementary perspectives on how community has changed over time — Tönnies on the traditional-to-modern shift, Maffesoli on postmodern fragmentation', 'Mutually exclusive', 'Both refuted by modern research'], answer: 1, explanation: 'Tönnies and Maffesoli describe different historical phases — useful in combination for analysing contemporary community.', unit: 4 },

  // -- Unit 4 AOS 2: Social movements and social change (151–200) --
  { id: 'ss-soc-151', q: 'A SOCIAL MOVEMENT is best defined as:', choices: ['Any group of people in a crowd', 'A group engaged in an organised effort to achieve social change', 'A government department', 'A purely commercial enterprise'], answer: 1, explanation: 'VCAA definition: organised effort to achieve social change.', unit: 4 },
  { id: 'ss-soc-152', q: 'Per VCAA, the four TYPES of social movement are:', choices: ['Local, national, international, global', 'Alternative, redemptive, reformative, revolutionary', 'Peaceful, violent, hybrid, ambiguous', 'Emergence, coalescence, bureaucratisation, decline'], answer: 1, explanation: 'The four TYPES (do not confuse with the four STAGES, which is a different classification).', unit: 4 },
  { id: 'ss-soc-153', q: 'Per VCAA, the four STAGES of a social movement IN ORDER are:', choices: ['Emergence, coalescence, bureaucratisation, decline', 'Decline, coalescence, emergence, bureaucratisation', 'Alternative, redemptive, reformative, revolutionary', 'Reward, coercive, expert, legitimate'], answer: 0, explanation: 'Memorise this order: emergence → coalescence → bureaucratisation → decline.', unit: 4 },
  { id: 'ss-soc-154', q: 'An ALTERNATIVE social movement seeks:', choices: ['Radical change across the whole society', 'Limited change in a limited population (e.g. Mothers Against Drunk Driving targeting drink-driving behaviour)', 'Revolutionary overthrow of government', 'Religious conversion of a few'], answer: 1, explanation: 'Alternative = limited change + limited population. Narrow scope, narrow target.', unit: 4 },
  { id: 'ss-soc-155', q: 'A REDEMPTIVE social movement seeks:', choices: ['Limited change across the whole society', 'Radical change in a limited population (e.g. Alcoholics Anonymous transforming individual members)', 'Limited reform of the entire society', 'Pure violence'], answer: 1, explanation: 'Redemptive = radical change + limited population. Deep transformation of specific individuals.', unit: 4 },
  { id: 'ss-soc-156', q: 'A REFORMATIVE social movement seeks:', choices: ['Limited change across the whole society (e.g. environmental movements pushing legislation)', 'Radical change in a limited population', 'No change', 'Radical change across the whole society'], answer: 0, explanation: 'Reformative = limited change + whole society. Targets specific reforms across the wider population.', unit: 4 },
  { id: 'ss-soc-157', q: 'Per Aberle\'s typology, which combination of scope and target defines a REVOLUTIONARY movement?', choices: ['Limited change targeting individuals', 'Limited change targeting a group', 'Radical change targeting individuals', 'Radical change targeting the whole society'], answer: 3, explanation: 'Aberle\'s grid: Alternative (limited/individual), Redemptive (radical/individual), Reformative (limited/group), Revolutionary (radical/whole society).', unit: 4 },
  { id: 'ss-soc-158', q: 'The first stage of a social movement is:', choices: ['Coalescence', 'Decline', 'Emergence', 'Bureaucratisation'], answer: 2, explanation: 'Order: emergence → coalescence → bureaucratisation → decline.', unit: 4 },
  { id: 'ss-soc-159', q: 'In the COALESCENCE stage of a social movement:', choices: ['The movement ends', 'The movement organises, develops strategies, gains public awareness and identifies leaders', 'A formal bureaucracy is fully established with paid staff', 'The issue is first identified'], answer: 1, explanation: 'Coalescence is when scattered unrest becomes organised collective action with a recognised public profile.', unit: 4 },
  { id: 'ss-soc-160', q: 'In the BUREAUCRATISATION stage of a social movement:', choices: ['Activists first identify the issue', 'The movement establishes formal structures, leaders, paid staff and ongoing infrastructure', 'The movement disbands', 'The movement turns violent'], answer: 1, explanation: 'Bureaucratisation is institutionalisation — the movement becomes a formal organisation.', unit: 4 },
  { id: 'ss-soc-161', q: 'A movement can enter the DECLINE stage for any of the following reasons EXCEPT:', choices: ['Repression by authorities', 'Co-optation into the mainstream', 'Achievement of its goals', 'Acquiring its first leader'], answer: 3, explanation: 'Acquiring leaders is part of coalescence or bureaucratisation. Decline reasons: repression, co-optation, success, failure, mainstreaming.', unit: 4 },
  { id: 'ss-soc-162', q: 'Per VCAA, the SIX forms of power used by social movements (and their opposition) are:', choices: ['Reward, coercive, referent, legitimate, expert, informational', 'Strong, weak, neutral, hostile, friendly, ambiguous', 'Federal, state, local, civic, private, public', 'Symbolic, practical, material, non-material, structural, cultural'], answer: 0, explanation: 'Memorise the six: reward, coercive, referent, legitimate, expert, informational.', unit: 4 },
  { id: 'ss-soc-163', q: 'REWARD power involves:', choices: ['Force or threats', 'Offering incentives in exchange for compliance', 'Charisma', 'Position of authority'], answer: 1, explanation: 'Reward power exchanges incentives for compliance.', unit: 4 },
  { id: 'ss-soc-164', q: 'COERCIVE power involves:', choices: ['Charisma', 'Force, punishment or threats', 'Specialised knowledge', 'Control over information'], answer: 1, explanation: 'Coercive power compels via force or threat of force.', unit: 4 },
  { id: 'ss-soc-165', q: 'REFERENT power involves:', choices: ['Force', 'Charisma and identification — followers are drawn to the leader\'s personal qualities', 'Specialised expertise', 'Legal authority by position'], answer: 1, explanation: 'Referent power flows from charisma and admiration — followers identify with the leader.', unit: 4 },
  { id: 'ss-soc-166', q: 'LEGITIMATE power flows from:', choices: ['Personal charisma', 'A recognised position of authority (e.g. an elected official)', 'Specialised expertise', 'Control over information'], answer: 1, explanation: 'Legitimate power = the authority of one\'s position or office.', unit: 4 },
  { id: 'ss-soc-167', q: 'EXPERT power flows from:', choices: ['Charisma', 'Specialised knowledge or skills others rely on', 'Brute force', 'Holding office'], answer: 1, explanation: 'Expert power is granted to those with valued knowledge — scientists, doctors, technical specialists.', unit: 4 },
  { id: 'ss-soc-168', q: 'INFORMATIONAL power flows from:', choices: ['Force', 'Control over information — what is shared, when, and with whom', 'Charisma', 'Holding elected office'], answer: 1, explanation: 'Informational power: controlling the narrative, leaks, or selective disclosure.', unit: 4 },
  { id: 'ss-soc-169', q: 'Erica Chenoweth\'s comparative study of 20th-century civil resistance campaigns found that:', choices: ['Violent campaigns succeed about twice as often as non-violent ones', 'Non-violent campaigns succeed about twice as often as violent ones', 'Violent and non-violent campaigns have identical success rates', 'Mixed-tactic campaigns outperform either pure strategy'], answer: 1, explanation: 'Chenoweth\'s headline finding (Why Civil Resistance Works, 2011): non-violent movements succeed roughly twice as often as violent ones.', unit: 4 },
  { id: 'ss-soc-170', q: 'Chenoweth\'s research is relevant to VCE Sociology because it provides:', choices: ['A theory of cultural hybridity', 'Empirical evidence supporting non-violent strategy for social movements', 'A definition of Gemeinschaft', 'Australian census data'], answer: 1, explanation: 'VCAA names Chenoweth specifically as the evidence base for non-violent effectiveness claims.', unit: 4 },
  { id: 'ss-soc-171', q: 'A movement that uses social media to spread its message and recruit supporters is exercising primarily:', choices: ['Coercive power', 'Informational power', 'Legitimate power', 'Reward power'], answer: 1, explanation: 'Controlling narrative and reach via social media is a form of informational power.', unit: 4 },
  { id: 'ss-soc-172', q: 'Police using force to disperse a protest is exercising:', choices: ['Referent power', 'Coercive power', 'Expert power', 'Reward power'], answer: 1, explanation: 'Force and threats are coercive power — typical of state response to disruption.', unit: 4 },
  { id: 'ss-soc-173', q: 'A charismatic activist drawing thousands of supporters through inspirational speeches is exercising:', choices: ['Coercive power', 'Referent power', 'Legitimate power', 'Reward power'], answer: 1, explanation: 'Personal charisma that draws identification = referent power.', unit: 4 },
  { id: 'ss-soc-174', q: 'A government minister using their official authority to ban a protest exercises:', choices: ['Coercive power only', 'Legitimate power (and potentially coercive power)', 'Expert power', 'Referent power'], answer: 1, explanation: 'A minister\'s authority is legitimate (position-based); enforcement also involves coercive power.', unit: 4 },
  { id: 'ss-soc-175', q: 'Climate scientists\' testimony shaping climate movements is an example of:', choices: ['Coercive power', 'Expert power', 'Referent power', 'Reward power'], answer: 1, explanation: 'Specialised scientific knowledge granting influence = expert power.', unit: 4 },
  { id: 'ss-soc-176', q: 'When the fossil fuel industry funds political campaigns AND threatens job losses to oppose a climate movement, the industry is deploying which forms of power?', choices: ['Reward power and coercive power', 'Legitimate power and expert power', 'Referent power and informational power', 'Only coercive power'], answer: 0, explanation: 'Funding = reward power (positive incentive); job-loss threats = coercive power (negative consequence). The opposition can deploy any of the six power forms, often in combination.', unit: 4 },
  { id: 'ss-soc-177', q: 'A movement that successfully achieved a legislative reform and then gradually disbanded most likely passed through which stage sequence?', choices: ['Emergence → coalescence only (skipping later stages)', 'Coalescence → bureaucratisation → decline (success variant), skipping emergence', 'Emergence → coalescence → bureaucratisation → decline', 'Emergence → decline (skipping the middle two stages)'], answer: 2, explanation: 'Decline can be triggered by success (as well as failure, repression, or co-optation). Long-lived legislative-change movements typically traverse all four stages in order.', unit: 4 },
  { id: 'ss-soc-178', q: 'Co-optation as a cause of DECLINE refers to:', choices: ['Violent suppression', 'The movement\'s goals being absorbed by mainstream institutions, often softening the original aims', 'Loss of all members', 'Government funding'], answer: 1, explanation: 'Co-optation is a subtle decline mechanism — the movement effectively dissolves into the mainstream it sought to change.', unit: 4 },
  { id: 'ss-soc-179', q: 'Repression as a cause of DECLINE refers to:', choices: ['Voluntary disbanding', 'Forceful action by authorities to shut down the movement', 'Achievement of goals', 'Internal democratic vote'], answer: 1, explanation: 'Government or other powerful actors using coercive power to suppress the movement.', unit: 4 },
  { id: 'ss-soc-180', q: 'A movement that uses petitions, public letters and lobbying is most likely:', choices: ['A revolutionary movement', 'A reformative movement using primarily informational and legitimate channels', 'An alternative movement targeting individual behaviour', 'A redemptive movement transforming individual lives'], answer: 1, explanation: 'Such tactics aim at limited (legislative) change across the whole society — classic reformative.', unit: 4 },
  { id: 'ss-soc-181', q: 'Civil disobedience refers to:', choices: ['Violent overthrow', 'Deliberate, often public, non-compliance with laws considered unjust', 'Random vandalism', 'Voting in elections'], answer: 1, explanation: 'Civil disobedience is a calculated, often peaceful, refusal to comply with specific laws.', unit: 4 },
  { id: 'ss-soc-182', q: 'According to Chenoweth, non-violent movements succeed because they:', choices: ['Are always larger', 'Tend to attract broader, more diverse participation and lower the cost of joining', 'Use more coercive power', 'Are funded by governments'], answer: 1, explanation: 'Chenoweth attributes non-violent success partly to broader participation — many more people can safely join.', unit: 4 },
  { id: 'ss-soc-183', q: 'A movement is in the EMERGENCE stage when:', choices: ['It has a national office and paid staff', 'A social problem is being identified and there is initial unrest but no clear organisation yet', 'It has achieved its main aims', 'It has been formally disbanded'], answer: 1, explanation: 'Emergence is the earliest stage — issue recognised, initial discontent, no formal organisation.', unit: 4 },
  { id: 'ss-soc-184', q: 'The Civil Rights Movement in the United States is often analysed as an example of a:', choices: ['Alternative movement', 'Reformative movement that used primarily non-violent civil disobedience', 'Redemptive movement', 'Movement that never bureaucratised'], answer: 1, explanation: 'The Civil Rights Movement sought legislative change across society and famously used non-violent civil disobedience.', unit: 4 },
  { id: 'ss-soc-185', q: 'Mothers Against Drunk Driving (MADD) is often cited as an example of:', choices: ['A revolutionary movement', 'An alternative movement targeting a specific behaviour in a specific population', 'A redemptive movement', 'A reformative movement'], answer: 1, explanation: 'MADD targets a specific behaviour (drink-driving) in a specific population (drivers) — alternative.', unit: 4 },
  { id: 'ss-soc-186', q: 'Alcoholics Anonymous (AA) is often cited as an example of a:', choices: ['Reformative movement', 'Redemptive movement aiming for radical change within individual members', 'Revolutionary movement', 'Alternative movement'], answer: 1, explanation: 'AA targets radical transformation of individual lives — redemptive movement.', unit: 4 },
  { id: 'ss-soc-187', q: 'Environmental movements pushing for nationwide legislation are best classified as:', choices: ['Alternative', 'Redemptive', 'Reformative', 'Revolutionary'], answer: 2, explanation: 'Limited change (specific legislation) across the whole society = reformative.', unit: 4 },
  { id: 'ss-soc-188', q: 'A movement seeking to overthrow an entire political system is best classified as:', choices: ['Alternative', 'Redemptive', 'Reformative', 'Revolutionary'], answer: 3, explanation: 'Radical change across the whole society = revolutionary.', unit: 4 },
  { id: 'ss-soc-189', q: 'The Suffrage Movement that secured women\'s vote is typically classified as:', choices: ['Alternative', 'Redemptive', 'Reformative', 'Revolutionary'], answer: 2, explanation: 'Limited change (voting rights) across the whole society = reformative.', unit: 4 },
  { id: 'ss-soc-190', q: 'A grassroots campaign to save a local pool from closure (as on the 2025 exam) most likely demonstrates:', choices: ['A long-running revolutionary movement', 'An alternative movement that may move quickly through emergence → coalescence → decline (success)', 'A redemptive movement', 'No use of power'], answer: 1, explanation: 'A targeted local campaign aimed at saving one facility fits the alternative category and can move fast through stages.', unit: 4 },
  { id: 'ss-soc-191', q: 'A social movement that achieves its goals and ENDS is in:', choices: ['The emergence stage', 'The decline stage (success variant)', 'The bureaucratisation stage', 'No stage'], answer: 1, explanation: 'Success is one cause of decline — the movement disbands or transitions because its work is done.', unit: 4 },
  { id: 'ss-soc-192', q: 'A movement that has hired full-time staff, set up offices, and operates like an NGO is most likely in the:', choices: ['Emergence stage', 'Coalescence stage', 'Bureaucratisation stage', 'Decline stage'], answer: 2, explanation: 'Formal organisation with paid staff and infrastructure = bureaucratisation.', unit: 4 },
  { id: 'ss-soc-193', q: 'A movement\'s SOCIAL MEDIA INFLUENCERS sharing the movement\'s narrative exercise primarily:', choices: ['Coercive power', 'Referent power (charisma) combined with informational power (control over messaging)', 'Legitimate power', 'Reward power'], answer: 1, explanation: 'Influencers leverage personal charisma (referent) and message control (informational).', unit: 4 },
  { id: 'ss-soc-194', q: 'A movement\'s OPPOSITION publishing reports that contradict the movement\'s claims is exercising:', choices: ['Coercive power', 'Informational power (and possibly expert power if scientists are involved)', 'Reward power', 'Referent power'], answer: 1, explanation: 'Counter-narrative via reports = informational; with expert authors, also expert power.', unit: 4 },
  { id: 'ss-soc-195', q: 'An ALTERNATIVE movement and a REVOLUTIONARY movement differ primarily in:', choices: ['Whether they use power', 'The SCOPE of intended change (limited vs radical) AND the breadth of the target population (limited vs whole society)', 'Whether they have leaders', 'Whether they operate online'], answer: 1, explanation: 'The classification axis: scope of change × breadth of target population.', unit: 4 },
  { id: 'ss-soc-196', q: 'Per Chenoweth\'s research, a non-violent movement is roughly:', choices: ['Half as likely to succeed as a violent movement', 'Twice as likely to succeed as a violent movement', 'Identical in success rate to a violent movement', 'Always guaranteed to succeed'], answer: 1, explanation: 'Chenoweth\'s headline finding: non-violent movements succeed about twice as often as violent ones.', unit: 4 },
  { id: 'ss-soc-197', q: 'The CONCEPT of "social change" refers to:', choices: ['Any change in fashion trends', 'Significant alteration in social structures, institutions, norms or relationships over time', 'Daily routine changes', 'Personal mood shifts'], answer: 1, explanation: 'Social change is structural — institutions, norms, relationships shift.', unit: 4 },
  { id: 'ss-soc-198', q: 'A movement that successfully pushes for a new anti-discrimination law has achieved:', choices: ['Symbolic change only', 'A measurable form of social change through legislation', 'A reduction in its own bureaucracy', 'Co-optation only'], answer: 1, explanation: 'Legislative reform is a concrete form of social change.', unit: 4 },
  { id: 'ss-soc-199', q: 'A movement that has lost its momentum and shrunk in membership without achieving its goals is in:', choices: ['Emergence', 'Coalescence', 'Bureaucratisation', 'Decline (failure variant)'], answer: 3, explanation: 'Decline can come from success, co-optation, repression OR failure.', unit: 4 },
  { id: 'ss-soc-200', q: 'A VCAA Unit 4 AOS 2 extended response on a current social movement should integrate which four analytical lenses?', choices: ['Type (Aberle), funding sources, founder biography, public popularity', 'Type, current stage, founder biography, social media presence', 'Type, current stage, power used by movement, opposition\'s power AND Chenoweth-informed evaluation of influence on social change', 'Goals, achievements, leadership structure and ideological position'], answer: 2, explanation: 'The full VCAA analytical lens has four interrelated parts: type, stage, dual power analysis, and influence-on-change evaluated through Chenoweth. Missing any one drops marks.', unit: 4 },
  // ── Textbook-anchored batch (ss-soc-201 to ss-soc-300) ──
  // AOS 1 — Indigenous cultures (K'gari / Butchulla case study + study-design depth)
  { id: 'ss-soc-201', q: 'In the textbook case study, what is the traditional Butchulla name for the world\'s largest sand island, restored in 2023?', choices: ['Uluru', 'K\'gari', 'Murujuga', 'Budj Bim'], answer: 1, explanation: 'In 2023 Premier Annastacia Palaszczuk announced "Fraser Island" would be officially renamed K\'gari, reflecting the Butchulla people\'s traditional name.', unit: 3 },
  { id: 'ss-soc-202', q: 'Before its 2023 renaming, K\'gari was officially called "Fraser Island" — named after:', choices: ['A Butchulla elder', 'Eliza Fraser, a shipwreck survivor', 'A British colonial governor', 'A Dutch explorer'], answer: 1, explanation: 'The island was named after Eliza Fraser, who survived a shipwreck there in 1836 — a name imposed by colonial naming rather than recognising Butchulla custodianship.', unit: 3 },
  { id: 'ss-soc-203', q: 'The renaming of Fraser Island to K\'gari best illustrates which form of cultural continuance?', choices: ['Economic continuance only', 'Linguistic and place-based continuance — restoring Indigenous names to Country', 'Religious continuance only', 'Genetic continuance'], answer: 1, explanation: 'Restoring an Indigenous place name re-asserts Country, language and custodianship — a visible act of cultural continuance.', unit: 3 },
  { id: 'ss-soc-204', q: 'When a non-Indigenous brand uses Aboriginal dot-painting designs without permission or attribution, this is best described as:', choices: ['Cultural appreciation', 'Cultural appropriation', 'Cultural continuance', 'Cultural relativism'], answer: 1, explanation: 'Taking elements of a culture out of context, without consent or benefit to the source community, is appropriation — not appreciation.', unit: 3 },
  { id: 'ss-soc-205', q: 'According to the study design, students must compare the experiences and responses of TWO Indigenous cultures: one from Australia and one from:', choices: ['Europe', 'Anywhere outside Australia (e.g. Aotearoa NZ, North America, Sápmi)', 'Asia only', 'Africa only'], answer: 1, explanation: 'AOS 1 requires a comparative study: an Australian Indigenous culture AND an Indigenous culture from elsewhere in the world.', unit: 3 },
  { id: 'ss-soc-206', q: 'The Māori concept of "tino rangatiratanga" most closely refers to:', choices: ['A type of haka', 'Self-determination / absolute sovereignty', 'A traditional food', 'A Treaty signatory'], answer: 1, explanation: 'Tino rangatiratanga is guaranteed under Te Tiriti o Waitangi and refers to Māori self-determination over their lands, people and taonga.', unit: 3 },
  { id: 'ss-soc-207', q: 'The Waitangi Tribunal, established 1975, primarily exists to:', choices: ['Run NZ elections', 'Hear claims of Crown breaches of Te Tiriti o Waitangi', 'Set tax policy', 'Manage fisheries quotas alone'], answer: 1, explanation: 'The Tribunal investigates historical and contemporary Crown breaches of the Treaty and makes recommendations — a state mechanism that recognises ongoing Māori claims.', unit: 3 },
  { id: 'ss-soc-208', q: 'A sociologist who argues "all cultures must be understood within their own context, not judged by another culture\'s standards" is applying:', choices: ['Ethnocentrism', 'Cultural relativism', 'Assimilationism', 'Social Darwinism'], answer: 1, explanation: 'Cultural relativism is the principle of understanding a culture on its own terms — the opposite of ethnocentrism.', unit: 3 },
  { id: 'ss-soc-209', q: 'The 2008 National Apology to the Stolen Generations was delivered by:', choices: ['John Howard', 'Kevin Rudd', 'Julia Gillard', 'Malcolm Turnbull'], answer: 1, explanation: 'PM Kevin Rudd delivered the formal Apology in Parliament on 13 February 2008 — a symbolic act of recognition of past harms.', unit: 3 },
  { id: 'ss-soc-210', q: 'In sociological terms, the Bringing Them Home report (1997) functions as an example of:', choices: ['A continuance practice', 'A truth-telling / acknowledgement of past harm against Indigenous peoples', 'A revolutionary movement', 'A reformative movement'], answer: 1, explanation: 'The HREOC report documented the policies and impacts of forcible child removal — central to Australia\'s truth-telling process.', unit: 3 },
  { id: 'ss-soc-211', q: 'Welcome to Country and Acknowledgement of Country differ primarily in that:', choices: ['They mean exactly the same thing', 'Welcome to Country is delivered by a Traditional Owner; an Acknowledgement can be given by anyone', 'Welcome to Country is only for tourists', 'Acknowledgement is older'], answer: 1, explanation: 'Welcome must be given by a Traditional Owner of the specific Country; an Acknowledgement can be offered by anyone to recognise that Country.', unit: 3 },
  { id: 'ss-soc-212', q: 'The Uluru Statement from the Heart (2017) called for THREE things, often summarised as:', choices: ['Land, sea, sky', 'Voice, Treaty, Truth', 'Past, present, future', 'Health, education, housing'], answer: 1, explanation: 'Voice (to Parliament), Treaty (Makarrata), and Truth-telling are the three pillars of the Uluru Statement.', unit: 3 },
  { id: 'ss-soc-213', q: 'The 2023 Voice referendum result demonstrated that constitutional recognition of an Indigenous advisory body was:', choices: ['Approved', 'Not approved by Australian voters', 'Postponed', 'Cancelled before voting'], answer: 1, explanation: 'The October 2023 referendum was not carried — neither a national majority nor a majority of states voted Yes.', unit: 3 },
  { id: 'ss-soc-214', q: 'NAIDOC Week is best understood sociologically as an example of:', choices: ['Cultural appropriation', 'Cultural continuance and public recognition', 'Assimilation policy', 'Coercive power'], answer: 1, explanation: 'NAIDOC celebrates and continues Indigenous histories, cultures and achievements — a public continuance practice.', unit: 3 },
  { id: 'ss-soc-215', q: 'The "Closing the Gap" framework is a state response that primarily addresses:', choices: ['Native title alone', 'Statistical disparities between Indigenous and non-Indigenous Australians (e.g. life expectancy, education, incarceration)', 'Cultural appropriation', 'Constitutional reform alone'], answer: 1, explanation: 'Closing the Gap targets measurable health, education, employment and justice disparities — a structural response framework.', unit: 3 },
  { id: 'ss-soc-216', q: 'Native title in Australia was first legally recognised by the High Court in:', choices: ['Wik (1996)', 'Mabo v Queensland (No 2), 1992', 'Yorta Yorta (2002)', 'Love v Commonwealth (2020)'], answer: 1, explanation: 'Mabo (No 2) rejected the doctrine of terra nullius and recognised native title — landmark recognition of continuous Indigenous connection to land.', unit: 3 },
  { id: 'ss-soc-217', q: 'The doctrine of "terra nullius" was the legal fiction that:', choices: ['Australia was discovered by Indigenous peoples', 'Australia was "land belonging to no-one" before British settlement', 'Indigenous peoples owned all of Australia', 'Australia was a Crown protectorate from 1788'], answer: 1, explanation: 'Terra nullius justified British dispossession by denying prior Indigenous sovereignty — overturned by Mabo in 1992.', unit: 3 },
  { id: 'ss-soc-218', q: 'When an Indigenous community runs its own ranger program managing fire, sea Country and species, this is BEST classified as:', choices: ['Assimilation', 'Self-determination AND continuance — Indigenous knowledge applied to caring for Country', 'Tokenism', 'Cultural appropriation'], answer: 1, explanation: 'Indigenous ranger programs combine self-determination with the continuance of land-management knowledge such as cultural burning.', unit: 3 },
  { id: 'ss-soc-219', q: 'A key challenge to Indigenous cultural continuance identified in sociological research is:', choices: ['Population growth', 'Loss of language speakers and intergenerational transmission', 'Excess government funding', 'Too many treaties'], answer: 1, explanation: 'Language loss — particularly the death of fluent first-language speakers — is widely identified as a critical threat to continuance.', unit: 3 },
  { id: 'ss-soc-220', q: 'The Australian Government\'s First Languages funding programs are an example of:', choices: ['A continuance practice supported by the state', 'A revolutionary movement', 'Cultural appropriation by the state', 'A reformative movement against the state'], answer: 0, explanation: 'State funding for First Languages programs is a continuance practice, even when delivered through state institutions.', unit: 3 },
  { id: 'ss-soc-221', q: 'Comparing Australian Indigenous and Māori experiences, ONE key structural difference is that:', choices: ['Both have a founding treaty with the Crown', 'Aotearoa NZ has a founding treaty (Te Tiriti, 1840) while Australia does not have a national treaty', 'Both lack any treaty', 'Australia has multiple treaties; NZ has none'], answer: 1, explanation: 'Te Tiriti o Waitangi gives Aotearoa NZ a founding bicultural framework; Australia has no equivalent national treaty.', unit: 3 },
  { id: 'ss-soc-222', q: 'Two Indigenous cultures may share which of the following experiences, despite being on different continents?', choices: ['Identical languages', 'Common responses to colonisation including dispossession, child removal, and movements for self-determination', 'The same religion', 'Identical political structures'], answer: 1, explanation: 'Comparative study reveals shared patterns of colonial impact AND shared strategies of resistance and continuance.', unit: 3 },
  { id: 'ss-soc-223', q: 'A misconception students should avoid in AOS 1 is:', choices: ['Treating "Indigenous" as one homogeneous culture', 'Recognising diversity within and across Indigenous nations', 'Acknowledging continuance', 'Comparing two cultures'], answer: 0, explanation: 'Treating Indigenous peoples as a single homogeneous group erases internal diversity — a common but critical error.', unit: 3 },
  { id: 'ss-soc-224', q: 'A "Songline" in Aboriginal Australian cultures functions primarily as:', choices: ['A tourist attraction', 'A way of encoding navigation, law, history and Country across generations', 'A government policy', 'A modern song genre'], answer: 1, explanation: 'Songlines transmit knowledge of Country, law and history through performance — a sophisticated continuance technology.', unit: 3 },
  { id: 'ss-soc-225', q: 'A high-quality VCAA evaluation of a continuance practice (e.g. an Indigenous ranger program) examines:', choices: ['Annual economic return and number of participants', 'Leadership, benefit distribution, AND the practice\'s relationship to state structures and ongoing colonisation', 'The founder\'s biography and public popularity ratings', 'Government funding amount and media coverage volume'], answer: 1, explanation: 'Rigorous evaluation foregrounds who leads, who benefits, and the practice\'s structural position — economic and popularity metrics alone are sociologically thin.', unit: 3 },

  // AOS 2 — Ethnicity (study-design depth + theorists)
  { id: 'ss-soc-226', q: 'The textbook frames ethnicity as primarily:', choices: ['A fixed biological trait', 'A socially constructed sense of shared identity (ancestry, language, religion, history)', 'A government category only', 'Identical to race'], answer: 1, explanation: 'Ethnicity is socially constructed — built on shared identity markers rather than biology.', unit: 3 },
  { id: 'ss-soc-227', q: 'The 2021 Australian Census recorded that what proportion of Australians were born overseas?', choices: ['Around 5%', 'Around 28%', 'Around 50%', 'Around 75%'], answer: 1, explanation: 'Roughly 28% of Australians were born overseas — among the highest proportions in the OECD.', unit: 3 },
  { id: 'ss-soc-228', q: 'The White Australia Policy is most associated with:', choices: ['The Immigration Restriction Act 1901', 'The Native Title Act 1993', 'The Racial Discrimination Act 1975', 'The Multicultural Affairs Act'], answer: 0, explanation: 'The Immigration Restriction Act 1901 codified the dictation test and excluded non-European migration for decades.', unit: 3 },
  { id: 'ss-soc-229', q: 'The Racial Discrimination Act was passed in:', choices: ['1901', '1975', '1992', '2008'], answer: 1, explanation: 'The Racial Discrimination Act 1975 (Whitlam government) made discrimination on the basis of race, ethnicity or national origin unlawful.', unit: 3 },
  { id: 'ss-soc-230', q: 'The shift from "assimilation" to "multiculturalism" in Australian policy is most associated with the era of:', choices: ['Federation (1901)', 'The 1970s (Whitlam–Fraser period)', 'The 2000s', 'The 1950s'], answer: 1, explanation: 'Multiculturalism emerged as official policy in the 1970s — a structural break from assimilation.', unit: 3 },
  { id: 'ss-soc-231', q: 'When a person navigates fluently between two cultural worlds (e.g. speaking one language at home and another at work), this is best described as:', choices: ['Assimilation', 'Bicultural identity / code-switching', 'Marginalisation', 'Cultural appropriation'], answer: 1, explanation: 'Holding and moving between two cultural frames is bicultural identity — often expressed through code-switching.', unit: 3 },
  { id: 'ss-soc-232', q: 'Stuart Hall\'s concept of "cultural identity" emphasises that identity is:', choices: ['Fixed at birth', 'A process of "becoming" — constructed, contested and shifting', 'Determined entirely by the state', 'Genetic'], answer: 1, explanation: 'Hall argued cultural identity is always in process — never finished, always positioned.', unit: 3 },
  { id: 'ss-soc-233', q: 'Benedict Anderson\'s concept of the "imagined community" argues that nations are:', choices: ['Naturally occurring', 'Socially imagined — members will never meet most fellow nationals but feel a shared identity', 'Defined only by borders', 'Defined only by language'], answer: 1, explanation: 'Anderson: a nation is "imagined" because members hold a shared identity with strangers they will never meet.', unit: 3 },
  { id: 'ss-soc-234', q: 'A first-generation migrant from Vietnam to Australia who maintains Vietnamese language at home AND adopts Australian civic practices is exhibiting:', choices: ['Pure assimilation', 'Integration / multiculturalism — maintaining heritage while participating in the host society', 'Separation', 'Marginalisation'], answer: 1, explanation: 'Berry\'s acculturation model: maintaining heritage AND engaging with the host culture = integration.', unit: 3 },
  { id: 'ss-soc-235', q: 'John Berry\'s acculturation framework identifies four strategies. A person who rejects BOTH their heritage culture AND the host culture is in a state of:', choices: ['Integration', 'Assimilation', 'Separation', 'Marginalisation'], answer: 3, explanation: 'Berry: marginalisation = low engagement with both heritage and host culture — a high-risk position.', unit: 3 },
  { id: 'ss-soc-236', q: 'A SNS (social networking site) feed full of memes about one\'s heritage culture, viewed in Australia, is BEST understood as:', choices: ['A meaningless distraction', 'A digitally-mediated continuance practice — maintaining diaspora identity online', 'Cultural appropriation', 'A revolutionary movement'], answer: 1, explanation: 'Diaspora SNS use sustains cultural identity across distance — a contemporary continuance practice.', unit: 3 },
  { id: 'ss-soc-237', q: 'A hospital with no overtly racist staff still records significantly worse health outcomes for one ethnic group because of how its triage policy interacts with English-language proficiency. This is BEST described as:', choices: ['Individual prejudice on the part of triage nurses', 'Institutional racism operating through policy and structure regardless of staff intent', 'Reverse discrimination against staff', 'Multiculturalism in action'], answer: 1, explanation: 'Institutional racism produces unequal outcomes through structures and policies — it can persist even when individual actors hold no prejudice.', unit: 3 },
  { id: 'ss-soc-238', q: 'A government decision to require interpreters in hospitals is a structural response that primarily aims to:', choices: ['Reduce ethnic diversity', 'Reduce structural barriers to equal access for diverse ethnic communities', 'Promote assimilation', 'Eliminate multiculturalism'], answer: 1, explanation: 'Language access reduces structural barriers — a multicultural policy response to ethnic diversity.', unit: 3 },
  { id: 'ss-soc-239', q: 'The textbook concept of "diaspora" refers to:', choices: ['A type of dance', 'A dispersed population maintaining identity ties to a homeland', 'A government department', 'A type of music genre'], answer: 1, explanation: 'Diaspora = population dispersed from a homeland but maintaining identity, networks and connections to it.', unit: 3 },
  { id: 'ss-soc-240', q: 'When a young person in Australia identifies as both "Australian" AND "Greek-Australian", this is sociologically described as:', choices: ['Confused identity', 'Hyphenated / hybrid identity — coexisting belongings', 'Failed assimilation', 'Pure separation'], answer: 1, explanation: 'Hybrid or hyphenated identity is a normal feature of multicultural societies — not a deficit.', unit: 3 },
  { id: 'ss-soc-241', q: 'Cosmopolitanism, in sociology, refers to:', choices: ['Living in a major city', 'An orientation of openness toward, and identification with, diverse cultures and global belonging', 'A type of cocktail', 'Rejecting all cultures'], answer: 1, explanation: 'Cosmopolitanism is an identity orientation — openness to diversity and global belonging.', unit: 3 },
  { id: 'ss-soc-242', q: 'The fact that Australian "cultural" exports such as flat whites and avocado toast now appear in cafés worldwide best illustrates:', choices: ['Cultural appropriation', 'Cultural globalisation / outflow of cultural practices through diaspora and trade', 'Assimilation', 'Cultural decline'], answer: 1, explanation: 'Cultural globalisation involves the international circulation of practices — not just inflow but outflow.', unit: 3 },
  { id: 'ss-soc-243', q: 'When a media outlet repeatedly only shows a particular ethnic group in crime stories, this is a form of:', choices: ['Balanced reporting', 'Stereotyping / symbolic violence through framing', 'Continuance', 'Multiculturalism'], answer: 1, explanation: 'Selective framing reinforces stereotypes — a form of symbolic violence (Bourdieu) embedded in everyday media practice.', unit: 3 },
  { id: 'ss-soc-244', q: 'Bourdieu\'s concept of "habitus" helps explain how:', choices: ['Genes determine ethnicity', 'Internalised dispositions shaped by upbringing produce "natural" cultural behaviour', 'Governments set ethnic policy', 'Migration occurs'], answer: 1, explanation: 'Habitus = internalised, taken-for-granted dispositions that make culturally specific behaviour feel "natural".', unit: 3 },
  { id: 'ss-soc-245', q: 'A common misconception in AOS 2 is to:', choices: ['Treat ethnicity as fluid and constructed', 'Treat ethnicity as biologically fixed and equivalent to "race"', 'Recognise hybrid identities', 'Discuss diaspora'], answer: 1, explanation: 'Treating ethnicity as biology — and conflating it with discredited concepts of race — is a key error.', unit: 3 },

  // AOS 3 — Community (Australian Men's Shed + Keysborough CFA textbook case studies)
  { id: 'ss-soc-246', q: 'The textbook reports the Australian Men\'s Shed Movement was established in:', choices: ['1976', '1986', '1996', '2006'], answer: 2, explanation: 'The Australian Men\'s Shed Movement was established in 1996 — the textbook details this as the formation date.', unit: 4 },
  { id: 'ss-soc-247', q: 'According to the textbook, approximately how many Men\'s Sheds operate across Australia?', choices: ['About 100', 'About 500', 'Over 1000', 'Over 10,000'], answer: 2, explanation: 'The textbook reports more than 1,000 Men\'s Sheds across Australia, with around 200,000 members.', unit: 4 },
  { id: 'ss-soc-248', q: 'The Australian Men\'s Shed Association (AMSA) functions as the:', choices: ['Owner of all sheds', 'National governing/peak body for the Men\'s Shed Movement', 'A government department', 'A private corporation'], answer: 1, explanation: 'AMSA is the national peak body — providing governance, advocacy and support across local sheds.', unit: 4 },
  { id: 'ss-soc-249', q: 'A primary stated purpose of the Australian Men\'s Shed Movement is to:', choices: ['Compete with sports clubs', 'Improve men\'s health, particularly mental health and social connection', 'Sell handmade products', 'Replace government services'], answer: 1, explanation: 'Men\'s Sheds are framed as a health response — combating isolation, supporting mental health, and building community.', unit: 4 },
  { id: 'ss-soc-250', q: 'In Tönnies\' typology, a Men\'s Shed most closely resembles:', choices: ['Gesellschaft (impersonal, contractual society)', 'Gemeinschaft (warm, face-to-face community)', 'A bureaucracy', 'A revolutionary movement'], answer: 1, explanation: 'Men\'s Sheds embody Gemeinschaft — small-scale, face-to-face, relational community.', unit: 4 },
  { id: 'ss-soc-251', q: 'The textbook\'s Keysborough CFA case study is located in:', choices: ['Northern NSW', 'South-eastern Melbourne, Victoria', 'Far north Queensland', 'Western Sydney'], answer: 1, explanation: 'Keysborough is a south-eastern Melbourne suburb — the textbook anchors its community-of-interest case study there.', unit: 4 },
  { id: 'ss-soc-252', q: 'The Keysborough CFA brigade has been operating for approximately:', choices: ['10 years', '20 years', '40 years', '80 years'], answer: 3, explanation: 'The textbook reports the brigade has been serving Keysborough for around 80 years.', unit: 4 },
  { id: 'ss-soc-253', q: 'According to the textbook, membership at Keysborough CFA grew over five years from:', choices: ['1 to 5 members', '9 to 50 members', '100 to 500 members', '50 to 9 members (decline)'], answer: 1, explanation: 'The brigade grew from 9 active volunteers to around 50 over five years — illustrating deliberate community-building.', unit: 4 },
  { id: 'ss-soc-254', q: 'The Keysborough CFA brigade refers to itself colloquially as the:', choices: ['"Fire crew"', '"Fire fam"', '"Burn squad"', '"Hot team"'], answer: 1, explanation: 'The textbook quotes brigade members calling themselves the "fire fam" — language that reflects strong relational bonds.', unit: 4 },
  { id: 'ss-soc-255', q: 'A specific norm at the Keysborough CFA limiting WhatsApp messaging between 10pm and 6am is BEST classified sociologically as:', choices: ['A formal law', 'An internal community norm protecting wellbeing', 'A piece of state regulation', 'A revolutionary act'], answer: 1, explanation: 'The 10pm–6am limit is an internal norm — a deliberate community-level rule about belonging and welfare.', unit: 4 },
  { id: 'ss-soc-256', q: 'The Keysborough brigade\'s use of Bunnings BBQ fundraisers exemplifies:', choices: ['Coercive power', 'A community of interest engaging in fundraising and visibility within a broader community', 'A revolutionary movement', 'Institutional racism'], answer: 1, explanation: 'Bunnings sausage sizzles are a quintessentially Australian fundraising practice — building visibility and resources for a community of interest.', unit: 4 },
  { id: 'ss-soc-257', q: 'Peer-support practices at Keysborough CFA, following traumatic incidents, illustrate the role of communities in:', choices: ['Causing trauma', 'Buffering members against trauma through social connection', 'Avoiding all difficult topics', 'Reporting members to police'], answer: 1, explanation: 'Communities of interest like emergency services are key sites of post-trauma peer support — a measurable benefit of belonging.', unit: 4 },
  { id: 'ss-soc-258', q: 'The textbook reports the 2021 ABS population of Keysborough as approximately:', choices: ['3,000', '30,000+', '300,000', '3,000,000'], answer: 1, explanation: 'The 2021 ABS Census recorded Keysborough\'s population at more than 30,000 — the context within which the brigade operates.', unit: 4 },
  { id: 'ss-soc-259', q: 'According to the textbook, the Australian Men\'s Shed Movement is sustained by a hybrid funding model combining:', choices: ['Federal Community Service Fund support, AMSA grants AND local fundraising', 'Member subscriptions and corporate sponsorship from major retailers', 'State health-department contracts and private philanthropy', 'Local council operating grants and Bunnings sponsorship'], answer: 0, explanation: 'The textbook details a three-stream hybrid: federal CSF support, AMSA-distributed grants, AND local fundraising by individual sheds.', unit: 4 },
  { id: 'ss-soc-260', q: 'A "community of interest" differs from a "community of place" primarily in that:', choices: ['Communities of interest are bigger', 'Communities of interest are bound by shared interest or identity; communities of place by shared geography', 'They are identical', 'Communities of place use no technology'], answer: 1, explanation: 'Place vs interest is the core textbook distinction — geographic vs identity/activity-based.', unit: 4 },
  { id: 'ss-soc-261', q: 'A Men\'s Shed is sociologically BEST classified as a community of:', choices: ['Place only', 'Interest (and also of place at the local level) — gender + craft + wellbeing focus', 'Resistance only', 'Online only'], answer: 1, explanation: 'Each Men\'s Shed has a local geography (place) but is defined by shared interest in craft, mateship and wellbeing.', unit: 4 },
  { id: 'ss-soc-262', q: 'Putnam\'s concept of "bonding social capital" refers to:', choices: ['Banking', 'Strong within-group ties (e.g. between close shed members)', 'Cross-group ties to outsiders', 'Government-issued capital'], answer: 1, explanation: 'Bonding social capital = strong, within-group ties; bridging social capital = ties across groups.', unit: 4 },
  { id: 'ss-soc-263', q: 'When a Men\'s Shed partners with a local school or aged-care home, it is building:', choices: ['Bonding social capital only', 'Bridging social capital — ties across different community groups', 'Coercive power', 'Cultural appropriation'], answer: 1, explanation: 'Cross-group partnerships build bridging social capital — a Putnam concept directly applicable to AOS 3.', unit: 4 },
  { id: 'ss-soc-264', q: 'The textbook\'s evaluation of communities of interest argues their main benefit is:', choices: ['Economic profit', 'Belonging, identity, social support and improved wellbeing for members', 'Power over outsiders', 'Replacing the state'], answer: 1, explanation: 'Belonging, identity and wellbeing are the dominant evaluative themes for communities of interest.', unit: 4 },
  { id: 'ss-soc-265', q: 'A risk identified for tight communities of interest is:', choices: ['Too much diversity', 'Becoming insular or excluding outsiders ("us vs them")', 'Excessive bridging capital', 'Government overreach'], answer: 1, explanation: 'High bonding capital can come at the cost of bridging — leading to insularity or exclusion.', unit: 4 },
  { id: 'ss-soc-266', q: 'A challenge in evaluating community success is that benefits are often:', choices: ['Easily quantifiable in dollars', 'Intangible (belonging, identity, wellbeing) and hard to measure quantitatively', 'Identical across all members', 'Determined by government alone'], answer: 1, explanation: 'Community outcomes are largely intangible — methodologically harder to capture than financial measures.', unit: 4 },
  { id: 'ss-soc-267', q: 'The Keysborough CFA brigade is composed primarily of:', choices: ['Paid career firefighters', 'Volunteers', 'Defence force personnel', 'Police officers'], answer: 1, explanation: 'CFA brigades like Keysborough rely on volunteer firefighters — central to their identity as a community of interest.', unit: 4 },
  { id: 'ss-soc-268', q: 'A Men\'s Shed expanding to host women\'s sessions or family open days illustrates:', choices: ['Loss of identity', 'Adaptive bridging — extending community beyond original boundaries', 'Coercion', 'Bureaucratisation'], answer: 1, explanation: 'Adapting to include broader participation builds bridging capital while testing the community\'s identity boundaries.', unit: 4 },
  { id: 'ss-soc-269', q: 'A common student misconception in AOS 3 is to:', choices: ['Distinguish place from interest communities', 'Confuse a "community" with a "social movement"', 'Recognise diverse community forms', 'Discuss social capital'], answer: 1, explanation: 'Communities seek belonging and identity; social movements seek social change — confusing them is a key error.', unit: 4 },
  { id: 'ss-soc-270', q: 'A Men\'s Shed and a Keysborough CFA brigade share which sociological feature?', choices: ['Both are revolutionary movements', 'Both are communities of interest delivering social, health and belonging outcomes', 'Both are state bureaucracies', 'Both are private companies'], answer: 1, explanation: 'Both are communities of interest — distinct vehicles, similar wellbeing/belonging outcomes.', unit: 4 },

  // AOS 4 — Social movements (Sunrise Movement deep dive + Chenoweth)
  { id: 'ss-soc-271', q: 'According to the textbook, the Sunrise Movement was first devised in:', choices: ['2010', '2016', '2018', '2020'], answer: 1, explanation: 'The textbook reports the Sunrise Movement was first devised in 2016 by a group of six young climate activists.', unit: 4 },
  { id: 'ss-soc-272', q: 'The Sunrise Movement officially launched in:', choices: ['January 2016', 'April 2017', 'November 2018', 'January 2020'], answer: 1, explanation: 'The textbook records the official launch as April 2017, supported by seed funding from Sierra Club and 350.org.', unit: 4 },
  { id: 'ss-soc-273', q: 'The Sunrise Movement\'s central policy demand, as set out in the textbook, calls for the United States to transition to 100% clean and renewable energy within how many years?', choices: ['5 years', '10 years', '20 years', '30 years'], answer: 1, explanation: 'The Green New Deal advocated by Sunrise calls for a 10-year transition off fossil fuels plus a parallel jobs and economic-justice agenda.', unit: 4 },
  { id: 'ss-soc-274', q: 'Using Aberle\'s typology, the textbook classifies the Sunrise Movement as:', choices: ['Alternative', 'Redemptive', 'Reformative', 'Revolutionary'], answer: 2, explanation: 'Sunrise seeks limited change (policy) from a group (government) — fitting the reformative classification.', unit: 4 },
  { id: 'ss-soc-275', q: 'In November 2018, roughly 200 Sunrise activists occupied House Speaker Nancy Pelosi\'s office wearing shirts reading "we have a right to a liveable future". The SIT-IN ITSELF (separate from Ocasio-Cortez\'s attendance) is best classified as which form of power?', choices: ['Legitimate power', 'Coercive power', 'Reward power', 'Referent power'], answer: 1, explanation: 'The sit-in disrupted Pelosi\'s office routine and imposed political cost — coercive power through non-violent disruption.', unit: 4 },
  { id: 'ss-soc-276', q: 'When freshly-elected Representative Alexandria Ocasio-Cortez attended the Sunrise sit-in at Pelosi\'s office, the textbook argues she brought which form of power that the activists alone could not?', choices: ['Coercive power', 'Reward power', 'Legitimate power', 'Expert power'], answer: 2, explanation: 'As an elected member of Congress, AOC carried legitimate power — the formal right to make demands of House leadership.', unit: 4 },
  { id: 'ss-soc-277', q: 'When prominent activist Naomi Klein speaks at a Sunrise rally, the textbook classifies this as adding which form of power?', choices: ['Coercive power', 'Expert power', 'Reward power', 'Legitimate power'], answer: 1, explanation: 'Experts like Klein, McKibben and NoiseCat bring expert power — credibility from specialist knowledge.', unit: 4 },
  { id: 'ss-soc-278', q: 'When actor Joaquin Phoenix speaks at a Sunrise rally, the textbook distinguishes his contribution from that of climate scientist Bill McKibben. Phoenix primarily contributes which form of power?', choices: ['Expert power', 'Referent power', 'Legitimate power', 'Informational power'], answer: 1, explanation: 'Phoenix lacks specific climate expertise, so his power is referent — drawn from his celebrity following and audience identification.', unit: 4 },
  { id: 'ss-soc-279', q: 'When Sunrise publicly endorses a Green-New-Deal-aligned candidate, channelling votes, small-dollar donations and volunteer doorknockers toward them, the textbook classifies this as which form of power?', choices: ['Coercive power', 'Reward power', 'Legitimate power', 'Expert power'], answer: 1, explanation: 'Endorsement provides positive incentives (votes, money, ground game) to aligned politicians — the defining feature of reward power.', unit: 4 },
  { id: 'ss-soc-280', q: 'Sunrise withholding endorsement from candidates is described in the textbook as a form of:', choices: ['Reward power', 'Coercive power', 'Expert power', 'Referent power'], answer: 1, explanation: 'Denying endorsement imposes a consequence for non-compliance — coercive power.', unit: 4 },
  { id: 'ss-soc-281', q: 'By 2023 Sunrise had more than 100 staff members, 500 active local hubs and tens of thousands of volunteers across North America, with strategy carried out through formal structures. Per Blumer\'s stage model, this places the movement in:', choices: ['Emergence', 'Coalescence', 'Bureaucratisation', 'Decline'], answer: 2, explanation: 'Formal structure, large paid staff, organised strategy = bureaucratisation. The textbook explicitly locates Sunrise here from 2017 onwards.', unit: 4 },
  { id: 'ss-soc-282', q: 'The textbook documents Sunrise\'s "three Ps" framework as three core strategies, all starting with the letter P. They are:', choices: ['Protest power, party power, petition power', 'People power, political power, people\'s alignment', 'Public power, press power, persuasion power', 'Participation, policy, persistence'], answer: 1, explanation: 'The three Ps in Sunrise\'s strategy: people power (active base), political power (electoral organising), and people\'s alignment (coalition-building across movements).', unit: 4 },
  { id: 'ss-soc-283', q: 'The textbook identifies the Sunrise Movement\'s two principal sources of organised opposition as:', choices: ['Local councils and university administrations', 'Trump-era Republicans and the fossil fuel lobby', 'The Democratic Party leadership and the Sierra Club', 'Mainstream media outlets and Wall Street banks'], answer: 1, explanation: 'The textbook focuses on Trump-era Republicans (using legitimate, reward, coercive and informational power) and the fossil fuel industry (using reward and coercive power) as primary opposition.', unit: 4 },
  { id: 'ss-soc-284', q: 'The fossil fuel industry funds the political campaigns of climate-sceptic candidates. When deployed by Sunrise\'s opposition, this strategy is best classified as which form of power?', choices: ['Coercive power', 'Reward power', 'Expert power', 'Referent power'], answer: 1, explanation: 'Providing campaign funding is a positive incentive for compliance — the textbook definition of reward power, regardless of whether deployed by movements or opposition.', unit: 4 },
  { id: 'ss-soc-285', q: 'According to the textbook, Sunrise\'s 2020 voter-contact effort reached approximately how many voters across postcards, texts and phone calls combined?', choices: ['Around 65,000', 'Around 650,000', 'Around 6.5 million', 'Around 65 million'], answer: 2, explanation: 'The textbook breakdown: 777,570 postcards + 2.6 million text messages + 5.8 million phone calls + 23,518 pledge confirmations — totalling well over 6.5 million voter contacts.', unit: 4 },
  { id: 'ss-soc-286', q: 'The textbook records that "Sunrise 2.0", ratified in mid-2022, was a strategic restructure primarily responding to which set of internal pressures?', choices: ['A government takeover attempt and a hostile media campaign', 'Internal tensions around race, members feeling "tokenised", and decision-making structures outgrown by rapid expansion', 'Insolvency following loss of seed funding from Sierra Club', 'A merger with the global 350.org organisation'], answer: 1, explanation: 'The textbook documents Sunrise 2.0 as a response to four shifts including a multiracial/cross-class focus and new internal democracy — addressing real tensions raised by Sunrise members of colour.', unit: 4 },
  { id: 'ss-soc-287', q: 'Erica Chenoweth\'s "3.5% rule" identifies which empirical threshold for movement success?', choices: ['Movements succeed when they secure 3.5% of national GDP in funding', 'Non-violent movements that sustain active participation of around 3.5% of the population have historically always succeeded', 'Movements succeed when they last at least 3.5 years', 'Around 3.5% of all civil resistance campaigns succeed overall'], answer: 1, explanation: 'The 3.5% threshold (active participation, sustained, non-violent) is associated with historical success. For the US, ~3.5% = ~11.5 million people — Sunrise has not yet reached this.', unit: 4 },
  { id: 'ss-soc-288', q: 'The textbook offers a Chenoweth-informed explanation for why Sunrise has not yet achieved its full goal of ending US fossil fuel reliance. Which figure is central to this analysis?', choices: ['~1.5 million Americans (1% threshold)', '~11.5 million Americans (3.5% threshold)', '~25 million Americans (~7.5% threshold)', '~50 million Americans (~15% threshold)'], answer: 1, explanation: 'Chenoweth\'s 3.5% threshold, applied to the US population, equals approximately 11.5 million active participants — a level Sunrise has not yet reached.', unit: 4 },
  { id: 'ss-soc-289', q: 'Despite not yet achieving its ultimate goal, the textbook credits the Sunrise Movement with which combination of measurable social changes?', choices: ['Eliminating US fossil fuel use and passing a federal Green New Deal', 'Increasing public awareness, mainstreaming the Green New Deal in Democratic politics, AND electing climate-champion candidates', 'Securing constitutional amendment recognising climate as a human right', 'Disbanding the major fossil fuel industry trade associations'], answer: 1, explanation: 'These three are the textbook\'s evaluated achievements: awareness, discourse mainstreaming, and concrete electoral wins (e.g. AOC 2018).', unit: 4 },
  { id: 'ss-soc-290', q: 'Sunrise\'s public principles include an explicit commitment to non-violent action. According to the textbook, the movement justifies this primarily on:', choices: ['Cost grounds — non-violent action is cheaper', 'Strategic grounds — non-violent action is more likely to win public sympathy and align with Chenoweth\'s findings', 'Legal grounds — violent protest is illegal in the US', 'Religious grounds — the founders held pacifist beliefs'], answer: 1, explanation: 'Sunrise frames non-violence as strategically superior — winning hearts and minds, building broad coalitions, and aligning with Chenoweth\'s empirical finding that non-violent movements succeed roughly twice as often.', unit: 4 },
  { id: 'ss-soc-291', q: 'According to the textbook, Sunrise\'s 2017 launch was supported by seed funding from two established US climate-organising organisations. They were:', choices: ['Greenpeace USA and the Natural Resources Defense Council', 'Sierra Club and 350.org', 'The Audubon Society and Earthjustice', 'The Climate Reality Project and the Environmental Defense Fund'], answer: 1, explanation: 'The textbook specifically names Sierra Club and 350.org as seed-funders. All other options name real, prominent US environmental organisations that were NOT the seed funders.', unit: 4 },
  { id: 'ss-soc-292', q: 'Sunrise School, launched in March 2020, is best described as:', choices: ['A residential climate-science academy for high school students', 'An online program teaching grassroots organising and Green-New-Deal advocacy', 'A renewable-energy trade-skills certification scheme', 'A youth political-campaign donor network'], answer: 1, explanation: 'Sunrise School is an online training program for movement organising and Green New Deal advocacy — part of the bureaucratisation-stage build-out.', unit: 4 },
  { id: 'ss-soc-293', q: 'The textbook notes that mainstream coverage of Sunrise actions by outlets like The New York Times, Vogue, Vice and Vox gives the movement leverage over the public information environment. This represents which form of movement power?', choices: ['Coercive power', 'Reward power', 'Informational power', 'Legitimate power'], answer: 2, explanation: 'Influence over the information environment — what is reported, framed and amplified — is informational power. Mainstream media coverage extends this power to a wider audience.', unit: 4 },
  { id: 'ss-soc-294', q: 'A Year 12 comparison response would most usefully pair Sunrise with which other contemporary climate movement?', choices: ['The Green Belt Movement (1977, Kenya, Wangari Maathai)', 'Extinction Rebellion / School Strike 4 Climate', '350.org (Sunrise\'s own seed funder)', 'The Sierra Club (Sunrise\'s own seed funder)'], answer: 1, explanation: 'XR and School Strike 4 Climate are contemporary, peer-aged comparators using overlapping but distinct tactics — productive for comparative analysis. The other options are either historical, or organisations Sunrise itself is funded by.', unit: 4 },
  { id: 'ss-soc-295', q: 'Sunrise organises politically with the principle "no permanent friends, no permanent enemies". In practice this means:', choices: ['Refusing to endorse any candidate to remain ideologically pure', 'Endorsing only registered Democrats regardless of policy positions', 'Backing or opposing candidates of any party based on their Green-New-Deal position, not party loyalty', 'Building permanent coalitions only with established climate NGOs'], answer: 2, explanation: 'The slogan captures Sunrise\'s issue-based strategy: judge each politician on climate position, not party affiliation. This explains the Biden "F-" rating during the 2020 primary.', unit: 4 },
  { id: 'ss-soc-296', q: 'Hahrie Han\'s "three Ps" framework, which the textbook applies to explain Sunrise\'s organising effectiveness, names which three Ps?', choices: ['Possible, probable, powerful', 'Participation, policy, persistence', 'People, politics, power', 'Protest, persuasion, persistence'], answer: 0, explanation: 'Han: movements grow when they make action possible (enabling), probable (personal connection) and powerful (leveraging influence). All four options are plausible-sounding alliterations — Han\'s specific frame is the first.', unit: 4 },
  { id: 'ss-soc-297', q: 'The Sunrise Movement at emergence (2016) had almost no power; by bureaucratisation (post-2017) it could mount 6.5-million-voter contact campaigns. This pattern illustrates that movement and opposition power:', choices: ['Are fixed throughout the movement\'s lifespan', 'Shift dynamically across stages, requiring stage-specific strategy', 'Are equal and unchanging across the movement\'s history', 'Become relevant only once a movement reaches decline'], answer: 1, explanation: 'Power balances are dynamic — the textbook stresses that movements typically begin weak and must build power, while opposition power may shift in response.', unit: 4 },
  { id: 'ss-soc-298', q: 'The textbook argues that former President Trump used social media to shape narratives around climate policy. As deployed against Sunrise, this is best classified as which form of opposition power?', choices: ['Legitimate power', 'Reward power', 'Informational power', 'Expert power'], answer: 2, explanation: 'Control of public messaging through social media is informational power — a key Trump-era opposition lever against Sunrise.', unit: 4 },
  { id: 'ss-soc-299', q: 'Marking an extended response on the Sunrise Movement, a VCAA assessor will reward a response that integrates which five components?', choices: ['Founding date, policy goal, founder biography, funding, media coverage', 'Type, current stage, power used by movement, opposition\'s power, and Chenoweth-informed evaluation of social change', 'Founder biography, policy goal, opposition list, media coverage, public approval', 'Funding sources, social media reach, election results, founder biography, policy detail'], answer: 1, explanation: 'These five components map directly to the AOS 4 study-design lens. Responses that skip the dual power analysis OR the Chenoweth evaluation drop marks.', unit: 4 },
  { id: 'ss-soc-300', q: 'Which is the most defensible VCAA-style evaluation of Sunrise\'s achievement to date?', choices: ['The movement has comprehensively achieved its full Green New Deal agenda', 'The movement has produced real but partial social change — significant gains in awareness, discourse and electoral outcomes, despite not yet meeting Chenoweth\'s 3.5% participation threshold', 'The movement has produced no observable social change since 2017', 'The movement has primarily caused social regression on climate policy'], answer: 1, explanation: 'Nuanced evaluation acknowledges both real achievements (awareness, discourse, electoral wins) and the unmet ultimate goal — exactly the synthesis VCAA examiners reward.', unit: 4 },
];

